INSERT INTO "public"."bestiaire" ("id", "created_at", "nom", "nc", "type_creature", "taille", "is_custom", "stats", "combat", "attaques", "capacites", "data", "campaign_id", "image_url", "description") VALUES
	('4b4d247c-993e-4899-afae-b0b055726663', '2026-04-02 12:34:02.796996+00', 'Bandit vétéran', '1', 'Humanoïde', 'Moyenne', true, '{"agi": {"mod": 1, "sup": true}, "cha": {"mod": 0, "sup": false}, "con": {"mod": 3, "sup": false}, "for": {"mod": 2, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 0, "sup": true}, "vol": {"mod": 0, "sup": false}}', '{"pv": 15, "rd": 0, "pv_max": 15, "defense": 14, "initiative": 13, "attaque_magique": null}', '[{"mode": "Épée longue", "bonus": 4, "portee": null, "dommages": "1d8+2"}, {"mode": "Arc", "bonus": 3, "portee": "30 m", "dommages": "1d6"}]', '[{"nom": "EMBUSCADE", "description": "Au premier round de combat, si l''environnement permet de se dissimuler, la cible doit faire un test de PER difficulté 16 ou être surprise."}]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1781775197494-gw2fuxty6wk.jpg', NULL),
	('91277cee-b5a8-4cac-832c-b162d2f69d29', '2026-04-02 12:34:02.796996+00', 'Chef bandit', '2', 'Humanoïde', 'Moyenne', true, '{"agi": {"mod": 2, "sup": true}, "cha": {"mod": 2, "sup": false}, "con": {"mod": 3, "sup": false}, "for": {"mod": 3, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 0, "sup": true}, "vol": {"mod": 2, "sup": false}}', '{"pv": 25, "rd": 0, "pv_max": 25, "defense": 16, "initiative": 13, "attaque_magique": null}', '[{"mode": "Épée longue", "bonus": 6, "portee": null, "dommages": "1d8+3"}, {"mode": "Arc", "bonus": 5, "portee": "30 m", "dommages": "1d6+2"}]', '[{"nom": "EMBUSCADE", "description": "Au premier round de combat, si l''environnement permet de se dissimuler, la cible doit faire un test de PER difficulté 16 ou être surprise."}, {"nom": "ATTAQUE EN TRAÎTRE (L)", "description": "Si la créature attaque en même temps qu''un allié ou par surprise, elle obtient +1d4 DM."}, {"nom": "CHEF", "description": "Le chef bandit donne un bonus de +1 en Init., en attaque et aux DM à tous les bandits à portée de vue."}]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', NULL, NULL),
	('a5a2e2ef-b2b6-4fa5-afdf-cc4a681c9f1d', '2026-04-02 12:34:02.796996+00', 'Garde de la ville', '1', 'Humanoïde', 'Moyenne', true, '{"agi": {"mod": 0, "sup": false}, "cha": {"mod": 0, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 2, "sup": false}, "int": {"mod": -1, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 0, "sup": false}}', '{"pv": 15, "rd": 0, "pv_max": 15, "defense": 16, "initiative": 10, "attaque_magique": null}', '[{"mode": "Épée longue", "bonus": 4, "portee": null, "dommages": "1d8+2"}, {"mode": "Arbalète", "bonus": 4, "portee": "30 m", "dommages": "2d4"}]', '[]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', NULL, NULL),
	('c563f253-26a8-41fa-b46c-4204071ff50c', '2026-06-23 16:30:51.621342+00', 'Gobelin de base', '0', 'Animal Fantastique', 'Petite', true, '{"agi": {"mod": 2, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": -1, "sup": false}, "for": {"mod": -1, "sup": false}, "int": {"mod": -2, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": -2, "sup": false}}', '{"pv": 3, "rd": 0, "pv_max": 3, "defense": 12, "initiative": 13, "attaque_magique": null}', '[{"dm": "1d4-1", "attaque_base": "Arme +2"}]', '[{"nom": "Attaque en meute", "type": "passif", "description": "Lorsque au moins 2 gobelins attaquent la même cible en même temps, ils bénéficient d''un bonus de +2 en attaque (bonus qui peut s''ajouter à une éventuelle attaque groupée)"}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782232251007-fq6zptjta1t.jpg', 'Le gobelin "peau verte" est une petite créature à la peau grisâtre d''environ 1m de haut, cruelle, vicieuse et qui attaque en bande. Les gobelins sont généralement couards : blessés ou en sous-nombre, ils s''enfuient la plupart du temps.'),
	('88dfb0b6-32c2-4518-b493-33eca7896335', '2026-04-02 12:34:02.796996+00', 'Capitaine', '4', 'Humanoïde', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": 2, "sup": false}, "con": {"mod": 2, "sup": true}, "for": {"mod": 3, "sup": false}, "int": {"mod": 1, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 50, "rd": 0, "pv_max": 50, "defense": 18, "initiative": 10, "attaque_magique": null}', '[{"mode": "Épée longue (2 attaques)", "bonus": 8, "portee": null, "dommages": "1d8+3"}]', '[{"nom": "CAPITAINE", "description": "Le capitaine donne un bonus de +2 en initiative, en attaque et aux DM à toutes les créatures sous ses ordres à portée de vue."}, {"nom": "RIPOSTE", "description": "La créature peut effectuer une attaque en action gratuite contre chaque adversaire qui l''attaque à l''exception de celui qu''elle a elle-même choisi d''attaquer à son tour."}]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', NULL, NULL),
	('6e22fd2e-02b4-4876-b41e-de5345147697', '2026-07-30 20:30:25.134091+00', 'Zombie Humain', '1', 'Mort-Vivant', 'Moyenne', true, '{"agi": {"mod": -1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 2, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": -2, "sup": false}, "vol": {"mod": 6, "sup": false}}', '{"pv": 18, "rd": 0, "pv_max": 18, "defense": 10, "initiative": 8, "attaque_magique": null}', '[{"dm": "1d6 +3", "mode": "Attaque", "bonus": 4, "portee": null, "dommages": "1d6+3", "attaque_base": "Attaque +4"}]', '[{"nom": "RÉSISTANCE AUX DM", "description": "Divisez par deux tous les DM infligés au zombie par des armes, sauf s''il s''agit d''armes tranchantes."}, {"nom": "SANS ESPRIT", "description": "Aucune âme n''habite la carcasse morte, le zombie est immunisé à tous les sorts qui affectent l''esprit. L''INT et le CHA passent à -4, la VOL à +6."}, {"nom": "LENTEUR", "description": "Le zombie voit son AGI réduite à -1 et sa PER à -2, et il ne se déplace que de 5 m par action de mouvement."}, {"nom": "INSENSIBLE À LA DOULEUR", "description": "Ajoutez 3 x NC aux PV et retranchez 5 à la DEF. La créature peut encore faire une action (attaque ou mouvement) après avoir été réduite à 0 PV."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1785443567090-htx13i5yc4b.jpg', NULL),
	('25b60426-992b-4da1-bc7a-c9470f49e114', '2026-07-30 20:20:59.838243+00', 'Squelette de base', '1', 'Mort-Vivant', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 1, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": -1, "sup": false}, "vol": {"mod": 6, "sup": false}}', '{"pv": 9, "rd": 0, "pv_max": 9, "defense": 13, "initiative": 9, "attaque_magique": null}', '[{"dm": "1D6+1", "mode": "Épée", "bonus": 4, "portee": null, "dommages": "1d6+1", "attaque_base": "Epée +4"}]', '[{"nom": "SANS ESPRIT", "description": "Aucune âme n''habite la carcasse morte, le squelette est immunisé à tous les sorts qui affectent l''esprit."}, {"nom": "RÉSISTANCE AUX DM", "description": "Tous les DM infligés à un squelette avec des armes sont divisés par deux, sauf si l''attaquant utilise une arme contondante."}, {"nom": "RÉDUCTION DES DM DE FROID", "description": "Réduit de 5 tous les DM de froid reçus."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1785443530389-mkr59abe0pb.jpg', NULL),
	('16d237cb-d7e9-4d77-a96e-6eea7656d805', '2026-06-26 09:25:42.603071+00', 'Loup - Compagnon Animal', '1', 'Animal', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 1, "sup": true}, "for": {"mod": 2, "sup": false}, "int": {"mod": -3, "sup": false}, "per": {"mod": 2, "sup": true}, "vol": {"mod": 2, "sup": false}}', '{"pv": 16, "rd": 0, "pv_max": 16, "defense": 13, "initiative": 17, "attaque_magique": null}', '[{"dm": "1d4+2", "attaque_base": "Attaque magique du rôdeur"}]', '[]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782465940193-m32oyvzctp.jpg', 'Le rôdeur obtient un loup puor compagnon animal. En combat, le loup attaque en même temps que le rôdeur. Le loup comprend des ordres simples comme : garde, reste, apporte, attaque, etc.'),
	('c486084e-2fa6-4fd5-a124-58c7acb115e9', '2026-04-02 12:38:56.223646+00', 'Gobelin élite', '1', 'Animal Fantastique', 'Petite', true, '{"agi": {"mod": 2, "sup": true}, "cha": {"mod": -1, "sup": false}, "con": {"mod": 0, "sup": false}, "for": {"mod": 0, "sup": false}, "int": {"mod": -1, "sup": false}, "per": {"mod": 0, "sup": true}, "vol": {"mod": -1, "sup": false}}', '{"pv": 9, "rd": 0, "pv_max": 9, "defense": 13, "initiative": 13, "attaque_magique": null}', '[{"dm": "1d6", "mode": "Arme", "bonus": 4, "portee": null, "dommages": "1d6", "attaque_base": "Arme +4"}]', '[{"nom": "ATTAQUE EN MEUTE", "type": "passif", "description": "Lorsque au moins 2 gobelins attaquent la même cible en même temps, ils bénéficient d''un bonus de +2 en attaque (bonus qui peut s''ajouter à une éventuelle attaque groupée)."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782232362766-yn21vtzuu6o.jpg', NULL),
	('69220fdd-4817-481e-be49-876a23c079e3', '2026-04-02 12:37:35.153556+00', 'Ours brun', '4', 'Animal', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 6, "sup": true}, "for": {"mod": 6, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 1, "sup": false}}', '{"pv": 50, "rd": 0, "pv_max": 50, "defense": 18, "initiative": 12, "attaque_magique": null}', '[{"mode": "Morsure et griffes", "bonus": 10, "portee": null, "dommages": "2d6+6"}]', '[{"nom": "CHARGE (L)", "description": "La créature parcourt une distance maximale de 20 m et réalise une attaque avec un dé bonus. Si l''attaque est réussie, en plus des DM normaux, une victime de taille inférieure ou égale à la créature, doit faire un test de FOR difficulté 16 ou être renversée. Dans ce cas, la créature piétine (ou embroche) sa victime et les DM sont doublés."}, {"nom": "ENRAGÉ", "description": "Lorsqu''elle reçoit un coup critique, la créature devient enragée. Elle ignore les pénalités de douleur ou la peur, augmente de +3 sa valeur d''attaque au contact et ses DM de +1d4. Elle peut encore agir un tour complet après avoir atteint 0 PV."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782233098187-zl1gfnsnwd.jpg', NULL),
	('b758efec-d2b5-4e7a-bd70-7b492a622b64', '2026-04-02 12:38:56.223646+00', 'Chef Gobelin', '2', 'Animal Fantastique', 'Petite', true, '{"agi": {"mod": 2, "sup": true}, "cha": {"mod": 1, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 1, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 0, "sup": true}, "vol": {"mod": 0, "sup": false}}', '{"pv": 22, "rd": 0, "pv_max": 22, "defense": 16, "initiative": 13, "attaque_magique": null}', '[{"dm": "1d6+1", "mode": "Arme (2 attaques)", "bonus": 5, "portee": null, "dommages": "1d6+1", "attaque_base": "Arme(x2) +5"}]', '[{"nom": "ATTAQUE EN MEUTE", "type": "passif", "description": "Lorsque au moins 2 gobelins attaquent la même cible en même temps, ils bénéficient d''un bonus de +2 en attaque (bonus qui peut s''ajouter à une éventuelle attaque groupée)."}, {"nom": "SERGENT", "type": "passif", "description": "Une fois par round, le sergent peut donner une action supplémentaire à n''importe quel allié sous ses ordres à portée de vue (attaque ou mouvement). Une fois par combat, une attaque qui aurait dû amener le sergent à 0 PV est ignorée."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782232475327-zx82jcjb8z9.webp', NULL),
	('89bca241-6f79-49ae-b659-4f26815c8066', '2026-07-30 20:35:08.411972+00', 'Squelette géant', '4', 'Mort-Vivant', 'Grande', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 6, "sup": false}, "for": {"mod": 6, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": -2, "sup": false}, "vol": {"mod": 6, "sup": false}}', '{"pv": 60, "rd": 0, "pv_max": 60, "defense": 18, "initiative": 9, "attaque_magique": null}', '[{"dm": "2d8+6", "mode": "Massue à deux mains", "bonus": 9, "portee": null, "dommages": "2d8+6", "attaque_base": "Massue à deux mains +9"}]', '[{"nom": "SANS ESPRIT", "description": "Aucune âme n''habite la carcasse morte, le squelette est immunisé à tous les sorts qui affectent l''esprit."}, {"nom": "RÉSISTANCE AUX DM", "description": "Tous les DM infligés à un squelette avec des armes sont divisés par deux, sauf si l''attaquant utilise une arme contondante."}, {"nom": "RÉDUCTION DES DM DE FROID", "description": "Réduit de 5 tous les DM de froid reçus."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1785443707204-pul5p35v6pe.jpg', NULL),
	('100fa78d-6c0d-4607-a169-8b863527ec10', '2026-04-02 12:34:02.796996+00', 'Bandit de base', '1/2', 'Humanoïde', 'Moyenne', true, '{"agi": {"mod": 1, "sup": true}, "cha": {"mod": 0, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 1, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": -1, "sup": false}}', '{"pv": 9, "rd": 0, "pv_max": 9, "defense": 12, "initiative": 10, "attaque_magique": null}', '[{"mode": "Épée longue", "bonus": 2, "portee": null, "dommages": "1d8+1"}, {"mode": "Arc", "bonus": 2, "portee": "30 m", "dommages": "1d6"}]', '[{"nom": "EMBUSCADE", "description": "Au premier round de combat, si l''environnement permet de se dissimuler, la cible doit faire un test de PER difficulté 16 ou être surprise."}]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1781775132418-dn2rnx42w3o.jpg', NULL),
	('383c4d26-22b1-4956-9c78-27da9f980991', '2026-07-30 20:38:33.56289+00', 'Goule', '2', 'Mort-Vivant', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 1, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 19, "rd": 0, "pv_max": 19, "defense": 15, "initiative": 12, "attaque_magique": null}', '[{"dm": "1d6+2", "mode": "Morsure et griffes", "bonus": 5, "portee": null, "dommages": "1d6+2 + paralysie", "attaque_base": "Morsure et griffes +5"}]', '[{"nom": "PARALYSIE", "description": "Une créature blessée par la morsure d''une goule doit réussir un test de CON difficulté 10 ou être paralysée pendant 1d6 rounds."}, {"nom": "DEVENIR UNE GOULE", "description": "Une créature tuée par une goule en devient une à son tour au prochain crépuscule."}, {"nom": "FIÈVRE DES GOULES", "description": "À la fin du combat, si le personnage a été blessé au moins une fois par la morsure d''une goule, il doit réussir un test de CON difficulté 15 ou contracter la maladie. Chaque jour, il subit 1d4° DM retranchés directement à sa valeur de PV maximale (il ne peut plus dépasser cette nouvelle valeur) et doit faire un nouveau test de CON difficulté 15 pour vaincre la maladie. Lorsqu''il arrive à 0 PV, il meurt et se transforme en goule. S''il guérit, les PV perdus peuvent être récupérés normalement. Un sort de Délivrance (rang 3 de la voie de la spiritualité) peut mettre fin à la fièvre des goules."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1785443913291-a4p6hfsm3f8.jpg', NULL),
	('426543b6-05cd-45b2-9593-7f5a8ea76370', '2026-07-06 11:20:12.919369+00', 'Orque noir', '1', 'Animal Fantastique', 'Moyenne', true, '{"agi": {"mod": 0, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 3, "sup": false}, "for": {"mod": 3, "sup": true}, "int": {"mod": -2, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 1, "sup": false}}', '{"pv": 15, "rd": 0, "pv_max": 15, "defense": 15, "initiative": 10, "attaque_magique": null}', '[{"dm": "2d6+3", "attaque_base": "Arrme à 2 mains +4"}]', '[]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1783336810681-fx0horow698.jpg', 'Les orcs noirs sont en race d''orcs d''élite obtenue par sélection et reproduction par de puissants maîtres maléfiques souhaitant construire l''armée ultime. Leur peau est plus sombre et leur musculature plus imposante. Ils manient des armes à deux mains, mais surtout, ils ne sont plus sensibles à la lumières du jour'),
	('052da913-906e-4a05-aaa7-4d1c8a5bff64', '2026-07-06 11:36:40.967428+00', 'Chef Orque Noir', '6', 'Animal Fantastique', 'Moyenne', true, '{"agi": {"mod": 0, "sup": false}, "cha": {"mod": 1, "sup": true}, "con": {"mod": 5, "sup": false}, "for": {"mod": 5, "sup": true}, "int": {"mod": 0, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 60, "rd": 0, "pv_max": 60, "defense": 20, "initiative": 10, "attaque_magique": null}', '[{"dm": "2d6+5", "attaque_base": "Epée 2 mains (x2) +10"}]', '[{"nom": "Imparable", "type": "passif", "description": "Si la créature obtient 15-20 sur le d20 d''un test d''attaque, elle inflige +2d6 dm et l''attaque est automatiquement réussie (quelle que soit la DEF de son adversaire). Les dés bonus ne sont pas multiplié en cas de critique."}, {"nom": "Brise genou", "type": "action", "description": "Si un adversaire au contact tente de s''éloigner de la créature (généralement pour fuir), celle-ci obtient une attaque de contact gratuite contre lui. Si cette attaque est réussie, en plus des DM habituels, la cible doit réussi un test de CON DD15 ou diviser par deux ses déplacements pour le reste du combat."}, {"nom": "Capitaine", "type": "passif", "description": "Le capitaine donne un bonus de +2 en INIT, en attaque et aux DM à toutes les créatures sous ses ordres à portée de vue."}, {"nom": "Commandant", "type": "passif", "description": "Tant qu''au moins 4 créatures sous ses ordres sont à moins de 20m du commandant, il ne subit que la moitié des DM qui lui sont infligés"}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1783337799697-3qxyjzgfkhn.jpg', NULL),
	('c4b08be4-c3d7-47c1-b5f0-9cce4a7b81e4', '2026-04-02 12:40:49.402857+00', 'Ogre de base', '3', 'Animal Fantastique', 'Grande', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 6, "sup": false}, "for": {"mod": 6, "sup": true}, "int": {"mod": -2, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 0, "sup": false}}', '{"pv": 40, "rd": 0, "pv_max": 40, "defense": 17, "initiative": 10, "attaque_magique": null}', '[{"dm": "2d6+6", "mode": "Hachoir", "bonus": 7, "portee": null, "dommages": "2d6+6", "attaque_base": "Hâchoir +7"}]', '[{"nom": "Tape dur", "type": "passif", "description": "Si la créature obtient 15 à 20 au dé du test d''attaque, l''attaque est automatiquement réussie. De surcroît, la victime doit réussir un test de CON DD16 ou être étourdie pendant 1 round"}, {"nom": "Imparable", "type": "action_limitee", "description": "L''ordre réalise une attaque avec un dé bonus et garde le meilleur résultat. S''il obtient 15-20 au test d''attaque, il inflige +1d6 DM et l''attaque set automatiquement réussie (quelle que soit la DEF de son adversaire)"}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782231744235-5ez8gxsssju.jpg', NULL),
	('37201e11-113e-4d7b-be94-e187cc72bc95', '2026-07-13 14:26:14.344553+00', 'Zazarelle la Sorcière', '5', 'Animal Fantastique', 'Grande', true, '{"agi": {"mod": 2, "sup": false}, "cha": {"mod": -3, "sup": false}, "con": {"mod": 5, "sup": false}, "for": {"mod": 5, "sup": false}, "int": {"mod": 1, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 75, "rd": 0, "pv_max": 75, "defense": 17, "initiative": 15, "attaque_magique": null}', '[{"dm": "1d6 +5", "attaque_base": "Griffes +11"}, {"dm": "", "attaque_base": "Attaque magique +9"}]', '[{"nom": "Adaptation", "type": "passif", "description": "La sorcière nage parfaitement, de plus elle peut respirer sous l''eau ou même dans la vase"}, {"nom": "Camouflage", "type": "passif", "description": "La sorcière est une experte du camouflage, elle obtient un bonus de +5 à tous les test d''AGI"}, {"nom": "Peur", "type": "sort", "description": "La cible (portée 20m) doit réussir un test de VOL DD12 ou fuir pendant 1d4+1 tours (le MJ peut garder cette durée secrète)"}, {"nom": "Malédiction", "type": "sort", "description": "Effectuez un test d''attaque magique contre une cible à moins de 20mètres. En cas de succès, la victime réalise tous ses tests avec désavantage. Le sort prend fin dès qu''elle aura raté 3 tests. Si la cible possède une capacité lui permettant de lancer 2 dés et de garder le meilleur, elle ne lance plus qu''un seul dé."}, {"nom": "Saignement", "type": "sort", "description": "La sorcière doit réussir un test d''attaque magique (portée 10m). Du sang s''écoule de la bouche, du nez, des oreilles et même des yeux de la victime, qui subit 1d6 DM par tour pendant 5 tours. Le sort prend fin si la sorcière est vaincue."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1783952774862-7cgafhk5da.jpg', 'La sorcière n''est pas humaine, comme l''attestent sa taille, sa mâchoire proéminente, ses longs doigts crochus munis de griffes tranchantes et la couleur verte de sa peau'),
	('6e6942bf-9a08-4742-8755-4c63bcaa85b9', '2026-07-15 09:04:00.105955+00', 'Harpie', '4', 'Animal Fantastique', 'Moyenne', true, '{"agi": {"mod": 3, "sup": false}, "cha": {"mod": 4, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 1, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 0, "sup": false}}', '{"pv": 29, "rd": 0, "pv_max": 29, "defense": 16, "initiative": 16, "attaque_magique": null}', '[{"dm": "1D6 +3", "attaque_base": "Serres +5"}]', '[{"nom": "Vol rapide", "type": "action", "description": "La créature obtient une action de mouvement supplémentaire par tour lorsqu''elle est en vol. Au premier tour de combat, la créature obtient un bonus de +5 en attaque et +1d6 aux DM si elle est en vol et attaque une créature au sol"}, {"nom": "Chant captivant (L)", "type": "action_limitee", "description": "En chantant, une harpie peut fasciner une cible. Toutes les créatures humanoïdes dans un rayon de 30m doivent réussir un test de VOL DD10 ou succomber à la magie. Le chant affecte l''esprit. Ainsi, se boucher les oreilles ne permet pas d''être immunisé contre ce pouvoir mais apporte un bonus de +5 aux tests de  VOL. En revanche, se boucher les oreilles avec les mains remplace une action d''attaque à chaque tour). \nUne cible fascinée s''approche de la harpie et reste sans défense tant que la Harpie chante, puis pour encore un tour complet après la fin du chant. Une créature qui résiste au chant des harpies y est immunisée pour une durée de 1h. Une cible fascinée qui commence à se faire dévorer vivante bénéficie chaque tour d''un nouveau test de VOL DD10 pour se libérer de l''emprise."}, {"nom": "Chant choral (L)", "type": "action_limitee", "description": "Lorsqu''elles sont en nombre, les harpies peuvent s''associer pour produire un chant plus puissant. Les cibles potentielles ne font pas plusieurs tests de résistance, mais un seul test de VOL dont le DD est égale à 10+nb de harpies. Une créature fascinée s''approche de la harpie la plus proche d''elle. Les cibles restent fascinées tant qu''au moins une harpie chante."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1784106239189-445qa71iauw.jpg', 'La Harpie est une femme dont les bras sont des ailes et dont les pieds sont les serres puissantes d''un oiseau de proie. Elle est connue par son chant maléfique qui laisse ses victimes sans défense, offertes au pires tourments et à l''appétit de chair de la créature.'),
	('53016120-326a-4181-a022-3d81e4355b79', '2026-07-15 10:04:14.001276+00', 'Striges', '1', 'Animal Fantastique', 'Minuscule', true, '{"agi": {"mod": 3, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": -3, "sup": false}, "for": {"mod": -3, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 0, "sup": false}}', '{"pv": 2, "rd": 0, "pv_max": 2, "defense": 15, "initiative": 12, "attaque_magique": null}', '[{"dm": "1d4", "attaque_base": "Piqure +3"}]', '[{"nom": "Sucer le sang", "type": "action", "description": "Une strige qui réussit  son attaque s''aggripe à sa proie pour lui aspirer le sang et inflige ainsi 1d4 DM par tour. Lorsque la strige a infligé au moins 6DM de cette façon, elle se détache et fuit le combat. Une créature de taille normale est dès lors affaiblie pour 10min. Lorsqu''elle est fixée à sa proie, la strige possède une DEF de 12."}, {"nom": "Vol", "type": "action", "description": "La strige vole à une vitesse de 20 mètres par action de mouvement."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1784109853018-rz46bxrwjoc.jpg', 'La strige est une affreuse petite créature rougeâtre de 30 cm, croisement entre un moustique géant et une chauve-souris pourvue de quatre ailes. Elle possède également quatre pattes barbelées qui permettant de s’accrocher férocement à ses victimes pour leur sucer le sang.'),
	('23ccc684-4232-4369-b72c-df4d10dfc346', '2026-04-02 12:40:49.402857+00', 'Squelette de base', '1', 'Mort-Vivant', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 1, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": -1, "sup": false}, "vol": {"mod": 6, "sup": false}}', '{"pv": 9, "rd": 0, "pv_max": 9, "defense": 13, "initiative": 9, "attaque_magique": null}', '[{"mode": "Épée", "bonus": 4, "portee": null, "dommages": "1d6+1"}]', '[{"nom": "SANS ESPRIT", "description": "Aucune âme n''habite la carcasse morte, le squelette est immunisé à tous les sorts qui affectent l''esprit."}, {"nom": "RÉSISTANCE AUX DM", "description": "Tous les DM infligés à un squelette avec des armes sont divisés par deux, sauf si l''attaquant utilise une arme contondante."}, {"nom": "RÉDUCTION DES DM DE FROID", "description": "Réduit de 5 tous les DM de froid reçus."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782230639424-54v8bbjas5k.jpg', NULL),
	('426c5b03-ef77-4b0a-977e-3070cdf7f5a6', '2026-04-02 12:40:49.402857+00', 'Squelette géant', '4', 'Mort-Vivant', 'Grande', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 6, "sup": false}, "for": {"mod": 6, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": -2, "sup": false}, "vol": {"mod": 6, "sup": false}}', '{"pv": 60, "rd": 0, "pv_max": 60, "defense": 18, "initiative": 9, "attaque_magique": null}', '[{"dm": "2d8+6", "mode": "Massue à deux mains", "bonus": 9, "portee": null, "dommages": "2d8+6", "attaque_base": "Massue à deux mains +9"}]', '[{"nom": "SANS ESPRIT", "description": "Aucune âme n''habite la carcasse morte, le squelette est immunisé à tous les sorts qui affectent l''esprit."}, {"nom": "RÉSISTANCE AUX DM", "description": "Tous les DM infligés à un squelette avec des armes sont divisés par deux, sauf si l''attaquant utilise une arme contondante."}, {"nom": "RÉDUCTION DES DM DE FROID", "description": "Réduit de 5 tous les DM de froid reçus."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782230964027-b9p81t629xk.jpg', NULL),
	('81c70291-c3d2-4fa4-8f56-3a28d2937a4e', '2026-07-16 12:14:00.27178+00', 'Mésange Bleue', '0', 'Animal', 'Minuscule', true, '{"agi": {"mod": 3, "sup": true}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 0, "sup": false}, "for": {"mod": -4, "sup": false}, "int": {"mod": -2, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 5, "rd": 0, "pv_max": 5, "defense": 15, "initiative": 10, "attaque_magique": null}', '[]', '[]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1784204039064-3ygo90tvq1j.jpg', NULL),
	('d9a90cd1-da90-44a7-aea9-03804fc02ab8', '2026-07-13 12:31:47.418929+00', 'Cheval de guerre', '1', 'Animal', 'Moyenne', true, '{"agi": {"mod": 0, "sup": false}, "cha": {"mod": -1, "sup": false}, "con": {"mod": 4, "sup": true}, "for": {"mod": 5, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 0, "sup": false}}', '{"pv": 14, "rd": 0, "pv_max": 14, "defense": 11, "initiative": 10, "attaque_magique": null}', '[{"dm": "1D4+5", "attaque_base": "Ruade +4"}]', '[{"nom": "Monture", "type": "passif", "description": "La créature double sa FOR pour porter une charge. Un cheval de guerre est apte à porter une barde, un ensemble de protections pour lui. Un caparaçon de maille de augmente la DEF du de cheval de +2 pour un prix de 100PA. une barde de plaques de métal apporte un bonus de +4 en DEF pour un prix de 400PA. Les bardes font subir au cheval et à son cavalier un malus en Init égal  au bonus de DEF.\nLa DEF de la fidèle monture du chevalier (voie du cavalier rang1), tient déjà compte du bonus de DEF d''une éventuelle barde.\nEntant que PNJ, un cheval de guerre lourd pour un cavalier de haut niveau pourrait bénéficier d''un ou plusieurs rangs de boss."}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1783945908009-3fu4yaoc64s.jpg', 'Monture'),
	('4c5788a9-1de0-4e2d-ab0d-9078f5add7ac', '2026-07-15 13:20:17.466451+00', 'Lutin', '4', 'Animal Fantastique', 'Minuscule', true, '{"agi": {"mod": 5, "sup": false}, "cha": {"mod": 2, "sup": false}, "con": {"mod": -3, "sup": false}, "for": {"mod": -3, "sup": false}, "int": {"mod": 2, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 22, "rd": 0, "pv_max": 22, "defense": 22, "initiative": 22, "attaque_magique": null}', '[{"dm": "1+poison", "attaque_base": "Arc +10"}]', '[{"nom": "Invisibilité (L)", "type": "action_limitee", "description": "Le lutin peut se rendre invisible comme s''il utilisait la capacité de magicien du même nom. Ce lutin particulier doit dire 22 pour se rendre invisible."}, {"nom": "Poison", "type": "passif", "description": "Les flèches du lutin ne provoquent qu''un seul dm ,mais elles sont enduites de poison : test de CON DD26 ou être aveuglée (-5 initiative, attaque contact, magique et DEF, -10 attaque distance) pendant 5 minutes "}, {"nom": "Téléportation", "type": "action", "description": "Le lutin est capable de se téléporter de 20m par action de mouvement"}]', '{}', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1784121616110-7ela7wqq3kg.jpg', NULL),
	('5adfca34-02d0-4287-8523-43182eccb228', '2026-04-02 12:38:56.223646+00', 'Goule', '2', 'Mort-Vivant', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 1, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 19, "rd": 0, "pv_max": 19, "defense": 15, "initiative": 12, "attaque_magique": null}', '[{"dm": "1d6+2", "mode": "Morsure et griffes", "bonus": 5, "portee": null, "dommages": "1d6+2 + paralysie", "attaque_base": "Morsure et griffes +5"}]', '[{"nom": "PARALYSIE", "description": "Une créature blessée par la morsure d''une goule doit réussir un test de CON difficulté 10 ou être paralysée pendant 1d6 rounds."}, {"nom": "DEVENIR UNE GOULE", "description": "Une créature tuée par une goule en devient une à son tour au prochain crépuscule."}, {"nom": "FIÈVRE DES GOULES", "description": "À la fin du combat, si le personnage a été blessé au moins une fois par la morsure d''une goule, il doit réussir un test de CON difficulté 15 ou contracter la maladie. Chaque jour, il subit 1d4° DM retranchés directement à sa valeur de PV maximale (il ne peut plus dépasser cette nouvelle valeur) et doit faire un nouveau test de CON difficulté 15 pour vaincre la maladie. Lorsqu''il arrive à 0 PV, il meurt et se transforme en goule. S''il guérit, les PV perdus peuvent être récupérés normalement. Un sort de Délivrance (rang 3 de la voie de la spiritualité) peut mettre fin à la fièvre des goules."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782229989617-rg0hlk73yxa.jpg', NULL),
	('9ad8cc2a-9f4b-47ee-993b-083d6764f56d', '2026-04-02 12:37:35.153556+00', 'Araignée géante', '3', 'Animal Fantastique', 'Grande', true, '{"agi": {"mod": 4, "sup": true}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 3, "sup": true}, "for": {"mod": 3, "sup": true}, "int": {"mod": -4, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 0, "sup": false}}', '{"pv": 30, "rd": 0, "pv_max": 30, "defense": 17, "initiative": 12, "attaque_magique": null}', '[{"dm": "2d6+4", "mode": "Attaque", "bonus": 6, "portee": null, "dommages": "2d6+4 + poison (2d6, difficulté 12)", "attaque_base": "Morsure +6"}]', '[{"nom": "POISON MORTEL", "type": "passif", "description": "Le poison inflige 2d6 DM supplémentaires à la victime à chaque attaque. Si la victime réussit un test de CON de la difficulté indiquée, elle subit seulement la moitié des DM."}, {"nom": "VERMINE", "type": "passif", "description": "Une araignée géante peut encore agir un round complet lorsqu''elle atteint 0 PV. Une araignée se déplace de 15 m par action de mouvement."}, {"nom": "ARAIGNÉE CHASSEUSE", "type": "passif", "description": "Au premier round de combat, si l''environnement permet à la créature de se dissimuler, la cible doit faire un test de PER difficulté 19 ou être surprise. Si elle attaque avec succès une cible surprise, la créature inflige +1d4 DM et toute créature dont la FOR est inférieure à la sienne est renversée. La créature obtient un bonus de +5 à tous les tests de discrétion."}, {"nom": "TOILE (L)", "type": "action_limitee", "description": "Sur un test d''attaque réussi (portée 3 m), l''araignée emprisonne sa cible dans une toile gluante et solide. Elle est immobilisée; se libérer nécessite l''usage d''une action limitée et il faut réussir un test de FOR difficulté 12."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782233050125-xju5qq1m4p.jpg', 'Les araignées géantes sont des monstres terrifiants : rapides, puissants et capables de survivre aux pires blessures. On trouve les araignées géantes dans les forêts sombres et reculées, mais aussi dans les souterrains, surtout les plus grosses d''entre elles.'),
	('0c36eb0f-7a54-4048-b5da-13f0e7055d0c', '2026-04-02 12:40:49.402857+00', 'Troll', '5', 'Animal Fantastique', 'Grande', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 6, "sup": false}, "for": {"mod": 6, "sup": false}, "int": {"mod": -2, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 2, "sup": false}}', '{"pv": 70, "rd": 3, "pv_max": 70, "defense": 19, "initiative": 10, "attaque_magique": null}', '[{"dm": "1d6+6", "mode": "Griffes ou gourdin (2 ATTAQUES)", "bonus": 10, "portee": null, "dommages": "1D6+6", "attaque_base": "Griffes ou gourdin (x2) +10"}, {"dm": "2d6+6", "attaque_base": "Lancer de rocher +10 (10m)"}]', '[{"nom": "FAUCHAGE", "type": "passif", "description": "Sur 17 à 20 sur le d20 d''un test d''attaque, si l''attaque est réussie, la victime doit réussir au choix un test de FOR ou d''AGI difficulté 16 ou être renversée. La créature retranche 3 à tous les DM subis (RD 3)."}, {"nom": "VITALITÉ SURNATURELLE", "type": "passif", "description": "Un troll récupère 5 PV par tour, sauf si les DM subis sont de feu ou d''acide. Même à 0 PV, il continue à régénérer les tissus morts à moins qu''on ne brûle son corps ou si un PJ utilise une action limitée pour achever la créature."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782232817956-wk7mne0oj3.webp', 'Les trolls sont de grands humanoïdes de 2.70m à la peau caoutchouteuse verdâtre couverte d''excroissances et de champignons. Non seulement les armes rebondissent sur cette épaisse peau élasstique, mais en plus les blessures infligées se referment comme par magie. Aussi, le troll est un monstre dénué de peur confiant en sa capacité à échapper à la mort et il combat férocement. Les trolls parlent en général le noir parler. Ils vivent le plus souvent dans des endroits reculés : forêts profondes, marais nauséabonds.'),
	('bece6dc5-aaf1-42dc-b776-36d95c6e84f7', '2026-04-02 12:40:49.402857+00', 'Zombie Humain', '1', 'Mort-Vivant', 'Moyenne', true, '{"agi": {"mod": -1, "sup": false}, "cha": {"mod": -4, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 2, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": -2, "sup": false}, "vol": {"mod": 6, "sup": false}}', '{"pv": 18, "rd": 0, "pv_max": 18, "defense": 10, "initiative": 8, "attaque_magique": null}', '[{"dm": "1d6 +3", "mode": "Attaque", "bonus": 4, "portee": null, "dommages": "1d6+3", "attaque_base": "Attaque +4"}]', '[{"nom": "RÉSISTANCE AUX DM", "description": "Divisez par deux tous les DM infligés au zombie par des armes, sauf s''il s''agit d''armes tranchantes."}, {"nom": "SANS ESPRIT", "description": "Aucune âme n''habite la carcasse morte, le zombie est immunisé à tous les sorts qui affectent l''esprit. L''INT et le CHA passent à -4, la VOL à +6."}, {"nom": "LENTEUR", "description": "Le zombie voit son AGI réduite à -1 et sa PER à -2, et il ne se déplace que de 5 m par action de mouvement."}, {"nom": "INSENSIBLE À LA DOULEUR", "description": "Ajoutez 3 x NC aux PV et retranchez 5 à la DEF. La créature peut encore faire une action (attaque ou mouvement) après avoir été réduite à 0 PV."}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782229907048-wczzo5p1cc.jpg', NULL),
	('e6b0f6fc-05a6-4778-a3f7-bb3aa09f5793', '2026-06-19 11:36:17.583077+00', 'Brigand - Sbire', '1', 'Humanoïde', 'Moyenne', true, '{"agi": {"mod": 2, "sup": false}, "cha": {"mod": -1, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 2, "sup": false}, "int": {"mod": -1, "sup": false}, "per": {"mod": 1, "sup": false}, "vol": {"mod": 0, "sup": false}}', '{"pv": 9, "rd": 0, "pv_max": 9, "defense": 12, "initiative": 12, "attaque_magique": null}', '[{"dm": "1D6+2", "attaque_base": "Epée longue +2"}, {"dm": "1D6", "attaque_base": "Arc +2"}]', '[]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1781868977470-4tis0b2hjxg.jpg', NULL),
	('c4bf9495-a83d-4b29-b2a2-f34336ffbb92', '2026-06-19 15:05:30.115711+00', 'Pointe Noire - Chef des brigands', '2', 'Humanoïde', 'Moyenne', true, '{"agi": {"mod": 2, "sup": false}, "cha": {"mod": 1, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": 2, "sup": false}, "int": {"mod": 0, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 1, "sup": false}}', '{"pv": 15, "rd": 0, "pv_max": 15, "defense": 14, "initiative": 12, "attaque_magique": null}', '[{"dm": "1d6+3", "attaque_base": "Epée Longue +4"}, {"dm": "1d6", "attaque_base": "Arc +3"}]', '[{"nom": "Bretteur", "type": "action", "description": "Pointe Noire sait se battre contre plusieurs adversaires. Lorsqu''il effectue un test d''attaque, il peut viser 2 PJ. Le même jet compte contre les 2 adversaires, et doit dépasser la défense de chacun pour les toucher."}]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1781881529430-dnydp31d8vg.jpg', NULL),
	('76fd4a9f-5091-4f10-a859-8c64b6474e61', '2026-06-19 15:24:49.612857+00', 'Abomination', '5', 'Aberration', 'Grande', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": -1, "sup": false}, "con": {"mod": 3, "sup": false}, "for": {"mod": 4, "sup": false}, "int": {"mod": -1, "sup": false}, "per": {"mod": -1, "sup": false}, "vol": {"mod": 1, "sup": false}}', '{"pv": 20, "rd": 0, "pv_max": 20, "defense": 14, "initiative": 10, "attaque_magique": null}', '[{"dm": "1d6+3", "attaque_base": "Mains nues +4"}]', '[{"nom": "Charge", "type": "action", "description": "Lorsque l''abomination n''est pas au contact, elle peut courir et charger un PJ. Si elle réussit son attaque, en plus des PV perdus, le PJ tombe au sol.\nPour reprendre le combat, il devra utiliser sa prochaine action d''attaque pour se relever (et ne pourra donc pas attaquer)"}]', '{}', '235d5097-053a-43b3-9bf1-929887e107ac', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1781882689195-wxfk2t2zrkd.jpg', NULL),
	('d2954bee-65f0-40c2-899f-5975debe65d4', '2026-06-23 15:42:25.417805+00', 'Sigméus le Nécromant', '5', 'Mort-Vivant', 'Moyenne', true, '{"agi": {"mod": 1, "sup": false}, "cha": {"mod": 1, "sup": false}, "con": {"mod": 1, "sup": false}, "for": {"mod": -1, "sup": false}, "int": {"mod": 3, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 3, "sup": false}}', '{"pv": 32, "rd": 0, "pv_max": 32, "defense": 22, "initiative": 16, "attaque_magique": null}', '[{"dm": "1d6+5", "attaque_base": "Main spectrale +12"}]', '[{"nom": "Effroi", "type": "sort", "description": "Lors du premier tour de combat, tous les adversaires du nécromant font un test de VOL difficulté 10. Ceux qui échouent ne peuvent pas l’attaquer pendant 1d4 tours."}, {"nom": "Baiser du vampire", "type": "action_limitee", "description": "Le nécromant effectue une attaque contre un adversaire engagé au contact. S’il réussit, il lui inflige 2d6 points de dégâts et récupère 2d6 pv perdus !"}]', '{}', '4afd8b4f-06c2-4432-823e-743464d27432', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782229344865-k7v1gdabadg.png', 'Sous une robe sombre d’un autre âge, une créature squelettique vous contemple de toute sa hauteur.');
