	('f540fe7a-570c-432b-9dda-71609902d5e5', '2026-04-29 12:20:00.403444+00', 'Torches (x3)', 'Matériel', '1 pa', false, '{"rarete": "Commun"}', NULL, NULL),
	('c3a3010e-c2e9-46c2-bdfd-650fa7c1133e', '2026-04-29 12:20:21.000897+00', 'Outils de crochetage', 'Matériel', '5 pa', false, '{"rarete": "Commun"}', NULL, NULL),
	('c03775ad-9308-4980-a278-7030d4049afe', '2026-04-29 12:20:56.917826+00', 'Potions de Soins', 'Potion', '10 pa', false, '{"rarete": "Commun", "description": "1d4° PV"}', NULL, NULL),
	('132d5812-489d-4b20-aca4-dbb037b74481', '2026-04-29 12:21:19.738737+00', 'Ration', 'Matériel', '4 pa', false, '{"rarete": "Commun", "description": "1 semaine"}', NULL, NULL),
	('29465c5e-0613-4589-ab20-1840c1e6f019', '2026-04-29 12:21:39.428452+00', 'Sac à dos', 'Matériel', '1 pa', false, '{"rarete": "Commun"}', NULL, NULL),
	('43cf5ace-6208-4013-abf3-48359a9ea3de', '2026-05-22 15:10:36.120595+00', 'Ceinture de géant', 'Accessoire', '100 po', false, '{"rarete": "Rare"}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1779462637158-jdsrzrovrrq.jpg', NULL),
	('c705ea38-469d-489b-8fa9-ee70651cab14', '2026-06-18 10:26:50.925619+00', 'Coffre de 50 PO', 'Autre', '50 po', true, '{"rarete": "Commun"}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1781778410512-yuwxzfourlq.jpg', '235d5097-053a-43b3-9bf1-929887e107ac'),
	('4e593a0b-677a-4573-8098-214add52abd8', '2026-06-18 10:28:19.599647+00', 'Lettre de recommandation', 'Parchemin', NULL, true, '{"rarete": "Commun"}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1781778499208-tmdt5cbdafo.jpg', '235d5097-053a-43b3-9bf1-929887e107ac'),
	('6fc66c43-f88f-4b65-96a4-202e168d8a80', '2026-06-19 10:55:13.475874+00', 'Parchemin', 'Autre', NULL, false, '{"rarete": "Commun", "description": "y est écrit  : \"En cas de problème, allez vous plaindre de la grêle au dragon\""}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1781866514078-g60e5zahhyk.jpg', NULL),
	('fe772a80-08d1-49f0-923b-ae2f118839a3', '2026-06-23 11:52:43.26138+00', 'Craie', 'Autre', '1PA', false, '{"rarete": "Commun"}', NULL, NULL),
	('d288b85e-a0c6-41b1-9fc4-3116ed37ced2', '2026-06-23 11:53:16.558949+00', 'Menottes en acier', 'Accessoire', '2 PA', false, '{"rarete": "Commun"}', NULL, NULL),
