	('10adeb40-6c62-418e-b7d5-10180d0f0bf7', '2026-06-23 15:12:16.168558+00', 'Sort de cécité', 'Parchemin', '100 PA', false, '{"rarete": "Rare", "description": "Action Limitée - Attaque magique contre un adversaire, si elle réussit, ce dernier perd la vue pendant 2 tours. Un adversaire aveugle subit un malus de -5 à la DEF et à tous ses tests d''attaque et de dégâts."}', NULL, NULL),
	('23750942-95e4-4651-a9bf-36679ad294ac', '2026-07-13 12:50:49.838703+00', 'Potion de soins supérieure', 'Potion', '30po', false, '{"rarete": "Commun", "description": "2d8+15 PV"}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1783947050994-3uun5wuv0vw.jpg', NULL),
	('0ac7b937-4a83-4abc-955b-946e4ea749fa', '2026-07-13 14:52:24.224564+00', 'Potion d''invisibilité', 'Potion', NULL, false, '{"rarete": "Commun", "description": "Boire la potion provoque le même effet que la capacité de magicien du même nom : la cible se rend invisible pendant 1d4+INT minutes. Une fois invisible, personne ne peut plus détecter sa présence ou lui porter d''attaque directe. Si la cible attaque, elle redevient visible."}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1783954345050-c5lhyk9z1w.jpg', NULL),
	('8e32069c-74cb-4ed3-8fdf-5212bbfe4448', '2026-07-15 10:28:06.639054+00', 'Talisman Scorpion', 'Artefact', '50 Po', true, '{"rarete": "Commun", "description": "Cet objet vient du désert des Morteroches. Il est magique et son porteur obtient un bonus de +5 pour résister aux tests de poison et divise par deux l''effet de celui-ci"}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1784111286352-ah2vwctcnje.jpg', 'c57e1f84-52a5-4f4b-945a-40c47977adae'),
	('68bdee79-b08a-4b74-ad74-39f17769d6b8', '2026-07-15 12:34:18.892141+00', 'Bracelets aquatiques', 'Artefact', '15 PO', false, '{"rarete": "Rare", "description": "Bracelets en argent, offrent une DEF +2 à un personnage sans armure et permettent de respirer sous l''eau pendant 5 minutes par jour."}', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/equipements/1784118857800-uhxs58bv5yk.jpg', NULL),
