	('b9a375f7-0c10-4b1c-b599-347dc2497556', 'a2a9cc38-039d-489b-b15a-217f24ca93a7', NULL, '16d237cb-d7e9-4d77-a96e-6eea7656d805', 'Loup - Compagnon Animal', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782465940193-m32oyvzctp.jpg', 'Fenn', 16, 16, NULL, '2026-06-26 09:31:31.701033+00', '{"nc": "1", "nom": "Fenn", "stats": {"agi": {"mod": 1, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 1, "sup": true}, "for": {"mod": 2, "sup": false}, "int": {"mod": -3, "sup": false}, "per": {"mod": 2, "sup": true}, "vol": {"mod": 2, "sup": false}}, "combat": {"pv": 16, "rd": 0, "pv_max": 16, "defense": 13, "initiative": 17, "attaque_magique": null}, "taille": "Moyenne", "attaques": [{"dm": "1d4+2", "attaque_base": "Attaque magique du rôdeur"}], "capacites": [], "image_url": "https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782465940193-m32oyvzctp.jpg", "is_custom": false, "campaign_id": null, "description": "Le rôdeur obtient un loup puor compagnon animal. En combat, le loup attaque en même temps que le rôdeur. Le loup comprend des ordres simples comme : garde, reste, apporte, attaque, etc.", "type_creature": "Animal"}', NULL),
	('e875ea31-f0d1-4720-aa80-fe0fdea45072', NULL, 'e1d9af04-5355-4d6d-9710-99b11ae679b0', 'd9a90cd1-da90-44a7-aea9-03804fc02ab8', 'Cheval de guerre', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1783945908009-3fu4yaoc64s.jpg', NULL, 14, 14, NULL, '2026-07-13 12:32:00.04066+00', '{"nc": "1", "nom": "Cheval de guerre", "stats": {"agi": {"mod": 0, "sup": false}, "cha": {"mod": -1, "sup": false}, "con": {"mod": 4, "sup": true}, "for": {"mod": 5, "sup": false}, "int": {"mod": -4, "sup": false}, "per": {"mod": 0, "sup": false}, "vol": {"mod": 0, "sup": false}}, "combat": {"pv": 14, "rd": 0, "pv_max": 14, "defense": 11, "initiative": 10, "attaque_magique": null}, "taille": "Moyenne", "attaques": [{"dm": "1D4+5", "attaque_base": "Ruade +4"}], "capacites": [{"nom": "Monture", "type": "passif", "description": "La créature double sa FOR pour porter une charge. Un cheval de guerre est apte à porter une barde, un ensemble de protections pour lui. Un caparaçon de maille de augmente la DEF du de cheval de +2 pour un prix de 100PA. une barde de plaques de métal apporte un bonus de +4 en DEF pour un prix de 400PA. Les bardes font subir au cheval et à son cavalier un malus en Init égal  au bonus de DEF.\nLa DEF de la fidèle monture du chevalier (voie du cavalier rang1), tient déjà compte du bonus de DEF d''une éventuelle barde.\nEntant que PNJ, un cheval de guerre lourd pour un cavalier de haut niveau pourrait bénéficier d''un ou plusieurs rangs de boss."}], "description": "Monture", "type_creature": "Animal"}', NULL),
	('9c8e011b-030b-4cfd-8535-6693cf90d2b6', '4a492bb7-2790-42db-95ca-fa0bdbad6043', NULL, '81c70291-c3d2-4fa4-8f56-3a28d2937a4e', 'Mésange Bleue', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1784204039064-3ygo90tvq1j.jpg', NULL, 5, 5, NULL, '2026-07-16 12:14:08.531036+00', '{"nc": "0", "nom": "Mésange Bleue", "stats": {"agi": {"mod": 3, "sup": true}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 0, "sup": false}, "for": {"mod": -4, "sup": false}, "int": {"mod": -2, "sup": false}, "per": {"mod": 2, "sup": false}, "vol": {"mod": 2, "sup": false}}, "combat": {"pv": 5, "rd": 0, "pv_max": 5, "defense": 15, "initiative": 10, "attaque_magique": null}, "taille": "Minuscule", "attaques": [], "capacites": [], "description": "", "type_creature": "Animal"}', NULL),
