	('2942ad76-c372-4dfd-b5db-04e87de572cb', '4f3184ea-1710-462c-8887-dd32de8f68f0', NULL, '16d237cb-d7e9-4d77-a96e-6eea7656d805', 'Loup - Compagnon Animal', 'https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782465940193-m32oyvzctp.jpg', 'Fenn', 16, 20, NULL, '2026-07-16 17:56:44.493468+00', '{"nc": "1", "nom": "Fenn", "stats": {"agi": {"mod": 1, "sup": false}, "cha": {"mod": -2, "sup": false}, "con": {"mod": 1, "sup": true}, "for": {"mod": 2, "sup": false}, "int": {"mod": -3, "sup": false}, "per": {"mod": 2, "sup": true}, "vol": {"mod": 2, "sup": false}}, "combat": {"pv": 20, "rd": 0, "pv_max": 20, "defense": 15, "initiative": 14, "attaque_magique": null}, "taille": "Moyenne", "attaques": [{"dm": "1d4+2", "attaque_base": "Attaque +6"}], "capacites": [{"nom": "Travail d''équipe", "type": "passif", "description": "Lorsque le loup et le rôdeur sont au contact, le loup obtient un dé bonus en attaque et le rôdeur obtient un dé bonus aux tests effectués pour pister ou pour éviter d''être surpris"}], "image_url": "https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/compendium/bestiaire/1782465940193-m32oyvzctp.jpg", "is_custom": false, "campaign_id": null, "description": "Le rôdeur obtient un loup pour compagnon animal. En combat, le loup attaque en même temps que le rôdeur. Le loup comprend des ordres simples comme : garde, reste, apporte, attaque, etc.", "type_creature": "Animal"}', NULL);
