INSERT INTO "public"."voies" ("id", "created_at", "nom", "type", "peuple_id", "profil_id", "is_custom", "capacites", "campaign_id", "famille_id", "notes") VALUES
	('150b0f3a-d91a-45f6-bda1-9aaf897ddcdd', '2026-04-02 09:22:11.092695+00', 'Voie de l''assassin', 'famille', NULL, 'f325015e-9aaa-486d-a5a1-ad4ef845de78', false, '{"rang1": {"bonus": [{"type": "Tests discrétion, et déguisement", "titre": "", "valeur": "Rang+2", "condition": "Le voleur ajoute son rang + 2 à tous les tests de discrétion, de déguisement ou pour cacher une arme sur lui."}, {"type": "Attaque", "titre": "", "valeur": "+dé bonus", "condition": "Le voleur obtient un dé bonus en attaque lorsqu’il attaque un adversaire surpris."}], "titre": "Discrétion", "actions": null, "legacies": null, "capacites": [{"titre": "Argotien", "description": "Le voleur apprend le langage silencieux à base de signe des voleurs (argotien)."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Attaque sournoise", "actions": [{"dm": "+2D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, quand il attaque un adversaire surpris ou qui lui tourne le dos avec une arme légère, le voleur inflige +2d4° DM supplémentaires. Les DM infligés par cette capacité augmentent de 1d4° à  chaque fois qu’il atteint le rang 4 dans une voie de voleur (pour un maximum de 7d4°). Cette capacité nécessite l’utilisation d’une arme légère (dague, éventuellement lancée, épée courte, rapière) dans tous les autres cas, le bonus aux DM est divisé par deux (cela comprend les armes à distance).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Attaque par surprise", "actions": [{"dm": "+2D4°", "sort": false, "type": "A", "titre": "", "cout_mana": "", "test_type": "", "description": "Contre un adversaire surpris, le voleur peut réaliser une attaque sournoise en utilisant une action d’attaque plutôt qu’une action limitée et il augmente les DM de son attaque sournoise de 2d4°.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Disparition ", "actions": [{"dm": "", "sort": false, "type": "M", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le voleur peut disparaître dans un flash lumineux et un nuage de fumée. Aucun adversaire ne peut l’attaquer pendant qu’il a disparu, mais il peut subir des DM de zone. Il ne réapparaît qu’au début de son prochain tour à une distance maximale de 20 m de sa position initiale. À ce moment, si le voleur a l’initiative, il peut réaliser une attaque sournoise.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Ouverture mortelle ", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le voleur obtient une réussite critique automatique contre la cible de son choix. Il profite donc d’une réussite automatique, des dommages multipliés par 2 prévus dans ce cas et d’une attaque sournoise (dont les DM ne sont pas doublés). ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('57c6f0f8-0166-4702-8023-0e15da3eb780', '2026-04-02 09:25:28.601201+00', 'Voie du spadassin', 'famille', NULL, 'f325015e-9aaa-486d-a5a1-ad4ef845de78', false, '{"rang1": {"bonus": [{"type": "Initiative", "titre": "", "valeur": "+AGI", "condition": ""}, {"type": "Tests intimidation", "titre": "", "valeur": "Rang+2", "condition": ""}], "titre": "Attaque en finesse", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le voleurpeut remplacer sa FOR par son AGI pour ses tests d’attaque au contact (mais pas aux DM) lorsqu’il utilise une arme légère à une main (dague, épée courte ou rapière)."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Esquive fatale", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le voleur peut esquiver une attaque et s’arranger pour que celle‐ci affecte un autre adversaire à son contact. Comparez le test d’attaque à la DEF de la nouvelle cible pour savoir si celle‐ci subit des DM. Cette capacité ne peut pas être utilisée si le voleur n’a qu’un seul adversaire au contact et jamais contre une réussite critique (un critique touche toujours sa cible).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "Critique", "titre": "", "valeur": "+2", "condition": "Par sa science de l’escrime (et de la fourberie), le voleur augmente ses chances de faire des coups critiques avec une arme légère de 2 points (ainsi, au lieu de 20, le critique standard  est obtenu entre 18 et 20). Toutefois, la valeur minimale requise pour obtenir un critique ne peut être inférieure à 16 ."}], "titre": "Frappe chirurgicale", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Ambidextrie (G)", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Avec sa main gauche, le voleur peut effectuer une attaque au contact gratuite avec une dague ou une épée courte à chaque round. Cette attaque ne peut pas bénéficier des avantages d’une attaque sournoise.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Botte secrète", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Lorsque le voleur obtient un critique sur le dé d’une attaque au contact de sa main principale avec une arme légère (mais pas sur une ouverture mortelle), il inflige à sa cible un état préjudiciable au choix parmi affaibli, aveuglé, étourdi, immobilisé ou ralenti pendant 1 round. Vous ne pouvez infliger chaque état préjudiciable qu’une seule fois par combat. Alternativement, le voleur peut choisir que l’attaque devienne une attaque sournoise dont les DM s’ajoutent au critique (au lieu d’infliger un état préjudiciable)."}], "familiers": null}}', NULL, NULL, NULL),
	('36bd204f-bff6-4bb7-9d92-14e35062dfc9', '2026-04-02 09:44:31.542099+00', 'Voie du primitif', 'famille', NULL, 'b12e8437-9f7e-4d3b-b55d-beaf048e8e50', false, '{"rang1": {"bonus": [{"type": "Tests survie", "titre": "", "valeur": "+2", "condition": "Le barbare ajoute son rang + 2 à ses tests de survie (dont les tests de récupération) et de discrétion en milieu naturel."}, {"type": "PV", "titre": "", "valeur": "+1", "condition": "Le barbare gagne 1 PV supplémentaire."}], "titre": "Proche de la nature", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+2", "condition": "Lorsqu’il ne porte aucune armure, le barbare peut se relever par une action de mouvement et il obtient +2 en DEF. Ce bonus passe à +3 au rang 5. S’il porte une armure, il gagne seulement +1 en DEF."}], "titre": "Armure de vent", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "Tests PER", "titre": "", "valeur": "+2", "condition": "Le barbare possède des sens très affûtés, il est difficile de le surprendre, il ajoute son rang + 2 à tous les tests effectués pour détecter les pièges mécaniques, magiques (ses poils se hérissent) ou les embuscades. "}], "titre": "Vigilance", "actions": null, "legacies": null, "capacites": [{"titre": "Immunité", "description": "Il devient immunisé aux Attaques sournoises d’un voleur ou à toute capacité similaire d’une créature de niveau inférieur au sien."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Résistance à la magie", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Le barbare devient capable de résister à la magie. Lorsqu’il est la cible d’un sort, une fois par round, il peut faire un test d’attaque magique* opposé à celui du sort (si le sort n’en demande pas, faites‐en tout de même un à cette occasion). En cas de réussite, il n’en subit pas les effets.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Vitalité débordante", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le barbare guérit à une vitesse presque surnaturelle. Tant que son niveau actuel de PV est compris entre 1 et un tiers de son maximum, il récupère 1d4° PV par heure, de nuit comme de jour. * Si le personnage est un profil hybride est qu’il est capable de faire de la magie (il possède au moins une capacité de sort), il subit un dé malus sur ce test opposé. Avoir cédé à la magie le rend moins apte à y résister."}], "familiers": null}}', NULL, NULL, NULL),
	('b124e353-1a89-4e9a-8b72-c37320c2ab6c', '2026-04-02 09:25:28.601201+00', 'Voie de l''archer', 'famille', NULL, '69a984cb-e7d2-4f98-b109-69536f32a6b4', false, '{"rang1": {"bonus": [{"type": "DM", "titre": "", "valeur": "PER+1", "condition": "Le rôdeur ajoute sa PER aux DM qu’il inflige à l’arc et +1 par rang dans la voie en initiative. Le joueur peut souhaiter une variante de cette capacité s’appliquant aux armes de jet (dague, hachette, javelot) plutôt qu’à l’arc (rebaptisez‐la voie du lancer). Dans ce cas, le PJ ajoute sa FOR aux DM qu’il inflige et double la portée de jet (pas de bonus d’Init.). Par ailleurs, toutes les capacités de la voie qui suivent s’appliquent aux armes de jet plutôt qu’à l’arc."}], "titre": "Archer émérite", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Tir chirurgical", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le rôdeur peut tirer sur une cible engagée en mêlée sans pénalité (mais pas sur une cible à couvert). Il ne risque jamais de toucher un allié, même en cas d’échec critique."}], "familiers": null}, "rang3": {"bonus": [{"type": "DM", "titre": "", "valeur": "+2D4°", "condition": "Pour une attaque à distance, le rôdeur peut choisir de s’imposer un dé malus en attaque. Si elle est réussie, il ajoute 2d4° aux DM. Cette capacité peut être utilisée avec Tir rapide ou Flèche de mort par exemple. \n"}], "titre": "Dans le mille", "actions": [{"dm": "+3D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Pour une attaque à distance, le rôdeur peut choisir de s’imposer un dé malus en attaque. Si elle est réussie, il ajoute 3d4° aux DM. \n", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Tir rapide", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le rôdeur peut faire deux attaques à distance pendant son tour avec un malus de ‐2.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Flèche de mort (L)", "actions": [{"dm": "+1D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Vous obtenez un dé bonus en attaque à distance et vous ajoutez 1d4° aux DM. Au lieu du dé bonus et de +1d4° aux DM, vous pouvez infliger un état préjudiciable de votre choix parmi aveuglé, affaibli, ralenti ou immobilisé pendant 1 round à une cible d’un NC inférieur au vôtre. Vous ne pouvez infliger chaque état préjudiciable qu’une seule fois par combat.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('9b85fe8d-f599-4bd3-9a00-387bbb17ebf8', '2026-04-02 09:44:31.542099+00', 'Voie de la brute', 'famille', NULL, 'b12e8437-9f7e-4d3b-b55d-beaf048e8e50', false, '{"rang1": {"bonus": [{"type": "max PV", "titre": "", "valeur": "+FOR", "condition": "Le barbare ajoute sa FOR à son maximum de PV "}, {"type": "Test éloquence", "titre": "", "valeur": "+FOR", "condition": "Le barbare ajoute sa FOR à ses tests de CHA et à ceux de ses alliés au contact pour les tests de négociation, de persuasion ou d’intimidation. Allez savoir pourquoi, sa simple présence donne de la force aux arguments de ses alliés..."}], "titre": "Argument de taille", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Tour de force", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Le barbare peut temporairement décupler ses ressources physiques pour faire usage d’une force prodigieuse. Il obtient un bonus de +10 sur un test de FOR (pas un jet de DM ou un test d’attaque), mais cela lui coûte 1d4° PV (à décider avant de lancer les dés). Enfin, le barbare peut désormais porter une chemise de mailles et utiliser toutes les capacités des voies de barbare auparavant autorisées avec une armure de cuir renforcé.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Attaque brutale", "actions": [{"dm": "+1D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le barbare effectue une puissante attaque au contact qui inflige +1d4° aux DM. À la place, il peut choisir de s’imposer un malus de ‐3 au test d’attaque pour obtenir +2d4° aux DM. Sur une attaque brutale réussie, il peut sacrifier 1d4° DM pour faire reculer de 3 m un adversaire de NC inférieur au rang atteint dans la voie, ou sacrifier 2d4° DM pour le renverser.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "FOR", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests FOR", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Force héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "Critique", "titre": "", "valeur": "+1", "condition": "Le barbare augmente de 1 point les chances d’obtenir un critique sur les attaques au contact (par exemple 19‐20 au lieu de 20). Lorsqu’il obtient un critique sur une attaque au contact, en plus des DM doublés, la cible est étourdie pendant 1 round."}], "titre": "Briseur d’os", "actions": null, "legacies": null, "capacites": [{"titre": "Maîtrise", "description": " Le barbare peut désormais porter une cotte de mailles et utiliser toutes les capacités des voies de barbare auparavant autorisées avec une chemise de mailles."}], "familiers": null}}', NULL, NULL, NULL),
	('a2f99fbc-24d6-488f-8a5c-e9a69ffcb44a', '2026-04-02 09:44:31.542099+00', 'Voie du pourfendeur', 'famille', NULL, 'b12e8437-9f7e-4d3b-b55d-beaf048e8e50', false, '{"rang1": {"bonus": [{"type": "Tests esquive", "titre": "", "valeur": "Rangs+2", "condition": "Le barbare ajoute son rang + 2 à tous les tests d’AGI destinés à esquiver (Explosion de feu, souffle, pièges, etc.). "}, {"type": "Initiative", "titre": "", "valeur": "+3", "condition": ""}, {"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le bonus de DEF passe à +2 au rang 5."}], "titre": "Réflexes éclair", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Charge", "actions": [{"dm": "+1D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le barbare se déplace en ligne droite entre 5 m et 10 m et effectue une attaque au contact avec un dé bonus et +1d4° aux DM. Il ne peut pas lancer une charge s’il est au contact d’un adversaire.Le barbare se déplace en ligne droite entre 5 m et 10 m et effectue une attaque au contact avec un dé bonus et +1d4° aux DM. Il ne peut pas lancer une charge s’il est au contact d’un adversaire.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Enchaînement", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Chaque fois que le barbare réduit un adversaire à 0 PV avec une attaque de contact, il bénéficie d’une action d’attaque gratuite sur un autre adversaire à son contact. Enchaînement ne peut pas être cumulé à un déchaînement d’acier ou une attaque tourbillon."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Déchaînement d’acier", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le barbare parcourt 10 m en ligne droite en dépassant autant d’ennemis qu’il le souhaite. Il porte une attaque avec un malus de ‐2 à chaque adversaire sur son passage. Il doit traverser l’espace occupé par ceux‐ci pour porter un coup, mais il ne peut terminer son déplacement à un endroit occupé par un ennemi.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Attaque tourbillon (L)", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le barbare tourne sur lui‐même en assénant des attaques à toutes les cibles au contact. Il inflige automatiquement des DM correspondant à l’arme utilisée (plus tous les bonus habituels) à toutes les cibles dans un rayon de 5 m autour de lui.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('b57e7466-207e-414f-95bb-c6c11c641a71', '2026-04-02 09:44:31.542099+00', 'Voie du pagne', 'famille', NULL, 'b12e8437-9f7e-4d3b-b55d-beaf048e8e50', false, '{"rang1": {"bonus": [{"type": "Tests athlétisme", "titre": "", "valeur": "Rang+2", "condition": "Le barbare est un athlète capable de prouesses physiques extraordinaires, il ajoute son rang + 2 aux tests de course, de saut ou d’escalade. "}, {"type": "PV/rang", "titre": "", "valeur": "+1", "condition": "De plus, il gagne 1 PV supplémentaire par rang atteint dans la voie."}], "titre": "Vigueur", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Peau de pierre", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le barbare est particulièrement endurci, il encaisse les coups plutôt que de les esquiver. Il peut choisir de remplacer son AGI par sa CON pour calculer sa DEF (la limitation du bonus maximal en fonction de l’armure portée s’applique toujours, mais cette fois elle s’applique à la CON). Autrement (si son AGI est supérieure ou égale à sa CON), il reçoit +1 en DEF et ce bonus passe à +2 au rang 4."}], "familiers": null}, "rang3": {"bonus": [{"type": "Choix", "titre": "", "valeur": "+3", "condition": "Le barbare possède un tatouage magique* qui améliore ses performances physiques ou mentales. Au choix : Taureau (+3 aux tests de FOR), ours (+3 aux tests de CON), panthère (+3 aux tests d’AGI), chouette (+3 aux tests de PER), loup (+3 aux tests de CHA), renard (+3 aux tests d’INT) ou serpent (+3 aux tests de VOL). De plus, lorsqu’il subit l’état étourdi, il est seulement ralenti."}], "titre": "Tatouages", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "CON", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests de CON", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Constitution héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Peau d’acier", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le barbare ne sent plus la douleur et ignore les égratignures, il réduit tous les DM subis de 3 points (RD 3). Une attaque lui inflige toujours au minimum 1 DM. * Ce bonus n’est pas un bonus de compétence, mais un bonus de magie qui ne peut donc pas se cumuler à un bonus fourni par un objet magique."}], "familiers": null}}', NULL, NULL, NULL),
	('bff60aa4-7c09-437f-b309-c86b3b150439', '2026-04-02 09:44:31.542099+00', 'Voie du cavalier', 'famille', NULL, '13a28973-6eb6-4cfb-9aef-d2ed5e76d3da', false, '{"rang1": {"bonus": null, "titre": "Fidèle monture", "actions": null, "legacies": null, "capacites": null, "familiers": [{"titre": "Cheval de  guerre", "description": "Le chevalier possède une fidèle monture, un cheval de guerre bien dressé qui comprend les ordres simples. À cheval, il peut ajouter un déplacement de 10 m avant ou après une action normale (par exemple, parcourir 10 m et réaliser une action limitée). La monture n’attaque que si elle est elle‐même attaquée au contact par une créature. De plus, le chevalier ajoute son rang + 2 aux tests d’équitation et de dressage."}]}, "rang2": {"bonus": [{"type": "DM", "titre": "", "valeur": "+1", "condition": "Lorsqu’il est en selle, le chevalier gagne un bonus de +1 aux DM de ses attaques au contact, et sa monture obtient une DEF égale à celle du chevalier. Le bonus aux DM passe à +2 au rang 5."}], "titre": "Cavalier émérite", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": " Monter ou descendre de cheval est désormais une action gratuite. ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Charge ", "actions": [{"dm": "+1D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "À cheval, le chevalier peut effectuer un déplacement de 10 à 20 m en ligne droite et faire une attaque de contact placée au moment de son choix. Le joueur obtient un dé bonus au test d’attaque et ajoute 1d4° aux DM. Si une créature s’interpose pour bloquer la charge du chevalier, elle doit réussir un test de FOR difficulté 20 ou être contrainte de céder le passage en subissant 1d4° DM. Si elle réussit ce test, la Charge est bloquée et le tour du chevalier se termine.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Monture magique", "actions": null, "legacies": null, "capacites": null, "familiers": [{"titre": "", "description": "Le chevalier obtient une monture magique, qui peut apparaître et disparaître depuis un autre plan à volonté. Il peut l’invoquer à tout moment (c’est une action limitée) et elle apparaît alors pour se mettre à son service. Lorsqu’il la laisse au moins une heure dans son plan d’origine, elle guérit l’ensemble de ses PV."}]}, "rang5": {"bonus": null, "titre": "Monture fantastique", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Lorsqu’il est en selle, le chevalier peut faire attaquer sa monture une fois par round en action gratuite. ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": [{"titre": "Monture puissante", "description": "Le chevalier obtient une monture puissante (cheval de guerre lourd, ours, félin géant, etc.). Init. [Init. du chevalier], DEF 20, PV [10 + niveau du chevalier × 6], Ruade ou morsure [attaque magique], DM 2d4°+5. La valeur exacte des caractéristiques peut varier selon la créature. "}, {"titre": "Monture volante", "description": "À partir du niveau 9, le chevalier peut obtenir une monture volante (pégase, griffon, hippogriffe, etc.) si le MJ l’autorise (il devra vérifier qu’une monture volante n’entre pas en contradiction avec les aventures prévues). Dans ce cas, en vol, la monture couvre une distance de 20 m par action de mouvement, mais ses PV sont seulement égaux à [10 + niveau × 5]."}]}}', NULL, NULL, NULL),
	('6987542b-7801-463b-a394-e5f0e3ee178a', '2026-04-02 09:44:31.542099+00', 'Voie de la rage', 'famille', NULL, 'b12e8437-9f7e-4d3b-b55d-beaf048e8e50', false, '{"rang1": {"bonus": [{"type": "Tests peur", "titre": "", "valeur": "Rang+2", "condition": "Le barbare est sans peur, il ajoute son rang + 2 à tous les tests de VOL destinés à résister à la peur."}], "titre": "Cri de guerre", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le barbare pousse un hurlement qui effraie ses adversaires dans un rayon de 10 m. Les adversaires dont la FOR est inférieure à celle du barbare subissent un dé malus à leurs tests d’attaque au contact durant leur prochain tour. ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Défier la mort", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Une fois par combat, lorsque le barbare subit des DM d’une attaque qui devrait l’amener à 0 PV, il peut réaliser un test de CON difficulté 10. En cas de réussite, il conserve 1 PV. S’il est enragé, la réussite est automatique."}], "familiers": null}, "rang3": {"bonus": null, "titre": "Rage du berserk", "actions": [{"dm": "+1D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par jour, le barbare entre dans une rage berserk pour le reste du combat, ce qui le rend particulièrement dangereux. Il obtient +1d4° DM sur ses attaques au contact, mais il subit ‐2 en DEF et ne peut fuir de son propre gré ou attaquer à distance. Enfin, il obtient un dé bonus pour tous les tests de VOL. S’il veut stopper la rage avant d’avoir éliminé tous les ennemis sur le terrain, le barbare doit réussir un test de VOL difficulté 15 (un seul essai, à la fin de son tour). S’il devient inconscient, la rage cesse. Le personnage peut entrer en rage une fois de plus par jour pour chaque capacité de rang 4 qu’il atteint dans une voie de barbare.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Même pas mal", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Une fois par combat, le barbare peut ignorer les DM d’un coup critique (il ne subit aucun DM) et il peut alors immédiatement entrer en Rage par une action gratuite."}], "familiers": null}, "rang5": {"bonus": null, "titre": "Furie du berserk (L)", "actions": [{"dm": "+2D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Au lieu de la Rage du berserk, le barbare peut entrer en Furie du berserk, mais cela consomme deux utilisations de la rage. Cet état est similaire à la rage, mais le barbare ajoute 2d4° aux DM (au lieu de 1d4°) et subit ‐4 en DEF. La difficulté du test pour mettre prématurément fin à la furie est égale à 20.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('aaab3ef3-f5fe-4605-9adf-bec3f862d135', '2026-04-02 09:48:22.268473+00', 'Voie des artefacts', 'famille', NULL, 'baf24636-8c4a-4899-ba60-cc2c57280418', false, '{"rang1": {"bonus": null, "titre": "Bâton de mage", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Lorsqu’il utilise son bâton, le forgesort inflige [1d4°+INT] DM magiques. À partir du rang 3, au prix d’une action limitée, il peut utiliser sa valeur d’attaque magique pour une attaque au contact et il inflige [2d4°+INT] DM dans un éclair d’énergie ! Si le forgesort fait l’acquisition d’un bâton magique, les bonus de celui‐ci s’ajouteront normalement à l’attaque et aux DM (de même pour le bonus de feu de la voie du métal)."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Ouverture ‐ fermeture ", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le forgesort peut ouvrir une porte fermée à clef en la touchant, il doit réussir un test d’attaque magique contre la difficulté pour la crocheter. Il peut aussi sceller une porte ou un coffre pour INT minutes. Seul un mot de commande qu’il choisit permet d’ouvrir l’objet. Celui‐ci peut toujours être brisé par la force, mais il bénéficie d’un bonus de +5 en solidité et en RD pour toute la durée du sort. À partir du rang 4, le forgesort peut rendre ce sort permanent en sacrifiant une gemme d’une valeur de 100 pa et en prolongeant l’incantation par un rituel de 10 min.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Sac sans fond", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le forgesort possède un sac magique dans lequel il peut entreposer 50 kg de matériel par rang dans la voie, tandis que le sac semble toujours peser un kilogramme. Le sac ne fonctionne pas si on tente d’y mettre une créature vivante. Le sac est de plus capable de fournir au forgesort les objets qu’il désire. Une fois par heure, il peut en retirer un ou plusieurs objets dont la valeur totale ne dépasse pas 25 pa, le poids 50 kg, la circonférence 1 m et le volume 1 m3. Ces objets ont hélas la propriété de disparaître au bout d’une heure. De ce fait, la nourriture magique retirée du sac ne nourrit pas vraiment celui qui la consomme."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Frappe des arcanes", "actions": [{"dm": "3D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le forgesort frappe le sol de son bâton et provoque une onde dévastatrice dans un rayon de 10 m autour de lui. Toutes les créatures dans la zone subissent automatiquement [3d4°+INT] DM et doivent réussir un test de FOR difficulté [10 + INT] pour ne pas être renversées.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Artefact étrange", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le forgesort crée un artefact qu’il est le seul à pouvoir utiliser et dont la description est laissée au soin du joueur. L’artefact permet d’utiliser les capacités de rang 5 suivantes chacune une fois par jour au prix d’une action limitée : Téléportation (voie de la magie universelle, magicien), Interruption du temps (voie de la magie protectrice, magicien), Forme éthérée (voie de l’air, ensorceleur), Prescience (voie de la divination, ensorceleur). À chaque utilisation, le joueur doit lancer 1d6 : sur un résultat de 1 ou 2, l’artefact ne fonctionne pas, le forgesort doit réparer l’artefact lors d’une récupération rapide avant de pouvoir faire une nouvelle tentative de ce pouvoir (il peut tenter d’utiliser les autres pouvoirs normalement).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('81d700d9-56ef-404f-ad1c-06aa924254eb', '2026-04-02 09:44:31.542099+00', 'Voie du preux', 'famille', NULL, '13a28973-6eb6-4cfb-9aef-d2ed5e76d3da', false, '{"rang1": {"bonus": null, "titre": "Ignorer la douleur", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le chevalier peut noter à part les DM subis par une attaque (mais pas un critique). Il ne subira les DM que lorsque le combat sera terminé. De plus le héros gagne un bonus égal à rang + 2 pour haranguer et convaincre les foules (au moins 15 individus).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Piqûres d’insectes", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le chevalier obtient une réduction des DM (RD) des attaques à distance (arcs, arbalètes, lances, etc.) qui dépend de l’armure qu’il porte. Armure de plaques (complète ou non) RD 3, armure intermédiaire (Chemise ou cotte de mailles) RD 2, armure de cuir (simple ou renforcée) RD 1. Les DM infligés par une attaque sont toujours au minimum d’un point."}], "familiers": null}, "rang3": {"bonus": null, "titre": "Laissez‐le‐moi", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le chevalier met un point d’honneur à combattre le leader ennemi. Lorsqu’il peut aisément être identifié dans un groupe d’au moins 4 créatures, le chevalier lui inflige +1d4° DM par attaque au contact. Chaque fois que le chevalier inflige des DM à une créature de cette façon, la créature doit réussir un test d’INT difficulté 15 ou elle ne peut pas attaquer d’autre adversaire que lui à son prochain tour."}], "familiers": null}, "rang4": {"bonus": [{"type": "CHA", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests de CHA", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Charisme héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Seul contre tous", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le chevalier sait faire face à de nombreux adversaires. Lorsque au moins 3 adversaires l’attaquent au contact à ce round, il obtient une action d’attaque (A) supplémentaire à ce round."}], "familiers": null}}', NULL, NULL, NULL),
	('c1576927-c56a-485c-8f7c-a6b70589e13a', '2026-04-02 09:48:22.268473+00', 'Voie de la magie des arcanes', 'famille', NULL, 'd9b341c4-cb8a-4ec0-ac65-f8b08a87f414', false, '{"rang1": {"bonus": null, "titre": "Projectile de mana", "actions": [{"dm": "1D4°", "sort": true, "type": "A", "titre": "", "cout_mana": "1", "test_type": "", "description": "Le magicien choisit une cible visible située à moins de 30 m et lance sur elle un projectile d’énergie ésotérique pure, déformant la trame de la réalité. La cible subit automatiquement 1d4° DM. Si le joueur obtient le résultat maximal sur son dé de dommages, il peut le relancer et ajouter le nouveau résultat (une seule fois). Les DM du projectile de mana augmentent de +1 chaque fois que le personnage atteint le rang 4 dans une voie de magicien jusqu’à un maximum égal à sa valeur d’INT.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Lévitation", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le magicien peut se déplacer verticalement de 5 m par action de mouvement vers le haut ou de 10 m vers le bas pendant INT minutes. Rester en vol stationnaire à la même hauteur demande une action de mouvement.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Forme gazeuse", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le magicien prend la consistance d’un gaz pendant 1 min. Il se déplace au ras du sol (s’il chute, il le fait au ralenti) à une vitesse de 5 m par action de mouvement (M). Il peut s’introduire par les plus petits interstices (comme sous une porte), mais ne peut utiliser aucune capacité. Sous cette forme, les armes ordinaires ne lui infligent aucun DM, mais la magie et les armes magiques l’affectent normalement.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Accélération", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le magicien voit son métabolisme s’accélérer pendant [1d4°+INT] rounds. Il reçoit immédiatement une action de mouvement supplémentaire, puis une action de mouvement supplémentaire à chaque round. À son tour, il peut choisir de sacrifier cette action de mouvement pour obtenir au choix +3 en DEF pendant un round ou ‐1 PM sur le lancement d’un sort à ce round. Il est possible de cumuler cette réduction de ‐1 PM avec une Concentration (L). Par exemple, une Désintégration lancée de cette façon coûtera 5 – 2 – 1 = 2 PM.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Désintégration", "actions": [{"dm": "5D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Le magicien projette un rayon mortel dont la portée est de 20 m et qui annule la cohésion de la matière, ne laissant derrière lui qu’un amas de poussière. Un test d’attaque magique réussi contre la DEF de la cible inflige [5d4°+INT] DM. Si le magicien vise un objet porté par une créature, le test d’attaque subit un dé malus. Les objets magiques sont insensibles à ce sort et les objets normaux (jusqu’à 100 kg) sont réduits en poussière. Une créature réduite à 0 PV par ce sort est proprement désintégrée, ne laissant aucun cadavre derrière elle ! (Ses objets magiques sont épargnés).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('cd3b269b-c767-4475-a0af-25e80e90ebf7', '2026-04-02 09:51:26.325734+00', 'Voie des animaux', 'famille', NULL, '5c9cda86-9d6b-4f19-90dd-61c6358cdb8e', false, '{"rang1": {"bonus": [{"type": "Tests communication animale", "titre": "", "valeur": "Rang+2", "condition": "Le druide  ajoute son rang + 2 à tous les tests destinés à influencer un animal avec lequel il peut communiquer. "}], "titre": "Langage des animaux", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le druide sait communiquer avec les mammifères. La communication reste primitive et limitée à l’intelligence de l’animal et à son point de vue (prédateur, proie, etc.). Chaque fois que le personnage atteint le rang 4 dans une voie de druide, il apprend à communiquer avec une nouvelle catégorie d’animaux de son choix : les oiseaux, les reptiles (et les amphibiens), les poissons (et les mollusques) ou les arthropodes (insectes, araignées, scorpions, etc.) et enfin les animaux fantastiques (griffon, pégase, etc.)."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Petit compagnon", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le druide choisit un petit animal (écureuil, corbeau, chat). Il peut utiliser les sens de son familier (voir par ses yeux, entendre ce qu’il entend, etc.) et communiquer avec lui à distance illimitée. Il gagne +2 en DEF lorsque son familier est en vue. Le familier récupère tous les PV perdus après une récupération rapide. S’il est réduit à 0 PV, le familier prend la fuite et réapparaît auprès de son maître 24 h plus tard, complètement soigné. S’il est tué (lors d’un fait de jeu que le MJ juge inévitable), le druide perd 1d4° PV en contrecoup et pourra trouver un autre familier au prochain passage de niveau (pas forcément le même animal)."}], "familiers": [{"titre": "Familier", "description": "| AGI +3* | CON 0 | FOR ‐4 | PER +2* | INT ‐2 | CHA ‐2 | VOL +2 | DEF [13 + rang dans la voie] | PV [niveau du druide × 2] | INIT [Init. du druide]. Un familier est une créature trop petite pour attaquer et infliger des dommages."}]}, "rang3": {"bonus": null, "titre": "Nuée d’insectes", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "En réussissant un test d’attaque magique contre la DEF de sa cible (portée 20 m), le druide libère sur celle‐ci une nuée d’insectes volants qui piquent, aveuglent et la suivent pendant [3 + PER] rounds. La victime subit 1 DM par round et un malus de ‐2 à tous les tests. Les DM de zone détruisent la nuée.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Masque du prédateur ", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Pendant PER minutes, le druide prend les traits d’un fauve ou d’un loup. Il gagne +2 en Initiative, en DEF, en attaque et aux DM au contact et peut voir dans la nuit (comme un elfe).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Forme animale ", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Pendant une durée de PER minutes, le druide peut prendre la forme d’un animal de taille moyenne ou inférieure (minimum une souris) d’une catégorie dont il maîtrise la communication (voir rang 1, à l’exception des animaux fantastiques). Il conserve seulement ses PV, ses valeur d’INT et de VOL, et acquiert les caractéristiques, les attaques, la DEF et les capacités naturelles de la forme choisie (le vol pour un oiseau, la respiration aquatique pour le poisson, etc.). Le druide ne peut ni utiliser son équipement ni ses propres capacités sous cette forme. Le druide peut reprendre sa forme humaine lorsqu’il le désire par une action de mouvement (M).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('091ef97a-c2f6-4d5f-a654-a5d125416e9d', '2026-04-02 09:51:26.325734+00', 'Voie de la prière', 'famille', NULL, '01f25d23-87a9-4843-b66d-328950b80de3', false, '{"rang1": {"bonus": null, "titre": "Bénédiction", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "1", "test_type": "", "description": "Le prêtre entonne un chant pour encourager ses compagnons en vue. Ses alliés et lui bénéficient d’un bonus de +1 à tous leurs tests de caractéristique et d’attaque pendant CHA minutes. Ce bonus passe à +2 au rang 5. De plus, le prêtre obtient un bonus égal à son rang + 2 à tous les tests de théologie ou de cosmologie.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Sanctuaire", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "2", "test_type": "", "description": "Pendant 1 min (10 rounds), tous les adversaires qui veulent attaquer le prêtre doivent réussir un test d’INT difficulté [10 + CHA du prêtre]. S’ils échouent, ils ne peuvent pas l’attaquer pour la durée du sort. Ceux dont le niveau est inférieur à la moitié de celui du prêtre sont automatiquement affectés (pas de test d’INT). Si le prêtre commet une action offensive, le sort prend fin immédiatement et il ne peut plus être lancé avant de prendre une récupération rapide.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Destruction du mal (A)*", "actions": [{"dm": "2D4°+CHA", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Tous les morts‑vivants et les démons dans un rayon de 10 m autour du prêtre subissent automatiquement [2d4°+CHA] DM. Les DM passent à 3d4° au rang 5.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "VOL", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests VOL", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Volonté héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Intervention divine", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Le prêtre fait appel à son dieu pour changer le cours des événements. Une fois par combat, il peut décider qu’un test du MJ ou des joueurs est une réussite ou un échec, même après que les dés ont révélé leur résultat. Il ne peut pas modifier le résultat du test obtenu par une créature d’un NC supérieur à son niveau.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('283fa5e5-8ddf-4a01-a665-c770869cffbd', '2026-04-02 09:44:31.542099+00', 'Voie du bouclier', 'famille', NULL, '01976a10-7e38-4233-b4d0-4b867f557327', false, '{"rang1": {"bonus": null, "titre": "Protéger un allié", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "S’il n’est pas surpris, le guerrier peut accorder un bonus de DEF de +2 à un allié à son contact contre une attaque par round. Il doit annoncer son intention avant de connaître le résultat de l’attaque. De plus, vous ajoutez votre rang + 2 à tous les tests destinés à éviter d’être surpris.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Parer un coup", "actions": [{"dm": "", "sort": false, "type": "M", "titre": "", "cout_mana": "", "test_type": "", "description": "Le guerrier utilise une action de mouvement pour se mettre en posture défensive. Il peut alors essayer de parer une attaque à tout moment avant son prochain tour. Il doit faire un test d’attaque au contact (il peut remplacer la FOR par l’AGI pour ce test) en opposition au test de l’attaque au contact ou à distance réussie par son adversaire. S’il l’emporte, l’attaque adverse est bloquée par le bouclier. Il ne subit aucun DM sauf si la créature est de taille énorme ou colossale, auquel cas, il subit tout de même la moitié des DM. À partir du rang 5, le guerrier peut utiliser cette capacité en action gratuite (toujours une fois par round), mais dans ce cas, il subit un dé malus au test opposé.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le guerrier obtient un bonus de +1 en DEF lorsqu’il manie un bouclier. Ce bonus passe à +2 au rang 5. "}], "titre": "Défense au bouclier", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Lorsqu’il tient son bouclier en main, le guerrier retranche son rang à tous les DM des attaques de zone (sorts d''Explosion de feu, mains brûlantes, foudre, etc. et aux souffles) sauf s’il est surpris."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Absorber un sort", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Lorsqu’il s’est préparé à parer un coup, le guerrier peut décider à la place d’absorber un sort. S’il réussit un test d’attaque au contact (il peut remplacer la FOR par l’AGI pour ce test) opposé à un test d’attaque magique du lanceur de sort, le sort est absorbé par le bouclier et n’a aucun effet sur le guerrier (mais s’il s’agit d’un sort de zone, les autres cibles sont affectées normalement)."}], "familiers": null}, "rang5": {"bonus": null, "titre": "Renvoi de sort (G)", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Le guerrier peut décider de renvoyer un sort qu’il vient d’absorber grâce à sa capacité Absorber un sort. Au lieu d’être annulé, le sort absorbé est immédiatement retourné contre son expéditeur : le lanceur du sort subit alors les effets de sa propre attaque! Cet effet ne fonctionne pas contre les sorts de zone.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('6fc11170-0484-47f6-b8b2-afda872149e2', '2026-04-30 14:54:19.043734+00', 'Voie du protecteur', 'famille', NULL, '5c9cda86-9d6b-4f19-90dd-61c6358cdb8e', false, '{"rang1": {"bonus": null, "titre": "Baies magiques", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "1", "test_type": "", "description": "Le druide doit se trouver devant un buisson ou un arbre vivant. Son incantation fait pousser PER fruits qu’il peut cueillir. Chaque fruit offre l’équivalent d’un repas et rend [1d4°+rang] PV après 1 min à celui qui le consomme. Les effets de ces fruits ne fonctionnent qu’une fois par jour et par personnage. En plus de ce sort, le druide ajoute son rang + 2 à tous les tests de vigilance et de discrétion en pleine nature.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Forêt vivante", "actions": [{"dm": "", "sort": true, "type": "", "titre": "", "cout_mana": "2", "test_type": "", "description": "Après un rituel de 30 min, la forêt s’éveille dans un rayon de 1 km par rang et devient une alliée du druide pendant 24 h. Dans ce périmètre, les ennemis du druide sont désorientés et gênés par les branches et les racines. Ils divisent leur déplacement par deux et subissent un dé malus à tous les tests de survie, d’orientation, de perception ou de discrétion. Le druide peut lancer ce sort une seule fois par jour. Si deux druides essaient d’influencer la forêt, c’est celui dont le niveau est le plus élevé qui l’emporte.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Régénération*", "actions": [{"dm": "", "sort": true, "type": "", "titre": "", "cout_mana": "3", "test_type": "", "description": "Une cible touchée par le druide récupère [3d4°+PER] PV par un rituel de 10 min (la cible et le druide doivent rester au calme). À partir du rang 5, ce sort permet aussi de faire repousser les membres ou les parties du corps amputées. Une cible peut bénéficier de ce sort seulement une fois par jour.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "PER", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests PER", "titre": "", "valeur": "+dé bonus", "condition": ""}, {"type": "PM", "titre": "", "valeur": "+PER", "condition": ""}], "titre": "Perception héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Forme d’arbre", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Le druide peut se transformer en arbre (environ 5 m de hauteur) pendant PER minutes. Il prend les mêmes caractéristiques (à l’exception de l’INT, de la PER et de la VOL) que l’arbre animé (voir plus loin), y compris les PV. Sous cette forme, il ne peut pas parler, mais peut utiliser les sorts des voies du protecteur et des végétaux. À la fin du sort, ou s’il est réduit à 0 PV, il reprend forme humaine et retrouve les PV que le personnage avait au début du sort.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('950bd3b3-80d8-4aaa-929a-bfa3ec0bc30d', '2026-04-27 11:06:34.439782+00', 'Voie du Demi-Elfe', 'peuple', 'f959b127-d5ae-4e2f-8152-597362675f05', NULL, true, '{"rang1": {"nom": "Héritage culturel", "type": "passif", "description": "Le demi-elfe ne possède pas de voie de peuple dédiée, selon l''héritage culturel et le lieu de l''éduction de son personnage, le joueur devra choisir entre la voie de l''humain ou une des voies de peuple d''elfe"}, "rang2": {"nom": "", "type": "passif", "description": ""}, "rang3": {"nom": "", "type": "passif", "description": ""}, "rang4": {"nom": "", "type": "passif", "description": ""}, "rang5": {"nom": "", "type": "passif", "description": ""}}', '4afd8b4f-06c2-4432-823e-743464d27432', NULL, NULL),
	('4be8c835-c42b-47d3-a1ea-8565b0aa1997', '2026-04-27 11:22:12.432385+00', 'Voie de l''Elfe Sylvain', 'peuple', 'feb25bad-ddff-434d-89da-724aeccba71a', NULL, false, '{"rang1": {"bonus": [{"type": "Tests de survie en forêt", "titre": "", "valeur": "+3", "condition": "L’elfe gagne un bonus de +3 à tous les tests de survie en forêt (escalade, discrétion, chasse, etc.)."}], "titre": "Lumière des étoiles", "actions": null, "legacies": null, "capacites": [{"titre": "Vision dans le noir", "description": "Pour un elfe sylvain, l’obscurité de la nuit sous la lumière des étoiles est considérée comme de la pénombre. "}], "familiers": null}, "rang2": {"bonus": null, "titre": "Enfant de la forêt", "actions": null, "legacies": [{"titre": "Voie de druide ou rôdeur", "description": "Le joueur choisit une capacité de rang 1 de n’importe quelle voie de druide ou de rôdeur. Il peut utiliser cette capacité en armure jusqu’à l’armure de cuir renforcé sans pénalité."}], "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "Critique et DM", "titre": "", "valeur": "+1 +1d4°", "condition": "L’elfe augmente de 1 la zone de critique lorsqu’il utilise un arc (19‑20 au d20) et ajoute +1d4° aux DM en cas de critique. "}], "titre": "Archer émérite", "actions": null, "legacies": null, "capacites": [{"titre": "Maîtrise", "description": "Il sait utiliser les arcs courts, quel que soit son profil."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Flèche sanglante", "actions": [{"dm": "arme + 1D4°/round", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "L’elfe fait une attaque à distance qui provoque une hémorragie. En plus des DM normaux, la à la victime 1d4° DM à chaque round suivant jusqu’à ce que la cible soit soignée (tout effet de soins ou une action limitée utilisée à cet effet). On ne peut cumuler plusieurs effets de saignement. ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "AGI et PER", "titre": "", "valeur": "+1", "condition": "L’elfe augmente ses valeurs d’AGI et PER de +1."}], "titre": "Supériorité elfique", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('13f20c45-036c-4e8c-8859-030f8244207b', '2026-04-30 13:14:04.511829+00', 'Voie de l''invocation', 'famille', NULL, 'fda5872c-4e8a-44ad-8728-71355682f1ea', false, '{"rang1": {"bonus": null, "titre": "Choc", "actions": [{"dm": "1D4°+CHA", "sort": true, "type": "A", "titre": "", "cout_mana": "1", "test_type": "", "description": "Si l’ensorceleur réussit un test d’attaque magique réussi contre la DEF de son adversaire situé à une portée de 20 m, il lui inflige [1d4° + CHA] DM. Si la cible a un NC inférieur au rang atteint par l’ensorceleur dans la voie, elle doit réussir un test de FOR difficulté 10 pour ne pas être renversée.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Serviteur invisible", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "2", "test_type": "", "description": "Ce sort crée une force invisible pendant CHA minutes. Le serviteur peut effectuer à distance des tâches simples ne nécessitant pas de test de réussite avec une AGI et une INT de +0 et une FOR égale au CHA de l’ensorceleur (portée 20 m). Il peut par exemple rapporter un objet ou actionner un levier, voire faire la vaisselle. Le serviteur invisible se déplace à la même vitesse que l’ensorceleur, ne pèse rien, ne parle pas, n’a pas vraiment d’existence et peut se déplacer dans toutes\nles directions. Concevez‐le davantage comme une force qui obéit aux injonctions télépathiques de son créateur que comme une créature. Il n’attaque pas et ne peut pas être combattu, mais il peut être dissipé grâce au sort de maîtrise de la magie.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Arme de mana", "actions": [{"dm": "1d4°+CHA", "sort": false, "type": "A", "titre": "", "cout_mana": "", "test_type": "", "description": "Le sort crée une lame d’énergie lumineuse pendant [rang] rounds. Dès le premier round et à chaque round suivant, l’ensorceleur peut lui ordonner d’attaquer une cible de son choix à portée (action gratuite, portée 20 m). La lame doit réussir un test d’attaque magique contre la DEF de l’adversaire. Elle inflige [1d4° + CHA] DM en cas de réussite. L’ensorceleur ne peut maintenir actif qu’un seul sort d’arme de mana à la fois.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Porte dimensionnelle ", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "L’ensorceleur se téléporte lui‐même et jusqu’à un allié par point de CHA à une distance maximale de 60 m. Le lieu d’arrivée doit être en vue.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Mur de mana ", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "L’ensorceleur crée un mur de force invisible et indestructible (portée 10 m, maximum 5 m de haut et 10 m de long, vertical, sans coudes), ou bien un hémisphère de 3 m de rayon centré sur lui‐même, tous les deux immobiles. Le sort dure CHA minutes. Aucune matière ni force ne peut passer à travers le mur de force. En revanche, les attaques mentales ne sont pas stoppées et une porte dimensionnelle (ou une téléportation) permet de le franchir.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('bc97b5cf-afcc-4e31-b807-f592d6950282', '2026-04-02 09:25:28.601201+00', 'Voie du mercenaire', 'famille', NULL, 'c0636e1d-413c-41df-a9a7-a14c1a1db8b7', false, '{"rang1": {"bonus": [{"type": "Tests interaction sociale et alcool", "titre": "", "valeur": "+2", "condition": "L’arquebusier obtient un bonus égal à son rang + 2 aux tests d’interaction sociale dans les tavernes ou les auberges (renseignement, négociation, séduction, etc.) ainsi que pour résister aux effets de l’alcool."}, {"type": "DM non létaux", "titre": "", "valeur": "+1d4° DM/2", "condition": "L''arquebusier  inflige 1d4° DM à mains nues (non létal) et il divise par 2 tous les DM non létaux qu’on lui inflige. "}], "titre": "Pilier de bar", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Mort ou vif", "actions": [{"dm": "Arme + Manoeuvre", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "L’arquebusier effectue une attaque au contact ou à distance (avec l’arme en main). Si l’attaque est réussie, il inflige ses DM habituels (mais peut choisir d’infliger des DM temporaires) et il choisit entre désarmer, renverser ou affaiblir (1d4 rounds) un adversaire dont le NC est inférieur au rang atteint dans la voie. Si l’attaque est une réussite critique, il peut choisir de cumuler deux effets.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": ""}], "titre": "Combattant aguerri", "actions": null, "legacies": [{"titre": "Voie guerrier, voleur ou rôdeur", "description": "L’arquebusier choisit une capacité de rang 1 de son choix de guerrier, de voleur (armure de cuir) ou de rôdeur (armure de cuir renforcé)."}], "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "CON et tests de CON", "titre": "", "valeur": "+1 ", "condition": ""}, {"type": "Tests de CON", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Constitution héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": ""}], "titre": "Combat de masse", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Si le combat implique au moins 10 créatures actives (en comptant l’arquebusier et ses alliés), l’arquebusier obtient, au choix, une action d’attaque ou une action de mouvement supplémentaire à son tour. "}], "familiers": null}}', NULL, NULL, NULL),
	('de26a2a8-2cff-49cb-afcc-64067bd9faff', '2026-04-30 13:57:30.272051+00', 'Voie de la magie universelle', 'famille', NULL, 'd9b341c4-cb8a-4ec0-ac65-f8b08a87f414', false, '{"rang1": {"bonus": null, "titre": "Lumière", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "1", "test_type": "", "description": "Le magicien désigne un objet à moins de 10 m. Celui‐ci produit de la lumière dans un rayon de 10 m pendant INT heures. Cette source de lumière n’émet pas de chaleur. Une fois par combat, le magicien peut lancer ce sort sur les yeux d’une créature dont le NC ne dépasse pas le rang atteint dans la voie. S’il réussit un test opposé d’attaque magique, elle est aveuglée pendant 1 round.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "Initiative et DEF", "titre": "", "valeur": "+2", "condition": "Le magicien gagne +2 en Initiative et en DEF lorsque son familier est en vue. "}], "titre": "Familier (A)*", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "Invocation de familier", "cout_mana": "2", "test_type": "", "description": "", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": [{"titre": "", "description": "Le magicien choisit un petit animal (écureuil, corbeau, chat, dragonnet). Il peut utiliser les sens de son familier (voir par ses yeux, entendre ce qu’il entend, etc.) et communiquer avec lui à distance illimitée. S’il est réduit à 0 PV, le familier disparaît dans un nuage de fumée et le personnage perd 1d4° PV en contrecoup. Toutefois, le maître pourra à nouveau invoquer son familier dès qu’il aura terminé une récupération complète (c’est toujours le même animal qui apparaît). Le familier récupère tous les PV perdus après une récupération rapide.\nFAMILIER | AGI +3* | CON 0 | FOR ‐4 | PER +2 | CHA ‐2 | INT ‐2 | VOL +2 | DEF [13 + rang dans la voie] | PV [niveau du magicien] | INIT [Init. du magicien].\nUn familier est une créature trop petite pour attaquer et infliger des dommages."}]}, "rang3": {"bonus": null, "titre": "Invisibilité", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le magicien se rend invisible pendant [1d4°+INT] minutes. Une fois invisible, personne ne peut plus détecter sa présence ou lui porter d’attaque directe. Si le magicien attaque, il redevient visible. À partir du rang 5, le magicien peut lancer ce sort sur un allié au prix d’une action limitée.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Vol", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le magicien peut voler pendant [2d4°+INT] minutes. Sa vitesse de déplacement est la même qu’au sol. Il peut rester en vol stationnaire s’il le désire et cela est une action gratuite.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Téléportation (L)*", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "5", "test_type": "", "description": "Une fois par jour, le magicien disparaît et réapparaît à un autre endroit situé à moins de (niveau x INT) kilomètres. Le lieu d’arrivée doit être soit en vue, soit parfaitement connu par le magicien. Le magicien peut emmener avec lui un allié à partir du niveau 10, un deuxième au niveau 13, un troisième au niveau 16 et enfin un quatrième au niveau 19.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('d56307e0-0ceb-477b-b010-5b180a6ab71a', '2026-04-27 17:41:56.58588+00', 'Voie de l''Humain', 'peuple', 'd10fa49e-e981-4d51-a093-f21e9354f89f', NULL, true, '{"rang1": {"nom": "Diversité", "type": "passif", "description": "Un humain obtient un bonus de  +3 aux tests de deux domaines associés à son origine géographique ou sociale. De plus, il gagne 1PC supplémentaire.\n- Montagnard : escalade et résistance au froid\n- Citadin : commerce et résistance aux maladies\n- Campagnard : météorologie et équitation\n- Riverain : natation et navigation\n- Sauvage : chasser et pister\n- Nomade : orientation et résistance à la chaleur ou au froid"}, "rang2": {"nom": "Instinct de survie", "type": "passif", "description": "Une fois par combat, lorsqu''une attaque devrait amener l''humain à 0PV, les DM qu''elle inflige sont divisés par 2 (minimum 1). Après avoir bénéficié de cette capacité, l''humain gagne pour le reste du combat un bonus de +2 en DEF. "}, "rang3": {"nom": "Touche à tout", "type": "passif", "description": "Le personnage obtient une capacité de rang 1 ou 2 de n''importe quel profil au choix du joueur. Si la capacité est de rang 2 ou accorde un bonus de DEF, il doit respecter les limitations d''armure."}, "rang4": {"nom": "Loup parmi les loups", "type": "passif", "description": "Une fois par round, l''humain gagne +1D4° aux DM qu''il inflige lorsqu''il combat un adversaire humanoïde de taille moyenne. Ce bonus ne s''applique qu''aux DM initiaux d''une attaque, pas aux DM sur la durée."}, "rang5": {"nom": "Polyvalence", "type": "passif", "description": "Le personnage augmente sa caractéristique la plus faible de +1 et sa Volonté de +1"}}', '4afd8b4f-06c2-4432-823e-743464d27432', NULL, NULL),
	('12dec45a-e52e-4b93-9cec-ee1755c32205', '2026-04-27 11:15:18.842482+00', 'Voie de l''Elfe Haut', 'peuple', 'd85f98f4-606c-45ea-8dea-1f6bfa5d2d7b', NULL, false, '{"rang1": {"bonus": [{"type": "Tests érudition et artistiques", "titre": "", "valeur": "+3", "condition": " L''elfe haut gagne un bonus de +3 à tous les tests d’érudition (INT) et artistiques (CHA)."}], "titre": "Lumière intérieure ", "actions": null, "legacies": null, "capacites": [{"titre": "Vision dans le noir", "description": "Pour un elfe, l’obscurité de la nuit sous la lumière des étoiles est considérée comme de la pénombre."}], "familiers": null}, "rang2": {"bonus": [{"type": "Test opposé attaque magique", "titre": "", "valeur": "+ Rang", "condition": "L''elfe obtient un bonus égal à son rang lorsqu’il doit faire un test opposé d’attaque magique pour résister à un sort."}], "titre": "Force d’âme", "actions": null, "legacies": null, "capacites": [{"titre": "Immunité", "description": "L’elfe est immunisé à la peur et au sommeil magique. "}], "familiers": null}, "rang3": {"bonus": null, "titre": "Talent pour la magie", "actions": null, "legacies": [{"titre": "Voie de magicien ou d''ensorceleur", "description": "Le joueur choisit une capacité de rang 1 de n’importe quelle voie de magicien ou d’ensorceleur. Il peut utiliser cette capacité en armure sans pénalité (mais pas une capacité qui offre un bonus de DEF). À la place, il peut choisir une capacité de rang 2, mais ne doit alors pas porter d’armure pour lancer le sort. "}], "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Immortel", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "L’elfe n’a besoin que de la moitié du repos, de la nourriture ou de la boisson d’un humain normal pour être en pleine forme. L''elfe est immunisé aux effets des poisons et des maladies."}], "familiers": null}, "rang5": {"bonus": [{"type": "VOL et INT/CHA", "titre": "", "valeur": "+1", "condition": "L’elfe augmente sa valeur de VOL de +1 et sa valeur d’INT ou de CHA de +1."}], "titre": "Supériorité elfique", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('05462380-f5a0-4e0c-8e7f-50c861cce982', '2026-04-23 14:57:29.407414+00', 'Voie du Demi-Orc', 'peuple', '312d3bd8-3ce0-4a36-acbc-a7ae675fc4b4', NULL, false, '{"rang1": {"bonus": [{"type": "Tests intimidation", "titre": "", "valeur": "+3", "condition": "Le demi-orc gagne un bonus de +3 à tous les tests d’intimidation. "}], "titre": "Impressionnant", "actions": null, "legacies": null, "capacites": [{"titre": "Vision dans le noir", "description": "Dans le noir total, le demi-orc voit comme dans la pénombre jusqu’à 30m."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Talent pour la violence", "actions": null, "legacies": [{"titre": "Voie de barbare ou guerrier", "description": "Le joueur choisit une capacité de rang 1 de n’importe quelle voie de barbare ou de guerrier."}], "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "Zone critique et DM", "titre": "", "valeur": "+1  +1d4°", "condition": "Le demi-orc augmente de 1 point la zone de critique sur une attaque au contact (19-20 au d20) et ajoute +1D4° aux DM en cas de critique."}], "titre": "Critique brutal", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Attaque sanglante ", "actions": [{"dm": "arme + 1D4°/round", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le demi-orc réalise une attaque de contact qui provoque une hémorragie. En plus des DM normaux, l’attaque produit un saignement qui inflige à la victime 1D4° DM à chaque round suivant jusqu’à ce que la cible soit soignée (tout effet de soins ou une action limitée utilisée à cet effet). On ne peut pas cumuler plusieurs effets de saignement.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "FOR et CON", "titre": "", "valeur": "+1", "condition": "Le demi-orc augmente ses valeurs de FOR et de CON de +1."}], "titre": "Colosse", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('1e905ab7-6a8d-4ba1-8e37-fdc073ffd571', '2026-04-30 07:44:46.007025+00', 'Voie du Halfelin', 'peuple', '914f9154-5b14-425c-9f00-e406f6e5ec56', NULL, false, '{"rang1": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le halfelin obtient un bonus de +1 en DEF ."}, {"type": "Tests discrétion et vol", "titre": "", "valeur": "+3", "condition": "Le halfelin obtient un bonus de +3 à tous les tests de discrétion ainsi qu’à tous les tests effectués pour subtiliser quelque chose (pickpocket, vol à l’étalage, etc.)"}], "titre": "Petite taille", "actions": null, "legacies": null, "capacites": [{"titre": "Désavantage de taille", "description": "Un halfelin ne peut pas utiliser à une main une arme dont les DM dépassent 1d6 (épée courte, masse, etc., mais pas rapière). Il lui faut utiliser les deux mains pour les armes qui infligent 1d8 à 1d10 de DM (épée longue) et il lui est interdit d’utiliser les armes qui infligent plus de 1d10 DM. Il ne peut pas utiliser d’arc long ni d’arbalète lourde."}], "familiers": null}, "rang2": {"bonus": [{"type": "Tests opposés attaque magique", "titre": "", "valeur": "+Rang", "condition": "Le halfelin obtient un bonus égal à son rang à tous les tests opposés d’attaque magique effectués pour résister à un sort."}], "titre": "Résistance légendaire", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "PV", "titre": "", "valeur": "+1D4° ", "condition": "Un halfelin qui mange bien est un halfelin heureux. À chaque repas (jusqu’à 4 fois par jour, espacés d’au moins 3 h) au cours duquel le personnage boit et mange des mets de qualité et en quantité, il récupère 1d4° PV."}], "titre": "Bon pour le moral", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "PC", "titre": "", "valeur": "+1", "condition": "Le halfelin gagne 1 PC supplémentaire."}], "titre": "Petit veinard", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "Esquive", "cout_mana": "", "test_type": "", "description": "Le halfelin peut esquiver une attaque de son choix par combat (avant d’avoir pris connaissance des DM, mais pas un critique).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "AGI et CON", "titre": "", "valeur": "+1", "condition": "Le halfelin augmente ses valeurs d’AGI et de CON de +1."}], "titre": "Vif et bien nourri", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('890cbee6-a587-42b6-a9b0-a42f72ce26ee', '2026-04-30 08:12:45.022227+00', 'Voie du Mage', 'peuple', '81bff689-433b-4de1-9146-7c70ab428614', NULL, false, '{"rang1": {"bonus": [{"type": "Tests de magie", "titre": "", "valeur": "+2", "condition": "Le mage ajoute  son rang + 2 aux tests de connaissance et d’érudition en rapport avec la magie."}], "titre": "Capacité de peuple + occultisme", "actions": null, "legacies": [{"titre": "Voie du peuple", "description": "Le mage conserve sa capacité de peuple de rang 1. "}], "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Maîtrise de la magie", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le mage peut détecter la présence de magie (y compris la présence d’objets magiques) dans un rayon de 10 m. Un test d’INT difficulté [10 + rang du sort] permet de déterminer la fonction générale de l’enchantement. Il peut aussi tenter de dissiper un sort non permanent d’un rang maximal égal à ceux qu’il est capable de lancer en emportant un test opposé d’attaque magique contre l’auteur du sort.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le mage gagne +1 en DEF."}, {"type": "PM", "titre": "", "valeur": "+2", "condition": "Le mage gagne +2 PM (en plus de celui gagné avec cette capacité ; au total, en apprenant ce sort, le mage acquiert donc 3 PM d’un coup)."}], "titre": "Tour de magie", "actions": [{"dm": "", "sort": true, "type": "G", "titre": "", "cout_mana": "0", "test_type": "", "description": "Le mage peut réaliser un tour de magie (portée 10 m) par round en action gratuite sans dépenser aucun PM. Par exemple, fermer une porte à distance, éteindre ou allumer une bougie en claquant des doigts. Il ne peut réaliser aucune action qui nécessite une valeur de caractéristique supérieure à 0 (par exemple, s’il faut au moins +1 ou un test de FOR pour pousser une porte lourde, ce sort ne permet pas de la fermer). Cette capacité ne peut produire aucun DM direct. ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "INT et VOL", "titre": "", "valeur": "+1", "condition": "Le mage augmente son INT et sa VOL de +1. "}, {"type": "Tests d''INT", "titre": "", "valeur": "+dé bonus", "condition": "Le mage obtient un dé bonus aux tests d''INT"}], "titre": "Esprit supérieur", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "DM", "titre": "", "valeur": "+1D4°", "condition": "Lorsqu’il lance un sort, le mage peut augmenter les DM de +1d4° (en cas de DM sur la durée, une seule fois) en payant +1 PM pour un sort à cible\nunique ou +3 PM pour un sort de zone (Explosion de feu, Foudre, etc.)."}], "titre": "Tempête de mana", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('2e0e9808-393d-4910-9176-f93546fef8f1', '2026-04-30 07:38:24.582483+00', 'Voie du Gnome', 'peuple', 'c91faffd-c7c7-4807-9e0b-1eb3d2cacc78', NULL, false, '{"rang1": {"bonus": [{"type": "Tests scientifiques", "titre": "", "valeur": "+3", "condition": "Le gnome possède un talent inné pour les sciences, qu’elles soient occultes ou plus ordinaires : il gagne un bonus de +3 à tous les tests scientifiques (INT)."}], "titre": "Don étrange", "actions": null, "legacies": [{"titre": "Voie de l''ensorceleur", "description": "Le gnome choisit une capacité de rang 1 d''ensorceleur au choix.  S’il porte une armure, il ne peut pas utiliser ce sort plus d’une fois par jour (il doit payer le coût en PM de façon normale)."}], "capacites": [{"titre": "Vision dans le noir", "description": " Dans le noir total, le gnome voit comme dans la pénombre jusqu’à 10 m."}], "familiers": null}, "rang2": {"bonus": [{"type": "Tests interaction sociale", "titre": "", "valeur": "+3", "condition": "Le gnome est un compagnon sympathique et difficile à considérer comme dangereux ou malintentionné. Il gagne +3 à tous les tests d’interaction sociale sauf pour intimider. "}, {"type": "PC", "titre": "", "valeur": "+1", "condition": "Le gnome gagne 1 point de chance."}], "titre": "Petit pote", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+2", "condition": "Le gnome sait comment échapper aux attaques des grandes créatures comme les géants. Il gagne un bonus de +2 en DEF contre les créatures de\ntaille grande ou supérieure. Ce bonus passe à +3 au rang 5."}], "titre": "Insignifiant", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "DM", "titre": "", "valeur": "+AGI", "condition": "Le gnome ajoute son AGI aux DM qu''il inflige avec les arbalètes."}], "titre": "Merveille technologique", "actions": null, "legacies": null, "capacites": [{"titre": "Maîtrise", "description": "Le gnome sait utiliser les arbalètes (et les armes à poudre si votre MJ autorise leur usage), quel que soit son profil. "}], "familiers": null}, "rang5": {"bonus": [{"type": "CON et CHA", "titre": "", "valeur": "+1", "condition": "Le gnome augmente ses valeurs de CON et de CHA de +1."}], "titre": "Bonne nature", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('51634559-0435-4796-8c54-be64e3606b25', '2026-04-30 07:52:49.476375+00', 'Voie du Nain', 'peuple', 'fe3c85fc-9a9a-479b-9671-d5f1a72fb99b', NULL, false, '{"rang1": {"bonus": [{"type": "Tests roche/pierre", "titre": "", "valeur": "+3", "condition": "Le nain obtient un bonus de +3 à tous les tests en rapport avec la\npierre, l’architecture ou les mines ainsi qu’avec les passages secrets et les pièges dans les murs et les parois rocheuses."}], "titre": "Habitant des tunnels", "actions": null, "legacies": null, "capacites": [{"titre": "Vision dans le noir", "description": "Dans le noir total, le nain voit comme dans la pénombre jusqu’à 30 m. "}], "familiers": null}, "rang2": {"bonus": [{"type": "Attaque et DM ", "titre": "", "valeur": "+1", "condition": "Le nain gagne un bonus de +1 en attaque et aux DM lorsqu’il utilise une hache ou un marteau de guerre. "}], "titre": "Haches et marteaux", "actions": null, "legacies": null, "capacites": [{"titre": "Maîtrise", "description": "Le naim sait utiliser la hache et le marteau de guerre, quel que soit son profil."}], "familiers": null}, "rang3": {"bonus": null, "titre": "Résistance à la magie", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par jour, le nain peut choisir d’ignorer les effets d’un sort qui le prend pour cible (mais pas un sort de zone). Les créatures dont le niveau (NC) est au moins égal au double du nain ignorent cette capacité.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "RD", "titre": "", "valeur": "+2", "condition": "Le nain réduit tous les DM subis de 2 points (mais il subit toujours au moins 1 DM par attaque reçue). La réduction passe à 3 au niveau 10. Elle est cumulable avec d’autres sources de réduction des DM comme la peau d’acier du barbare."}], "titre": "Fils du roc", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "CON et VOL", "titre": "", "valeur": "+1", "condition": "Le nain augmente ses valeurs de CON et de VOL de +1."}], "titre": "Ténacité", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('39d00064-6d93-4f12-88c0-67a0abd6fded', '2026-04-30 14:18:30.479822+00', 'Voie de la mort', 'famille', NULL, '0e70fe72-32f7-4f1a-abe5-96290371a0a8', false, '{"rang1": {"bonus": null, "titre": "Siphon des âmes", "actions": null, "legacies": null, "capacites": [{"titre": "Siphon des âmes", "description": "Une fois par round, lorsqu’une créature humanoïde vivante meurt à moins de 20 m du sorcier, il récupère NC PV (arrondis à 1 pour NC 1⁄2). À partir du rang 3, si la créature est de NC supérieur à 4, il peut choisir de récupérer 1 PM au lieu des PV."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Masque mortuaire", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le sorcier prend l’apparence de la mort pendant INT minutes. Il est alors considéré non‐vivant et devient immunisé à la plupart des pouvoirs des morts‐vivants (drain de vigueur et affaiblissement, paralysie de la goule, etc.). De plus, ceux‐ci le prennent pour l’un des leurs. Il divise par deux tous les DM de froid. Il ne peut pas bénéficier de soins tant qu’il est sous l’effet de ce sort. Note : Les créatures non vivantes sont infatigables, ne respirent pas et sont immunisées aux maladies, aux poisons et à la plupart des attaques qui demandent un test de CON. Elles voient dans le noir comme dans de la pénombre à une distance de 30 m.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Baiser du vampire ", "actions": [{"dm": "2D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Ce sort nécessite la réussite d’un test opposé d’attaque magique (portée 30 m). La victime subit [2d4°+INT] DM et le sorcier récupère autant de PV (sans dépasser son maximum de PV).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Peur", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le sorcier effectue un test opposé d’attaque magique contre une cible (portée 20 m). S’il l’emporte, la victime fuit aussi loin du sorcier que possible pendant INT rounds (il lui faut généralement autant de temps pour revenir!). Les créatures dont le NC est supérieur ou égal au niveau du sorcier ne fuient qu’un seul round. Le sorcier peut choisir de lancer ce sort en action limitée et toutes les créatures à son contact sont affectées (faire un test d’attaque magique par adversaire).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Briser les cœurs", "actions": [{"dm": "5D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "Attaque magique", "description": "Le sorcier fait mine d’arracher le cœur de sa victime, puis de broyer dans sa main (l’image du cœur de la victime apparaît dans la main du sorcier). Il doit faire un test opposé d’attaque magique contre une cible vivante (portée 20 m) et, en cas de réussite, il inflige [5d4°+INT] DM, la moitié en cas de test raté. Ce sort ne peut affecter une même cible qu’une seule fois par combat.", "test_oppose": true, "resultat_si_reussi": "DM/2"}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('a13ca74c-dabb-4f5a-848e-17a3943a51b6', '2026-04-02 09:25:28.601201+00', 'Voie du combat à deux armes', 'famille', NULL, '69a984cb-e7d2-4f98-b109-69536f32a6b4', false, '{"rang1": {"bonus": null, "titre": "Attaque à suivre (G)", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, lorsqu’il rate une attaque de sa main principale, le rôdeur peut porter une attaque en action gratuite de son autre main avec une arme parmi dague (dague de lancer), hachette (hache de lancer) ou épée courte. S’il utilise une arme à une main en dehors de cette liste, il subit un dé malus sur cette attaque.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le rôdeur obtient un bonus de +1 en DEF lorsqu’il combat avec une arme dans chaque main. Ce bonus passe à +2 au rang 5 de la voie. Au début de son tour, s’il renonce à toute attaque de la main secondaire, il double ce bonus jusqu’à son prochain tour."}], "titre": "Parade croisée", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Droite ‐ gauche (G)", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, lorsqu’il attaque de sa main principale, le rôdeur obtient aussi une attaque de sa main secondaire en action gratuite. Si la cible n’est pas la même que celle de la main principale, il subit un dé malus au test. Cette capacité se substitue à Attaque à suivre.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "AGI", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests d''AGI", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Combattant héroïque", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Plutôt qu’augmenter son AGI, le personnage peut choisir d’augmenter sa valeur de FOR de +1 (pas de dé bonus aux tests) et peut désormais attaquer avec la même arme dans la main secondaire sans subir de dé malus (par exemple deux épées longues)."}], "familiers": null}, "rang5": {"bonus": [{"type": "DM ", "titre": "", "valeur": "1D4°", "condition": "Si les deux armes du rôdeur atteignent la même cible lors d’un même tour, le personnage obtient un effet d’enchaînement qui ajoute 1d4° DM à l’une des deux attaques de son choix."}], "titre": "Double peine", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('0bcb58f1-2fa7-4214-b85b-170ca8000366', '2026-04-02 09:25:28.601201+00', 'Voie du vagabond', 'famille', NULL, '49f707ab-2da8-4901-92ad-b80c1fde5c0f', false, '{"rang1": {"bonus": [{"type": "Tests culture", "titre": "", "valeur": "+2", "condition": "À force de voyager, le barde possède une culture générale très vaste, il ajoute son rang + 2 aux tests d’INT pour se «souvenir» d’une information historique, politique, géographique ou occulte ou encore pour identifier un objet magique difficulté (25 – (2 x niveau de magie de l’objet))."}], "titre": "Rumeurs et légendes", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "Tests de compétence", "titre": "", "valeur": "+1", "condition": "Le barde obtient un bonus de +1 à tous les tests de compétence (absolument tous, de se cacher dans les ombres jusqu’à forger une épée, en passant par traduire une langue ancienne). Ce bonus ne peut se cumuler à aucun autre bonus de compétence sauf celui du rang 1 de la voie de peuple. Il augmente de +1 chaque fois qu’il atteint le rang 4 dans une voie de barde."}], "titre": "Éclectique", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Attirail", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le barde possède toutes sortes de choses dans son sac ou ses poches. En dépensant 1 PC, il peut sortir un objet improbable qu’il avait sur lui, mais qui n’est pas inscrit sur sa fiche de PJ, par exemple un livre de poésie, une bouteille d’un excellent vin, un jouet pour enfant, un os pour le chien, une lettre de recommandation, etc. (pour une valeur maximale de 10 pa). Il peut aussi bricoler un objet avec trois bouts de ficelles et un clou (système D)."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Compréhension des langues (A)*", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Ce sort permet au barde de lire, écrire et parler une langue vivante étrangère. Le sort a une durée maximale de CHA heures, mais il peut aussi être lancé sur un allié au contact et dans ce cas, il ne dure que CHA minutes. À partir du rang 5, il peut aussi déchiffrer une inscription dans une langue morte.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Déguisement", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Ce sort permet au barde de prendre l’apparence de n’importe quelle humanoïde de taille à peu près équivalente (avec une marge d’environ 50 cm). S’il veut imiter une personne en particulier, il lui faudra réussir un test de CHA difficulté 15 (20 s’il ne la connaît pas mais l’a seulement vue, 10 s’il la connaît très bien). Le sort a une durée maximale de CHA heures, mais il peut aussi être lancé sur un allié au contact et dans ce pas, il ne dure que CHA minutes.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('195ac1b4-83a8-4881-8334-00599bd81bb4', '2026-04-02 09:25:28.601201+00', 'Voie de l''aventurier', 'famille', NULL, 'f325015e-9aaa-486d-a5a1-ad4ef845de78', false, '{"rang1": {"bonus": [{"type": "Tests éloquence", "titre": "", "valeur": "Rang+2", "condition": "Le voleur ajoute son rang + 2 aux tests destinés à baratiner, séduire, négocier, mentir ou pour trouver un objet au marché noir. "}], "titre": "Baratin", "actions": null, "legacies": null, "capacites": [{"titre": "Maîtrise", "description": "De plus, il devient capable d’utiliser les parchemins ou les baguettes magiques en réussissant un test d’attaque magique (L) contre une difficulté de (10 + (2 x rang du sort inscrit)). En cas d’échec, le sort n’est pas lancé et le voleur peut faire une nouvelle tentative."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Provocation", "actions": [{"dm": "+1D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "CHA contre INT", "description": "Le voleur maîtrise l’art de se rendre désagréable, voire insupportable. S’il emporte un test opposé de CHA contre INT d’un adversaire humanoïde à moins de 10 m, il force la cible à l’attaquer à son prochain tour. À ce moment‐là, si le voleur est au contact, il peut riposter par une attaque de contact gratuite pour laquelle il bénéficie au choix d’une attaque sournoise ou d’un bonus de 1d4° aux DM.", "test_oppose": true, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+2", "condition": "Le voleur possède une démarche et une façon de se déplacer à la fois élégante, féline et souple. Il ajoute +2 en DEF et en Initiative. Ce bonus passe à +3 au rang 5. Il lui faut seulement une action de mouvement pour se relever."}], "titre": "Souplesse du félin", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "CHA", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests de CHA", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Charisme héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Attaque paralysante", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le voleur peut, en réussissant une attaque de contact, paralyser un adversaire humanoïde de douleur. La cible ne subit aucun DM, mais elle est immobilisée pendant 1d4 rounds ou, si son NC est inférieur à la moitié du niveau du voleur, elle est paralysée. De plus, le voleur peut désormais utiliser au choix l’attaque sournoise (s’il détient cette capacité) ou infliger +1d4° DM contre tout adversaire immobilisé ou paralysé.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('820023db-e8dc-4a02-b9a4-bca8f7b8f9a1', '2026-04-02 09:48:22.268473+00', 'Voie du démon', 'famille', NULL, '0e70fe72-32f7-4f1a-abe5-96290371a0a8', false, '{"rang1": {"bonus": null, "titre": "Malédiction", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "1", "test_type": "Attaque magique", "description": "Le sorcier effectue un test opposé d’attaque magique contre une cible à moins de 20 m. En cas de succès,  la victime subit un dé malus à son prochain test. La cible ne peut subir les effets de ce sort qu’une fois par combat.", "test_oppose": true, "resultat_si_reussi": ""}, {"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "1", "test_type": "Attaque magique", "description": "Le sorcier effectue un test opposé d’attaque magique contre une cible à moins de 20 m. En cas de succès,le dé malus s’applique à ses 3 prochains tests. La cible ne peut subir les effets de ce sort qu’une fois par combat.", "test_oppose": true, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Beauté de la succube", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le sorcier acquiert une beauté fascinante pour INT minutes. Il gagne un dé bonus aux tests de CHA ainsi qu’une attaque de contact nécessitant un test d’attaque magique (contre DEF, action d’attaque), qui inflige [1d4°+INT] DM. Le sorcier récupère autant de PV (sans dépasser son maximum de PV) que la cible en a perdu.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Pacte démoniaque", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Le sorcier sacrifie 1d4° PV et gagne immédiatement +INT sur le résultat d’un d20 qu’il vient de lancer ou en DEF contre une attaque (avant de savoir si une attaque touche). De plus, il ajoute désormais sa VOL au nombre de dés de récupération (DR) qu’il possède.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Aspect du démon", "actions": [{"dm": "1D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le sorcier prend l’apparence d’un démon ailé pendant INT minutes. Il gagne un dé bonus en attaque au contact et +5 en DEF et à tous les tests physiques (FOR, AGI, CON), mais il ne peut pas utiliser d’arme (ni les arts martiaux). Il peut faire deux attaques de griffes à [1d4°+INT] DM à chaque tour, en action limitée (une seule en action d’attaque) et il peut voler de 10 m par action de mouvement. Note : Ne se cumule pas avec la Beauté de la succube.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Invocation d’un démon (L)*", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "5", "test_type": "", "description": "En sacrifiant 1d4° PV, le sorcier invoque un démon à son service pour INT minutes. Ce démon possède l’apparence d’un humanoïde musclé d’environ 2,30 m doté d’une épée et d’ailes de chauve‐souris. Le démon divise par deux tous les DM non magiques subis, les sorts et les armes magiques lui infligent des DM normaux. Il est capable de voler à une vitesse équivalente à un déplacement normal. Lorsque le sorcier atteint le niveau 15, le démon devient capable d’attaquer deux fois à son tour, au prix d’une action limitée.\n", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": [{"titre": "Démon", "description": "| AGI +2 | CON +4* | FOR +5* | PER +2 | CHA +0 | INT +2 | VOL +4 | DEF 18 | PV [niveau du sorcier × 5] | INIT [Init. du sorcier] | Attaque au contact : [attaque magique du sorcier] · DM 2d4°+5"}]}}', NULL, NULL, NULL),
	('bcc41557-c4e6-48b7-996f-0dfac4431606', '2026-04-30 12:50:51.632325+00', 'Voie du maître d''armes', 'famille', NULL, '01976a10-7e38-4233-b4d0-4b867f557327', false, '{"rang1": {"bonus": [{"type": "Tests estimation", "titre": "", "valeur": "Rang+2", "condition": "Le guerrier ajoute son rang + 2 à tous les tests destinés à estimer la valeur d’une arme ou la réputation martiale d’un adversaire."}], "titre": "Armes de prédilection", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le guerrier choisit une catégorie d’armes de prédilection parmi épées, haches, mains nues, masses, lances (épieu, lance, pique) et enfin armes de jet (dague de lancer, javelot, etc.), et il gagne +1 en attaque lorsqu’il l’utilise une arme de cette catégorie. "}], "familiers": null}, "rang2": {"bonus": [{"type": "Critique", "titre": "", "valeur": "+1", "condition": "Le guerrier augmente de 1 point les chances d’obtenir un critique sur les attaques effectuées avec une arme de prédilection (par exemple, 19‐20 au lieu de 20)."}], "titre": "Science du critique", "actions": null, "legacies": null, "capacites": [{"titre": "Science du critique", "description": ""}], "familiers": null}, "rang3": {"bonus": null, "titre": "Spécialisation", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Lorsque le guerrier emploie une arme de prédilection, il gagne un bonus de +1 DM. Chaque fois que le personnage atteint le rang 5 dans une voie de guerrier, il peut choisir une nouvelle catégorie d’arme de prédilection (il gagne les avantages des rangs 1 à 3) ou décider d’augmenter de +1 le bonus aux DM d’une catégorie qu’il connaît déjà (pour un maximum de +6 pour un guerrier ayant atteint le rang 5 dans les cinq voies)."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Attaque parfaite", "actions": [{"dm": "+1D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Vous obtenez un dé bonus en attaque au contact (ou à distance pour une arme de lancer) et ajoutez +1d4° DM. Vous devez utiliser une arme de prédilection. Éventuellement, le guerrier peut choisir de ne pas infliger les DM de son attaque parfaite pour désarmer une cible dont le NC est inférieur à son bonus de DM de spécialisation.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Riposte", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Lorsqu’un adversaire rate une attaque de contact contre lui, le personnage obtient immédiatement une attaque au contact contre cet adversaire. Le personnage ne peut obtenir qu’une seule attaque supplémentaire de cette façon à chaque round et si plusieurs adversaires le ratent, il choisit contre lequel il effectue la riposte.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('f3607500-7e01-41c0-a552-066e9b6d4090', '2026-04-02 09:25:28.601201+00', 'Voie du traqueur', 'famille', NULL, '69a984cb-e7d2-4f98-b109-69536f32a6b4', false, '{"rang1": {"bonus": [{"type": "Tests discrétion, vigilance, chasse", "titre": "", "valeur": "+2", "condition": "En milieu naturel, le rôdeur ajoute son rang + 2 à ses tests de discrétion et de vigilance ainsi qu’aux tests pour pister. "}], "titre": "Éclaireur", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le rôdeur peut remplacer le bonus de +1 PC de la famille des aventuriers par un bonus de +1 DR si le joueur le souhaite. "}], "familiers": null}, "rang2": {"bonus": null, "titre": "Attaque éclair", "actions": [{"dm": "+AGU", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le rôdeur peut effectuer une attaque au contact très rapide. Il ajoute son AGI en attaque et aux DM pour cette attaque. À partir du rang 5, cette attaque peut être associée à 10 m de déplacement.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "DM", "titre": "", "valeur": "+1D4°", "condition": "Le rôdeur obtient +1d4° aux DM de ses attaques au contact ou à distance lorsqu’il combat des animaux (même géants). Chaque fois qu’il atteint le rang 5 dans une voie de rôdeur, il peut choisir un ennemi juré contre lequel il obtient le même avantage parmi les goblinoïdes, les géants, les dragons, les morts‐vivants, les insectes, les démons."}], "titre": "Chasseur émérite", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "PER", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests de PER", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Perception héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Repli (L)", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "En milieu naturel, le rôdeur se déplace de 30 m en s’éloignant de ses ennemis. Le joueur fait un test d’AGI difficulté 10, en cas de succès, il disparaît de la vue de ses poursuivants. Il peut s’éloigner ou rester caché sans risque d’être retrouvé ou rattrapé. Si le terrain est découvert (désert, plaine), la difficulté passe à 15.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('3c839ca0-a682-477d-b88c-a472166b78f7', '2026-04-02 09:25:28.601201+00', 'Voie du roublard', 'famille', NULL, 'f325015e-9aaa-486d-a5a1-ad4ef845de78', false, '{"rang1": {"bonus": [{"type": "Tests voleur", "titre": "", "valeur": "Rang+2", "condition": "Le voleur ajoute son rang + 2 aux tests liés à la précision manuelle (crocheter une serrure, désamorcer un piège, pickpocket...) ainsi qu’aux tests pour évaluer un objet précieux (joyaux, bijoux,etc.). De plus il obtient +1 aux DM des attaques à distance avec les dagues et couteaux. Ce bonus passe à +2 au rang 3 de la voie et +3 au rang 5."}], "titre": "Doigts agiles", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "", "titre": "", "valeur": "Rang+2", "condition": "Le voleur ajoute son rang + 2 aux tests effectués pour fouiller une pièce à la recherche d’un trésor, détecter un piège (même magique), un passage secret ou même une embuscade (Vigilance). De plus, il divise par 2 les DM infligés par des pièges."}], "titre": "Aux aguets", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Feindre la mort", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "INT dd20", "description": "Une fois par combat, le voleur peut feindre la mort après avoir reçu une blessure (même à 0 PV). Il peut ainsi passer pour mort aussi longtemps qu’il le souhaite et un test d’INT difficulté 20 est nécessaire pour révéler la supercherie. Lorsqu’il décide de se relever (action gratuite), le voleur récupère immédiatement 1d4° PV et s’il est au contact d’un adversaire, celui‐ci est surpris. Un adversaire qui a déjà été victime de cette stratégie du voleur lors d’un précédent combat ne se laisse pas surprendre une seconde fois (sauf si son INT est de ‐4).", "test_oppose": true, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "Tests enquête", "titre": "", "valeur": "+dé bonus", "condition": "Le voleur obtient un dé bonus sur tous les tests de recherche d’indice (Trouver une preuve [PER], Faire une déduction [INT] et Obtenir un aveu [CHA]) ainsi que pour tous les tests réalisés pour brouiller des pistes, réaliser de faux indices ou de faux documents."}], "titre": "Expert en criminalité", "actions": null, "legacies": null, "capacites": [{"titre": "Indice", "description": "Lorsque le voleur est dans un lieu, s’il dépense 1 PC, le MJ devra lui donner un indice qui lui a échappé jusque‐là. S’il n’y a pas d’indice, le PC n’est pas dépensé."}], "familiers": null}, "rang5": {"bonus": null, "titre": "Maître du poison", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le voleur peut utiliser 3 doses de poison par jour sans risque de s’empoisonner lui‐même. Une dose permet d’enduire une dague, une flèche ou un carreau pour infliger +2d4° DM supplémentaire et demande un test de CON difficulté (10 + INT du voleur) ou une cible vivante est affaiblie pour le reste du combat. Alternativement, une dose peut être versée dans les aliments pour une personne ; si la cible rate son test de CON, elle sombre dans l’inconscience pour 2d6 min (4d6 min pour 2 doses, etc.)."}], "familiers": null}}', NULL, NULL, NULL),
	('aac0ca28-e5cb-4433-a68f-132f2789df0a', '2026-04-30 13:14:04.415936+00', 'Voie des illusions', 'famille', NULL, 'fda5872c-4e8a-44ad-8728-71355682f1ea', false, '{"rang1": {"bonus": null, "titre": "Mirage", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "1", "test_type": "", "description": "L’ensorceleur crée une illusion visuelle et sonore immobile d’une durée de CHA minutes. Le volume maximal de l’illusion est de 2 m de côté par rang dans la voie (portée 50 m). À partir du rang 4, l’illusion peut être animée, mais dans ce cas sa durée est exprimée en rounds. En plus de ce sort, l’ensorceleur ajoute son rang + 2 aux tests de supercherie ou à tout test qui lui servirait à mentir.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Image décalée", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "", "description": "L’ensorceleur crée des images décalées qui se superposent à sa silhouette pendant [1d4 + CHA] rounds. Lorsqu’une attaque au contact ou à distance le touche, l’ensorceleur lance 1d6 : sur 5‐6, il ne subit pas les DM.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Sort illusoire", "actions": [{"dm": "3D4°+CHA", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "L’ensorceleur lance un sort d’attaque qui n’est qu’une illusion. Il inflige [3d4°+CHA] DM contre une seule cible ou [2d4°+CHA] DM contre un maximum de cibles égal au rang atteint. Le joueur peut décrire la nature du sort à sa guise (une Explosion de feu, une nuée de criquets, une lance de glace, etc.), son imagination demeurant sa seule limite. Chaque cible peut faire un test de PER difficulté [10 + CHA de l’ensorceleur] pour ne subir aucun DM. Les créatures sans esprit (créatures artificielles, certaines plantes et morts‐vivants) sont immunisées à ce sort. Les PV perdus de cette façon se récupèrent normalement.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Imitation", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Pendant CHA minutes, l’ensorceleur peut prendre l’apparence d’une créature de taille proche de la sienne (+ ou – 50 cm) qu’il voit au moment de l’incantation. Une créature qui touche l’ensorceleur se rend compte que quelque chose ne va pas et a le droit à un test d’INT difficulté [10 + CHA de l’ensorceleur] pour voir à travers l’illusion.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Exécution mentale", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Ce sort invoque les pires terreurs d’une créature humanoïde vivante et lui fait croire à sa propre mort. L’ensorceleur doit faire un test opposé d’attaque magique contre sa cible (portée 20 m). En cas de succès la victime tombe à 0 PV ou si la cible est de niveau supérieur ou égal à l’ensorceleur, elle est étourdie (‐5 DEF et pas d’action) pendant 1 round. Une créature ne peut être la cible de ce sort qu’une fois par jour. Les créatures sans esprit (créatures artificielles, certaines plantes et certains morts‐vivants) sont immunisées à ce sort.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('016e39e1-d7cd-4cd8-a431-03879b42a425', '2026-04-30 14:54:19.13217+00', 'Voie des végétaux', 'famille', NULL, '5c9cda86-9d6b-4f19-90dd-61c6358cdb8e', false, '{"rang1": {"bonus": [{"type": "Tests connaissances plantes", "titre": "", "valeur": "Rang+2", "condition": "Le druide ajoute son rang + 2 aux tests pour identifier les plantes et connaître leurs propriétés."}], "titre": "Peau d’écorce", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "1", "test_type": "", "description": "La peau du druide prend la consistance de l’écorce. Il bénéficie d’un bonus à la DEF égal à +2 pendant PER minutes. Ce bonus augmente de +1 aux rangs 3 et 5. Les effets du sort ne sont pas cumulables au bonus d’une armure métallique ou d’un autre sort de protection qui ajoute un bonus de DEF (à l’exception du Masque du prédateur). ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Prison végétale", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le druide peut commander à la végétation de pousser et bloquer ses ennemis (mais pas ses alliés) dans une zone de 10 m de diamètre (portée 20 m) pendant PER minutes. Les cibles sont immobilisées. À son tour, une créature peut se libérer (action d’attaque) avec un test de FOR difficulté [10 + PER du druide]. En cas de réussite, elle n’est plus affectée par le sort pour le reste du combat.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Flèche vivante", "actions": [{"dm": "+3D4°", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "En une action, le druide enchante une flèche et la tire (il doit tenir un arc en main). Cette flèche a pour particularité de prendre racine dans la plaie et de devenir un arbuste. S’il réussit un test d’attaque à distance, il inflige les DM habituels de son attaque, et au round suivant, la flèche inflige 3d4° DM supplémentaires. Si la victime est réduite à 0 PV par ce sort, un jeune arbuste pousse sur son cadavre.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Animation d’un arbre", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le druide peut animer un arbre en le touchant. Il combat à son service pendant [niveau du druide] rounds. Il peut animer un seul arbre à la fois.\nARBRE ANIMÉ | AGI ‐2 | CON +3 | FOR +3 | PER ‐2 | CHA ‐2 | INT ‐2 | VOL +0 | DEF  [10 + rang] | PV [Niveau × 5] | INIT 8 | Attaque de contact : [attaque magique] · DM 1d4°+3 | Déplacement : 5 m par action de mouvement.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Porte végétale", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Une fois par jour, le druide peut pénétrer dans le tronc d’un gros arbre et sortir de celui d’un autre arbre appartenant à la même forêt et situé à une distance maximale de PER × 10 km. À partir du niveau 10 et tous les 4 niveaux supplémentaires, le druide peut emmener une personne avec lui.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('b4d0c9d4-60d8-47d6-bc78-e40a610b107f', '2026-04-02 09:44:31.542099+00', 'Voie de la guerre', 'famille', NULL, '13a28973-6eb6-4cfb-9aef-d2ed5e76d3da', false, '{"rang1": {"bonus": null, "titre": "Armure sur mesure", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "L’armure du chevalier est parfaitement ajustée, aussi il n’ajoute que la moitié de sa DEF à la difficulté des tests pour lesquels l’armure inflige une pénalité. De plus, lorsqu’il porte une armure lourde (plaque ou plaque complète), il obtient un bonus de +1 en DEF à chaque fois qu’il atteint le rang 5 dans une voie de chevalier."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Encaisser un coup", "actions": [{"dm": "", "sort": false, "type": "M", "titre": "", "cout_mana": "", "test_type": "", "description": "Le chevalier se place de façon à dévier un coup sur son armure. Jusqu’à son tour au round suivant, il peut retrancher la valeur de DEF de son armure (bonus de magie inclus si elle est enchantée) aux DM d’une seule attaque au contact qu’il subit (minimum 1 DM). Au rang 5, il peut ajouter son bonus de bouclier (là aussi, bonus de magie inclus et cumulable au bonus d’armure). Le chevalier ne peut pas être étourdi ou renversé par une attaque qu’il a décidé d’encaisser.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Frappe du justicier", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Lorsque le chevalier réalise cette attaque au contact, si le test d’attaque est un échec, il inflige tout de même 1⁄2 DM à sa cible. Un résultat de 1 au d20 n’inflige aucun DM.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "FOR", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests FOR", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Force héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Mon armure est une arme", "actions": [{"dm": "+1d4° +FOR", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le chevalier peut donner un coup avec son armure (gantelet, heaume, spallière, etc.) en action gratuite. Il inflige automatiquement [1d4° + FOR] DM, et si la FOR de la cible est inférieure à celle du chevalier, elle est (au choix du chevalier) renversée ou étourdie pour 1 round ou recule de 3 m.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('d1c82521-3144-4e52-baab-0dbcb2494e90', '2026-04-02 09:44:31.542099+00', 'Voie du meneur d''homme', 'famille', NULL, '13a28973-6eb6-4cfb-9aef-d2ed5e76d3da', false, '{"rang1": {"bonus": [{"type": "Tests stratégie", "titre": "", "valeur": "Rang+2", "condition": "Le chevalier ajoute son rang + 2 aux tests de stratégie et de tactique militaire ou pour commander une troupe."}], "titre": "Sans peur", "actions": null, "legacies": null, "capacites": [{"titre": "Immunité ", "description": "Le chevalier est immunisé aux effets de peur et il offre un bonus égal à son CHA aux tests de tous ses alliés contre ce type d’effet. "}], "familiers": null}, "rang2": {"bonus": null, "titre": "Intercepter", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, le chevalier peut encaisser une attaque au contact ou à distance à la place d’un allié à son contact. Il utilise sa DEF plutôt que celle de la cible initiale et retranche son rang dans la voie aux DM (en cas de synergie avec la capacité Piqûres d’insectes ou encaisser un coup, la réduction des DM se cumule). Le joueur doit annoncer son intention d’intercepter avant de connaître le résultat de l’attaque.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Exemplaire", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, le chevalier donne un dé bonus à un allié qui attaque un adversaire à son contact. Le dé bonus doit être attribué avant de lancer les dés.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Charge fantastique", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, lorsque le chevalier déclare l’utilisation de cette capacité, tous ses alliés en vue et lui obtiennent 10 m de déplacement supplémentaire au début de leur tour puis un dé bonus et +1d4° DM à toutes leurs attaques. Ne se cumule ni avec exemplaire ni avec ordre de bataille.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Ordre de bataille (G)", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Le chevalier donne des ordres tactiques pertinents au cœur de la bataille. Une fois par round, il octroie une action supplémentaire gratuite à un allié en vue (une action de mouvement ou une action d’attaque, mais pas une action limitée). Chaque allié ne peut profiter d’un ordre de bataille qu’une seule fois par combat.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('f1db5581-1512-4617-97ae-ff0bd2deced5', '2026-04-02 09:44:31.542099+00', 'Voie de la noblesse', 'famille', NULL, '13a28973-6eb6-4cfb-9aef-d2ed5e76d3da', false, '{"rang1": {"bonus": [{"type": "Tests culture", "titre": "", "valeur": "+2", "condition": "Le chevalier sait lire et écrire, et apprend à parler une langue supplémentaire. De plus, il ajoute son rang + 2 à tous les tests d’histoire, d’héraldique et de géographie ainsi qu’aux tests pour savoir se comporter dans la haute société."}], "titre": "Éduqué", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "Critique", "titre": "", "valeur": "+1", "condition": "Grâce à l’écuyer, les armes du chevalier sont parfaitement affûtées et il augmente de 1 point les chances d’obtenir un critique sur les attaques au contact (par exemple, 19‐20 au lieu de 20)."}], "titre": "Écuyer", "actions": null, "legacies": null, "capacites": [{"titre": "Services de l''écuyer", "description": "Le chevalier, sa monture et jusqu’à CHA alliés récupèrent 1d4° PV supplémentaires après chaque récupération complète s’ils profitent des services de l’écuyer."}], "familiers": [{"titre": "", "description": "Le chevalier dispose d’un écuyer à son service (Init. [chevalier], DEF [10 + rang], PV [niveau × 4], Att [attaque magique], DM 1d4°+1). Il est absolument loyal à son maître, il s’occupe de sa monture et de son équipement, prépare le campement, panse les blessures, etc.  Si l’écuyer vient à mourir, le chevalier en prendra un autre à son service au niveau suivant."}]}, "rang3": {"bonus": [{"type": "Tests autorité", "titre": "", "valeur": "Rang+2", "condition": "Le chevalier ajoute son rang + 2 aux tests réalisés pour donner des ordres ou intimider."}], "titre": "Autorité naturelle", "actions": null, "legacies": null, "capacites": [{"titre": "Maîtrise", "description": " Le noble chevalier reçoit la formation nécessaire au port de l’armure de plaque complète (DEF +7). Désormais, il peut utiliser toutes les capacités des voies de chevalier en portant cette armure."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Massacrer la piétaille", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le chevalier ajoute +1d4° aux DM contre la piétaille. S’il y a au moins 4 créatures aux statistiques semblables impliquées dans le combat, elles sont assimilées à de la piétaille (même si leur nombre est par la suite réduit à moins de 4 au cours du combat). Les cavaliers ne sont jamais considérés comme de la piétaille."}], "familiers": null}, "rang5": {"bonus": [{"type": "Tests caractéristique", "titre": "", "valeur": "+dé bonus", "condition": " Le chevalier choisit une caractéristique ; désormais, il obtient un dé bonus lors des tests en rapport avec celle‐ci."}], "titre": "Formation d’élite", "actions": null, "legacies": [{"titre": "Famille combattants ou aventuriers", "description": "Le chevalier possède les moyens et la culture nécessaires pour obtenir une formation dans n’importe quel domaine qui lui sied. Choisissez une capacité de rang 1 à 3 dans n’importe quel profil issu de la famille des combattants ou des aventuriers. "}], "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('1709a5d1-ca78-4fcd-ab86-41deaad6efd5', '2026-04-30 13:36:01.612565+00', 'Voie du métal', 'famille', NULL, 'baf24636-8c4a-4899-ba60-cc2c57280418', false, '{"rang1": {"bonus": null, "titre": "Morsure de la forge", "actions": [{"dm": "+2(feu)", "sort": true, "type": "M", "titre": "", "cout_mana": "1", "test_type": "", "description": "Au prix d’une action de mouvement, le forgesort peut enflammer son bâton ou son marteau pendant INT minutes et ajoute +2 DM de feu sur les attaques au contact réalisées avec cette arme. Ce bonus augmente de +1 chaque fois que le personnage atteint le rang 4 dans une voie de forgesort. L’arme s’éteint immédiatement s’il la lâche. En plus de ce sort, le forgesort ajoute son rang + 2 aux tests d’orfèvrerie ou de forge.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Métal brûlant", "actions": [{"dm": "1", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "Attaque magique", "description": "Le forgesort doit réussir un test opposé d’attaque magique (portée 20 m) pour faire chauffer un objet métallique porté par sa cible pendant [1d4+INT] rounds. S’il s’agit d’une arme, elle inflige 1 DM par round à son porteur et un malus de ‐2 aux tests d’attaque. S’il s’agit d’une armure, elle inflige 1d4° DM par round à son porteur (au tour du forgesort). La victime peut se débarrasser précipitamment de son armure au prix d’une action limitée (elle perd le bonus de DEF associé ; dans le cas d’un adversaire, le MJ devra évaluer ce montant).", "test_oppose": true, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Magnétisme", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le forgesort contrôle le magnétisme autour de lui pendant INT minutes. Il obtient un bonus de +2 en DEF contre les attaques des armes métalliques (au contact ou à distance). De plus, il divise par deux les DM de tous les projectiles à pointes métalliques (flèches, carreaux, armes de lancer, etc.).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Métal hurlant", "actions": [{"dm": "3D4°", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Sur un test opposé d’attaque magique réussi (portée 10 m), le forgesort déforme une pièce d’équipement métallique portée par sa cible. Une arme devient inutilisable et bonne pour le rebut, une armure impose l’utilisation d’un dé malus à tous les tests d’attaque et d’AGI de son porteur. La victime peut se débarrasser de son armure au prix d’une action limitée. Si l’objet est magique, le sort ne fait effet que pendant un seul round (et ne peut pas être renouvelé). Appliqué à une structure (par exemple, une porte blindée), ce sort inflige 3d4° DM en divisant par deux sa RD.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "CON", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests CON", "titre": "", "valeur": "+dé bonus", "condition": ""}, {"type": "PM", "titre": "", "valeur": "+CON", "condition": ""}], "titre": "Endurer", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le forgesort est habitué aux travaux et à la chaleur de la forge. Il divise par deux tous les DM de feu subis. "}], "familiers": null}}', NULL, NULL, NULL),
	('22ba4946-62c7-4c87-a08b-42af89709adc', '2026-04-30 13:57:30.131456+00', 'Voie de la magie élémentaire', 'famille', NULL, 'd9b341c4-cb8a-4ec0-ac65-f8b08a87f414', false, '{"rang1": {"bonus": null, "titre": "Asphyxie", "actions": [{"dm": "1D4°", "sort": true, "type": "A", "titre": "", "cout_mana": "1", "test_type": "", "description": "Si le magicien réussit un test opposé d’attaque magique (avec une portée de 20 m), la créature ciblée est privée d’air. La victime étouffe progressivement et subit 1d4° DM par round pendant INT rounds. Les créatures qui ne respirent pas (morts‐vivants, créatures artificielles) sont immunisées à ce sort. En revanche, les réductions de dommages (voie du colosse, par exemple) ne s’appliquent pas.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Maîtrise des éléments", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le magicien retranche son rang + 2 à tous les DM de feu, de froid, d’électricité ou d’acide subis pendant INT minutes. De plus, pendant la durée du sort, lorsqu’il lance un sort d’un élément, le magicien peut échanger un élément contre un autre (par exemple, une explosion de froid ou une flèche acide).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Arme élémentaire", "actions": [{"dm": "+1D4°", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le magicien peut enchanter, en la touchant, une arme au contact ou à distance pour INT minutes. S’il s’agit de son arme, l’incantation est une action d’attaque (A); Si l’arme change de main, le sort prend fin. L’arme inflige +1d4° DM de feu, de froid, d’électricité ou d’acide en plus des DM habituels. Le magicien doit choisir l’élément au moment de l’incantation. Tant qu’il tient l’arme élémentaire en main, les sorts basés sur cet élément lui coûtent 1 PM de moins pour être lancés (par exemple, Mains brûlantes ou Explosion de feu s’il a enflammé son bâton). Ce sort ne fait aucun effet sur une arme qui bénéficie déjà d’un bonus élémentaire aux DM.", "test_oppose": false, "resultat_si_reussi": ""}, {"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le magicien peut enchanter, en la touchant, une arme au contact ou à distance pour INT minutes. Si elle appartient à autrui, c’est une action limitée (L). Si l’arme change de main, le sort prend fin. L’arme inflige +1d4° DM de feu, de froid, d’électricité ou d’acide en plus des DM habituels. Le magicien doit choisir l’élément au moment de l’incantation. Tant qu’il tient l’arme élémentaire en main, les sorts basés sur cet élément lui coûtent 1 PM de moins pour être lancés (par exemple, Mains brûlantes ou Explosion de feu s’il a enflammé son bâton). Ce sort ne fait aucun effet sur une arme qui bénéficie déjà d’un bonus élémentaire aux DM.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Respiration aquatique", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le magicien peut respirer sous l’eau pendant 10 minutes. Cette capacité peut être étendue à un compagnon par point d’INT.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Armure de pierre", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Pendant INT minutes, le magicien retranche 5 points à tous les DM subis. Le sort prend fin dès qu’il a absorbé [niveau du magicien × 3] DM. Cette réduction se cumule à celle offerte par la Maîtrise des éléments. Armure de pierre est incompatible avec le sort Déphasage (voie de la magie protectrice), il y met fin immédiatement.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('c10edd9c-8f7d-41fe-ab8a-c9953c3dce0f', '2026-04-02 09:51:26.325734+00', 'Voie de l''énergie vitale', 'famille', NULL, '366b95b3-7789-4c78-8353-7b098c2b1c5f', false, '{"rang1": {"bonus": null, "titre": "Mains d’énergie", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Par un effort de concentration, le moine peut rendre ses mains intangibles. Au prix d’une action limitée, à son tour, il peut faire une attaque à mains nues avec un bonus en attaque égal au rang + 2. De plus, même lorsqu’il n’utilise pas Mains d’énergie, toutes les attaques à mains nues du moine sont considérées comme magiques et il peut choisir de remplacer sa FOR aux DM par sa VOL.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Projection du ki", "actions": [{"dm": "1D4°+VOL", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le moine projette une vague de force avec son corps et son esprit à une distance maximale de 20 m. Un test d’attaque magique réussi lui permet d’infliger [1d4°+ VOL] DM. Les DM passent à [2d4°+ VOL] au rang 4.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Invulnérable", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le moine ne reçoit que la moitié des DM de toutes les sources « élémentaires » : Feu, froid, foudre, acide… ainsi que des poisons ou des maladies. À partir du rang 5, il ne reçoit plus aucun DM ni effet des poisons et des maladies."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Pression mortelle (M)", "actions": [{"dm": "+1D4°", "sort": false, "type": "M", "titre": "", "cout_mana": "", "test_type": "", "description": "Le moine frappe les points par lesquels circule l’énergie vitale d’une créature vivante. En touchant un point précis, il libère ensuite des effets dévastateurs. Lorsqu’il combat à mains nues, le joueur peut choisir de ne pas infliger immédiatement les DM de ses attaques, il les comptabilise à part et ajoute +1d4° aux DM de chaque attaque. À tout moment dans l’heure qui suit, il peut annoncer une Pression mortelle. Il doit alors réussir un test d’attaque au contact contre la DEF de la cible (action limitée), ce qui libère instantanément la totalité des DM infligés jusqu’alors. À partir du niveau 10, le moine n’a plus besoin de toucher sa cible pour déclencher cet effet ; dans ce cas, il remplace le test d’attaque au contact par un test opposé d’attaque magique, mais n''a droit qu''à un seul essai.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "CON", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests CON", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Ascétisme", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le moine ne mange presque plus, et il peut subsister sans eau et sans sommeil pendant [5 + VOL] jour. Il ne subit aucune pénalité durant cette période. "}], "familiers": null}}', NULL, NULL, NULL),
	('04d3f569-6a1b-4969-a399-c584de5886d7', '2026-04-02 09:51:26.325734+00', 'Voie de la maîtrise', 'famille', NULL, '366b95b3-7789-4c78-8353-7b098c2b1c5f', false, '{"rang1": {"bonus": [{"type": "Tests acrobaties", "titre": "", "valeur": "Rangs+2", "condition": "Le moine ajoute son rang + 2 à tous ses tests pour effectuer des acrobaties ou esquiver."}, {"type": "DEF", "titre": "", "valeur": "+2", "condition": "Le moine gagne +2 en DEF. Ce bonus passe à +3 au rang 4."}], "titre": "Agilité du singe", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Se relever (si le personnage est renversé) devient une action gratuite.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Griffes du tigre", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Désormais, lorsque le moine obtient un résultat de 1 au dé de DM à mains nues, il le remplace par le résultat maximal du dé. De plus le moine peut choisir d’infliger des DM tranchants ou perforants lorsqu’il combat à mains nues au lieu de DM contondants."}], "familiers": null}, "rang3": {"bonus": [{"type": "Critique", "titre": "", "valeur": "+1", "condition": "Lorsqu’il attaque à mains nues, le moine augmente de 1 point les chances d’obtenir un critique sur les attaques au contact (par exemple, 19‑20 au lieu de 20)."}], "titre": "Morsure du serpent", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Les coups critiques portés à mains nues sont désormais si douloureux que la cible est affaiblie pendant 1 round."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Fureur du dragon", "actions": [{"dm": "3D4°+FOR", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "FOR", "description": "Une fois par combat, le moine peut effectuer une attaque tournoyante qui inflige automatiquement [3d4°+FOR] DM à tous les adversaires au contact et oblige ceux‑ci à réussir un test de FOR difficulté 10 pour ne pas être renversés.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "Choix", "titre": "", "valeur": "+1", "condition": "De plus le moine augmente définitivement de +1 la valeur de sa plus faible caractéristique (choisir en cas d’égalité)."}], "titre": "Moment de perfection", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Une fois par jour, le moine peut choisir de réussir toutes ses attaques automatiquement (pas de critique) et d’esquiver toutes celles qui le prennent pour cible pendant un round. Tout semble aller au ralenti autour de lui… Il peut utiliser cette capacité une fois de plus chaque jour par rang 5 atteint dans une autre voie de moine, mais pas plus d’une fois par combat. "}], "familiers": null}}', NULL, NULL, NULL),
	('0ee2588f-b9b4-41e1-a2db-1a1526163eb4', '2026-04-30 14:18:30.627598+00', 'Voie de l''outre-tombe', 'famille', NULL, '0e70fe72-32f7-4f1a-abe5-96290371a0a8', false, '{"rang1": {"bonus": null, "titre": "Un pied dans la tombe ", "actions": [{"dm": "1D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "1", "test_type": "Attaque magique", "description": "Le sorcier désigne une cible vivante à portée (10 m) et doit réussir un test opposé d’attaque magique. En cas de succès, la cible ressent une douleur intense à l’emplacement du cœur, elle subit [1d4°+INT] DM et, si elle rate un test de CON difficulté 10, l’état ralenti durant 1 round.", "test_oppose": true, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Armure d’os", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le sorcier peut désormais porter une armure d’os (souvent camouflée sous une robe) qui lui offre un bonus de +3 en DEF et n’empêche pas l’utilisation des capacités de sorcier. Son bonus de DEF augmente de +1 chaque fois que le personnage atteint le rang 4 dans une voie de sorcier. Le sorcier doit confectionner cette armure lui‐même à partir d’ossements et l’entretenir par magie 10 min chaque jour. L’armure d’os n’inflige aucun malus d’AGI."}], "familiers": null}, "rang3": {"bonus": null, "titre": "Animation des morts", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le sorcier anime le cadavre d’un humanoïde de taille moyenne, décédé depuis moins d’INT jours. Le zombie comprend les ordres «Attaquer », «Suivre», «Garder» et «Pas bouger». Le sorcier peut contrôler un seul zombie, plus un zombie chaque fois qu’il atteint le rang 5 dans une voie de sorcier. Un zombie réduit à 0 PV tombe en poussière.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": [{"titre": "Zombie", "description": " | AGI ‐1 | CON +1 | FOR +2 | PER ‐2 | CHA ‐4 | INT ‐4 | VOL +6 | DEF 10 | PV [10 + niveau] | INIT 8 | Attaque au contact : [attaque magique du sorcier] · DM 1d4°+2 - Le zombie se déplace de 5 m par action de mouvement."}]}, "rang4": {"bonus": null, "titre": "Ensevelissement", "actions": [{"dm": "2D4°", "sort": true, "type": "L", "titre": "", "cout_mana": "4", "test_type": "", "description": "Une fois par combat, si le sorcier réussit un test opposé d’attaque magique (portée 20 m), des mains squelettiques surgissent sous les pieds d’une cible de taille moyenne ou inférieure et l’enterrent vivante. Tant qu’elle est ensevelie, elle subit 2d4° DM par round, ne peut agir ni être la cible d’attaques extérieures. À son tour, elle peut tenter de sortir de terre en réussissant un test de FOR ou d’AGI (au choix de la cible) difficulté 15 au prix d’une action limitée. Si elle tombe à 0 PV, elle reste enterrée et décède au tour suivant. Chaque personne qui creuse pour l’aider lui octroie un bonus de +2 sur son test (maximum +10).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Armée des morts", "actions": [{"dm": "2D4°", "sort": true, "type": "L", "titre": "", "cout_mana": "5", "test_type": "", "description": "Une fois par jour, le sorcier peut invoquer d’innombrables squelettes qui émergent du sol pour attaquer ses ennemis pendant [niveau du sorcier] rounds. Tous les adversaires situés dans un rayon de 10 m autour du sorcier subissent automatiquement 2d4° DM par round. Les squelettes se déplacent avec le sorcier, mais tous les déplacements dans cette zone (même ceux du sorcier) sont divisés par deux.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('74c9364a-625f-4972-b95e-a4ea794cde6e', '2026-04-30 14:18:30.725176+00', 'Voie du sang', 'famille', NULL, '0e70fe72-32f7-4f1a-abe5-96290371a0a8', false, '{"rang1": {"bonus": null, "titre": "Saignements ", "actions": [{"dm": "1D4°", "sort": true, "type": "A", "titre": "", "cout_mana": "1", "test_type": "", "description": "Le sorcier doit réussir un test d’attaque magique (portée 10 m) contre une difficulté de [10 + CON de la cible]. Du sang s’écoule de la bouche, du nez, des oreilles et même des yeux de la victime, qui subit 1d4° DM par round pendant INT rounds.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Sang mordant", "actions": [{"dm": "1D4° acide", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "", "description": "Pendant INT minutes, le sang du sorcier se transforme en un acide qui gicle lorsqu’il subit une blessure. Chaque fois qu’un ennemi au contact le blesse, ce dernier subit 1d4° DM d’acide.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+2", "condition": "Le corps du sorcier devient cadavérique. Il gagne +2 en DEF et ce bonus passe à +3 au rang 5 (Si le personnage porte une armure autre qu’une armure d’os de sorcier, le bonus est réduit de 1 point, donc +1 DEF et +2 DEF au rang 5)."}], "titre": "Exsangue", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Lorsque le sorcier tombe à 0 PV, il peut continuer à agir, mais avec un dé malus à tous ses tests. S’il subit encore au moins 1 DM, il sombre dans l’inconscience."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Rituel de sang", "actions": [{"dm": "+1D4°", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le sorcier s’ouvre les veines et sacrifie 1d4° PV pour cibler une créature vivante (portée 20 m), la victime saigne à la moindre blessure. Tous les DM infligés à la cible par des armes tranchantes ou perçantes (griffes et crocs inclus) augmentent de +1d4° pendant INT rounds.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Lien de sang", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "En réussissant un test opposé d’attaque magique (portée 20 m), le sorcier tisse un lien avec sa victime. Pendant INT minutes, la moitié des DM reçus par le sorcier sont également subis par la cible (les DM infligés au sorcier ne sont pas pour autant réduits) et le sorcier peut lui lancer un sort sans la voir (si elle est à portée).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('573991bc-28e1-4dc5-a740-67784a194fd4', '2026-04-30 14:18:33.009419+00', 'Voie de la sombre magie', 'famille', NULL, '0e70fe72-32f7-4f1a-abe5-96290371a0a8', false, '{"rang1": {"bonus": [{"type": "Tests savoirs sombres", "titre": "", "valeur": "Rang+2", "condition": "Le sorcier ajoute son rang + 2 à tous les tests d’INT basés sur les savoirs sombres (démons, morts‐vivants, rituels impies, etc.)."}], "titre": "Ténèbres", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "1", "test_type": "", "description": "Le sorcier invoque une zone fixe de ténèbres magiques, de 10 m de diamètre, à une portée de 20 m pour une durée d’INT minutes. Toutes les créatures, même celles capables de voir dans le noir, sont aveuglées dans cette zone. ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Reptation", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "2", "test_type": "", "description": "Pendant INT minutes, le sorcier peut ramper de 5 m par action de mouvement sur les murs et les plafonds. Il peut lancer des sorts dans cette posture.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Strangulation", "actions": [{"dm": "1D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "Attaque magique", "description": "En réussissant un test opposé d’attaque magique (portée 20 m), le sorcier étouffe une créature vivante. La victime subit un dé malus à tous ses tests et [1d4°+INT] DM par round tant que le sorcier maintient sa concentration par une action de mouvement et la dépense de 1 PM par round. Si la victime sort de la portée du sort, il prend fin.", "test_oppose": true, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Manteau d’ombre", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le sorcier s’enveloppe d’ombre pendant INT minutes. Il gagne un dé bonus à tous les tests de discrétion et il impose un dé malus à tous les tests d’attaque à distance qui le prennent pour cible. S’il tombe à 0 PV pendant la durée du sort, il peut choisir de disparaître dans son ombre et de réapparaître à 1d6 km dans la direction de son choix avec 1d4° PV, 1d6 min plus tard (une dissipation de la magie (Maîtrise de la magie, voie du mage) lancée sur la zone où le sorcier a disparu dans son ombre avant sa réapparition au loin fait apparaître son corps et annule l’effet). Ceci met fin au sort et interdit de le lancer de nouveau avant le prochain crépuscule.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "CON", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests CON", "titre": "", "valeur": "+dé bonus", "condition": ""}, {"type": "DM", "titre": "", "valeur": "+2D4°", "condition": "Lorsqu’il lance un sort, il peut sacrifier 1d4° PV pour ajouter +2d4° aux DM de ce sort. S’il s’agit d’un sort dont les DM durent de round en round (comme strangulation), il peut sacrifier 1d4° PV chaque round."}], "titre": "Pacte ténébreux", "actions": null, "legacies": null, "capacites": [{"titre": "Vision dans le noir", "description": "Le sorcier voit dans le noir comme s’il s’agissait de pénombre. "}], "familiers": null}}', NULL, NULL, NULL),
	('2e403cb5-121f-42b8-8ef0-d7077540d654', '2026-04-02 09:25:28.601201+00', 'Voie de la précision', 'famille', NULL, 'c0636e1d-413c-41df-a9a7-a14c1a1db8b7', false, '{"rang1": {"bonus": null, "titre": "Joli coup", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "L’arquebusier ignore la pénalité appliquée pour une couverture partielle de sa cible (‐2 au test devient aucun malus) et réduit la pénalité pour une couverture importante à ‐2 (au lieu de ‐5)."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Défaut dans la cuirasse", "actions": [{"dm": "", "sort": false, "type": "A", "titre": "", "cout_mana": "", "test_type": "", "description": "L’arquebusier utilise une action d’attaque pour trouver le point faible de son adversaire et le viser. Au prochain round, il réalise ses attaques à distance sur cette cible contre une DEF de [10 + AGI de la cible] et il peut ignorer sa résistance aux DM ou sa réduction des DM (sauf si cette dernière est acquise parce que la cible est immatérielle : ombre, fantôme, etc.).  Si l’arquebusier utilise la capacité Combat de masse pour son action d’attaque en début de round, alors la capacité s’applique seulement aux tirs du round en cours.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": [{"type": "Critique", "titre": "", "valeur": "+1", "condition": "L’arquebusier inflige des critiques sur 19‐20 sur ses attaques avec une arme à distance. La plage de critique passe à 18‐20 à partir du rang 5."}], "titre": "Tir précis", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Tireur d’élite", "actions": [{"dm": "+2d4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "L’arquebusier prend le temps d’ajuster une cible au loin (distance minimum de 10 m). Il double la portée de son arme et ajoute +2d4° aux DM. Il ne peut pas utiliser cette capacité s’il est au contact d’un adversaire ou dans une position instable (par exemple dans un véhicule).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Tir fatal", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "S’il tire sur une créature dont le niveau (NC) est inférieur à la moitié du sien (arrondi au supérieur), l’arquebusier peut faire un test d’INT difficulté [10 + NC de la créature]. En cas de réussite, elle est morte. Dans tous les autres cas, elle subit les DM normaux.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('9a6aab40-c52c-4a79-a15c-44fae477bce6', '2026-06-23 10:51:08.97196+00', 'Voie du vent', 'profil', NULL, '366b95b3-7789-4c78-8353-7b098c2b1c5f', false, '{"rang1": {"bonus": [{"type": "Initiative", "titre": "", "valeur": "+3", "condition": "Le moine gagne +3 en Initiative"}, {"type": "Tests agilité", "titre": "", "valeur": "Rang+2", "condition": "Le moine gagne  son rang + 2 à tous les tests de saut, de course ou d’escalade."}], "titre": "Pas du vent", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le moine peut se déplacer avant et après avoir attaqué (mais il couvre toujours une distance normale, il divise son mouvement en deux). "}], "familiers": null}, "rang2": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le moine gagne +1 en DEF. Au rang 5, le bonus de DEF passe à +2."}], "titre": "Course du vent", "actions": null, "legacies": null, "capacites": [{"titre": "Action de mouvement", "description": "Le moine se déplace à une vitesse surhumaine, il gagne une action de mouvement lui permet de couvrir 15 m. Au rang 5,  l’action de mouvement lui permet de couvrir 20 m."}], "familiers": null}, "rang3": {"bonus": null, "titre": "Course des airs", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le moine défie les lois de la pesanteur et peut se déplacer sur des surfaces qui ne devraient pas supporter son poids. Il peut se déplacer sur l’eau, la neige, le feuillage des arbres ou courir sur un mur vertical. Il doit commencer et terminer son déplacement sur une surface normale. Il n’est plus ralenti par les terrains difficiles et il est désormais immunisé à l’état immobilisé."}], "familiers": null}, "rang4": {"bonus": [{"type": "AGI", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests AGI", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Agilité héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Passe‑muraille", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par combat, le moine peut rendre son corps intangible le temps de passer au travers d’un mur d’une épaisseur maximal de VOL mètres. Il ne peut rester immatériel qu’un court instant et reprend corps dès qu’il émerge du mur. Si le mur est trop épais, la capacité ne fonctionne pas. De plus le moine augmente définitivement de +1 la valeur de sa plus faible caractéristique (choisir en cas d’égalité).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('8f758358-5340-4ff1-835d-192e22125f69', '2026-04-02 09:25:28.601201+00', 'Voie de l''escrime', 'famille', NULL, '49f707ab-2da8-4901-92ad-b80c1fde5c0f', false, '{"rang1": {"bonus": null, "titre": "Précision", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le barde peut remplacer sa FOR par son AGI pour ses tests d’attaque au contact (mais pas aux DM) lorsqu’il emploie une arme légère à une main (les armes légères sont la dague, l’épée courte et la rapière)."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Feinte", "actions": [{"dm": "Rangx2 +2D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "CHA contre PER", "description": "Le barde effectue une attaque fictive pour déséquilibrer son adversaire et réalise ensuite une attaque mortelle. Faites un test opposé de CHA contre la PER de votre adversaire à ce round. Au round suivant, vous obtenez un bonus en attaque égal au double de votre rang dans la voie de l’escrime (+4 au rang 2, par exemple) sur votre première attaque au contact contre cet adversaire et, si votre feinte a réussi, +2d4° aux DM.", "test_oppose": true, "resultat_si_reussi": "échec"}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Intelligence du combat", "actions": [{"dm": "", "sort": false, "type": "M", "titre": "", "cout_mana": "", "test_type": "INT", "description": "Une fois par combat, le barde peut au choix désarmer, renverser ou aveugler pour une durée de 1 round un adversaire dont le NC est inférieur au sien en emportant un test opposé d’INT. S’il a réussi une feinte contre cet adversaire à son tour précédent, il bénéficie d’un bonus de +5 au test d’INT.", "test_oppose": true, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Attaque flamboyante (L)", "actions": [{"dm": "Arme +CHA", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le style de combat du barde est flamboyant et surprenant : Il effectue une attaque de contact avec une arme légère et obtient un bonus d’attaque et de DM égal à son CHA (en plus de sa FOR ou de son AGI).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "DM", "titre": "", "valeur": "+2D4°", "condition": "Lors d’une attaque au contact avec une arme légère, s’il obtient un résultat d’attaque supérieur ou égal à (la DEF de son adversaire + 10 points), le barde obtient un bonus de +2d4° aux DM de son attaque (les dés bonus ne sont jamais multipliés en cas de critique)."}], "titre": "Botte mortelle", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('549df3a2-b7a2-4f73-9e80-9f81268d5a19', '2026-04-02 09:25:28.601201+00', 'Voie du saltimbanque', 'famille', NULL, '49f707ab-2da8-4901-92ad-b80c1fde5c0f', false, '{"rang1": {"bonus": [{"type": "Tests acrobate", "titre": "", "valeur": "Rang+2", "condition": "Le barde ajoute son rang + 2 à tous les tests qu’il effectue pour réaliser des acrobaties, tenir en équilibre, faire des sauts ou de l’escalade."}], "titre": "Acrobate", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "Initiative", "titre": "", "valeur": "+CHA", "condition": ""}, {"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le barde gagne +1 en DEF (+2 au rang 4). "}, {"type": "Tests performance", "titre": "", "valeur": "+2", "condition": ""}], "titre": "Grâce féline", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Lanceur de couteau", "actions": [{"dm": "1D4 + AGI", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, en plus de ses autres actions, le barde peut lancer un couteau sur une cible à distance (portée 10 m) en réussissant un test d’attaque à distance. Cette attaque occasionne [1d4 + AGI] DM. Il peut exécuter cette action sans pénalité, même s’il est engagé en combat au contact avec un autre adversaire. Les DM passent à 1d4° au rang 5.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Liberté d’action", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le barde est immunisé à la peur et à tous les sorts qui asservissent l’esprit (possession, charme), il est immunisé aux états ralenti et immobilisé."}], "familiers": null}, "rang5": {"bonus": null, "titre": "Esquive acrobatique", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, le barde peut réaliser une esquive en réussissant un test d’attaque à distance contre une difficulté égale au résultat obtenu par son adversaire, lors de son attaque. En cas de réussite, le barde ne subit aucun DM. Si cette attaque était un critique, il subit tout de même des DM normaux (il annule donc l’effet critique «dommages doublés»).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('0d5ed2f2-b002-4adb-bd90-813aaa2ca267', '2026-04-30 14:54:18.957997+00', 'Voie de la nature', 'famille', NULL, '5c9cda86-9d6b-4f19-90dd-61c6358cdb8e', false, '{"rang1": {"bonus": [{"type": "Tests survie et récupération", "titre": "", "valeur": "Rang+2", "condition": "En milieu naturel, le druide ajoute son rang + 2 à tous les tests de survie (s’orienter, trouver un abri et de la nourriture, éviter les dangers, etc.) dont les tests de récupération effectués chaque nuit. "}], "titre": "Maître de la survie", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Lorsqu’il dort en milieu naturel, s’il utilise 1 DR, le druide guérit 1d4° PV supplémentaire."}], "familiers": null}, "rang2": {"bonus": [{"type": "Initiative", "titre": "", "valeur": "+3", "condition": "Le druide obtient un bonus de +3 en Initiative lors d''un combat en terrain difficile"}, {"type": "Attaque et DEF", "titre": "", "valeur": "+1", "condition": "Le druide obtient un bonus de +1 en attaque et en DEF lors d’un combat en terrain difficile"}], "titre": "Terrains difficiles", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le druide ne subit aucune pénalité de déplacement en terrain difficile (natation, neige, boue, broussailles, pente abrupte, etc.). "}], "familiers": null}, "rang3": {"bonus": null, "titre": "Bâton de druide", "actions": [{"dm": "1D4°+FOR ou AGI", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le druide combat avec les deux extrémités de son bâton de bois noueux (ou de son épieu). Lorsqu’il utilise cette capacité, il effectue deux attaques de contact pour lesquelles il peut remplacer sa FOR par son AGI en attaque s’il le souhaite. Il inflige [1d4°+FOR ou AGI au choix] DM par attaque (plus d’éventuels bonus si l’arme est magique) et il gagne +2 en DEF pendant 1 round.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "CON", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests CON", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Constitution héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Résistant", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le druide divise par deux tous les DM «naturels non magiques» : froid, feu, chutes, poisons... mais aussi les DM provoqués par les animaux ou les insectes (même géants). Cette protection s’étend aussi à ses compagnons animaux."}], "familiers": null}}', NULL, NULL, NULL),
	('056762d4-2c0f-4eb6-bed0-0c962c57b0d1', '2026-04-30 12:50:53.075205+00', 'Voie du soldat', 'famille', NULL, '01976a10-7e38-4233-b4d0-4b867f557327', false, '{"rang1": {"bonus": null, "titre": "Teigneux", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, si une créature à votre contact tente de s’éloigner de vous, vous obtenez une attaque au contact en action gratuite contre elle. De plus vous ajoutez votre rang + 2 aux tests destinés à résister à l’alcool et à la privation de nourriture ou de sommeil.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Prouesse", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Le guerrier réussit souvent des exploits physiques hors‐norme. Une fois par round, vous pouvez sacrifier 1d4° PV pour obtenir +5 sur un test de FOR ou de CON. Vous pouvez annoncer l’utilisation de cette capacité après avoir pris connaissance du résultat du test de caractéristique.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Piqûre de rappel", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Vous n’admettez pas qu’un adversaire vous ignore. Une fois par round, si un adversaire à votre contact attaque une autre créature que vous, vous obtenez une attaque en action gratuite contre lui. Si l’INT de cet adversaire est négative et que vous lui infligez des DM sur cette attaque, il vous prend automatiquement pour cible lors de sa prochaine attaque.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": [{"type": "FOR", "titre": "", "valeur": "+1", "condition": ""}, {"type": "tests FOR", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Force héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Rempart", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Vous pouvez désormais utiliser Teigneux contre un nombre d’adversaires égal à votre AGI + 2 à chaque round. Si vous réussissez cette attaque, le déplacement de votre adversaire est stoppé à l’endroit où vous l’avez attaqué. De plus vous gagnez +1 en DEF."}], "familiers": null}}', NULL, NULL, NULL),
	('50a9f94d-3336-43ae-a8a7-eca33f51e582', '2026-04-30 13:36:01.702841+00', 'Voie du golem', 'famille', NULL, 'baf24636-8c4a-4899-ba60-cc2c57280418', false, '{"rang1": {"bonus": [{"type": "Tests bricolages et sciences", "titre": "", "valeur": "Rang+2", "condition": "Le forgesort ajoute son rang + 2 à tous les tests de bricolage ou de science."}], "titre": "Grosse tête", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le forgesort remplace la force brutale par un peu de réflexion. Il peut effectuer un test d’INT au lieu d’un test de FOR (par exemple, il utilise un levier pour déplacer une lourde charge). De plus, au niveau où il acquiert cette capacité, il peut ajouter son INT à ses PV au lieu de la CON. "}], "familiers": null}, "rang2": {"bonus": null, "titre": "Golem", "actions": null, "legacies": null, "capacites": null, "familiers": [{"titre": "", "description": "Le golem est une créature humanoïde fabriquée par le forgesort pour lui servir de serviteur et de garde du corps. Il comprend des ordres simples, comme suivre, attaquer, monter la garde, mais il est incapable d’actions complexes ou nécessitant une motricité fine (comme de la couture. \nGOLEM | AGI ‐1 | CON +10 | FOR +1 | PER ‐3 | CHA ‐4 | INT ‐3 | VOL +4 | DEF [10 + rang dans la voie] | PV  [niv. du forgesort × 5]\n| INIT [Init. du forgesort] - Attaque : [attaque magique du forgesort] · DM 1d4°+1. "}]}, "rang3": {"bonus": null, "titre": "Protecteur", "actions": [{"dm": "", "sort": false, "type": "G", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par round, s’il est au contact d’un personnage, le golem peut s’interposer et subir les DM d’une attaque à sa place.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Statuette", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le forgesort transforme son golem en statuette d’une douzaine de centimètres de haut, recouverte de runes. Sous forme de statuette, le golem ne peut pas agir, mais il bénéficie d’une RD 10. À tout moment, le forgesort peut utiliser une action de mouvement pour jeter la figurine au sol et lui rendre sa taille normale et", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Golem supérieur", "actions": null, "legacies": null, "capacites": null, "familiers": [{"titre": "", "description": "Le forgesort peut améliorer son golem en choisissant une option parmi les suivantes. Le joueur peut choisir une option différente supplémentaire à chaque fois qu’il atteint le rang 5 dans une voie de forgesort.\n - Armure : +5 en DEF\n - Forme de félin : +3 en AGI et en DEF, dé bonus en AGI\n - Baliste : portée 20 m, [1d4°+AGI] DM\n - Grande taille : +2 PV par niveau et +1 en FOR et DM\n - Vol : des «sauts» de 40 m en action limitée\n - Cerveau amélioré : +2 en INT, PER et CHA, doué de parole\n - Puissant : +2 en FOR et aux DM, dé bonus en FOR\n - Arme à deux mains : +1d4° aux DM au contact"}]}}', NULL, NULL, NULL),
	('f06be550-30de-4c1b-85f8-15aecc766554', '2026-04-30 12:50:52.596703+00', 'Voie de la résistance', 'famille', NULL, '01976a10-7e38-4233-b4d0-4b867f557327', false, '{"rang1": {"bonus": [{"type": "PV max", "titre": "", "valeur": "Rang+2", "condition": "Le guerrier augmente sa valeur maximale de PV de rang + 2."}, {"type": "Tests résistance physique", "titre": "", "valeur": "Rang+2", "condition": " De plus, le guerrier ajoute son rang + 2 à tous les tests destinés à résister aux efforts physiques, à la chaleur ou au froid (conditions naturelles)."}], "titre": "Robustesse", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": [{"type": "Tests résistance état", "titre": "", "valeur": "+Rang", "condition": "Le guerrier obtient un bonus égal au rang atteint dans la voie pour tous les tests destinés à résister aux états étourdi et affaibli."}], "titre": "Résilient", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Désormais, il suffit de 10 min au guerrier pour bénéficier des effets d’une récupération rapide (au lieu de 30 min) et cela passe à 5 min au rang 4 de la voie. "}], "familiers": null}, "rang3": {"bonus": null, "titre": "Armure lourde", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Au choix le guerrier gagne +1 en DEF ou il apprend à porter l’armure de plaque (DEF +6) et désormais, il peut utiliser toutes les capacités de guerrier avec cette armure."}], "familiers": null}, "rang4": {"bonus": [{"type": "CON", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests CON", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Constitution héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+1", "condition": ""}], "titre": "Dur à cuire", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le guerrier , une fois par combat, lorsqu’il tombe à 0 PV, il peut encore agir un round avant de tomber inconscient. De plus, il ne subit plus de dé malus lorsqu’il est immobilisé et lorsqu’il est étourdi ; il peut encore attaquer, mais avec un dé malus."}], "familiers": null}}', NULL, NULL, NULL),
	('57a1ecb7-08dc-456b-ad65-7af8fb95856b', '2026-04-30 13:36:01.796452+00', 'Voie des runes', 'famille', NULL, 'baf24636-8c4a-4899-ba60-cc2c57280418', false, '{"rang1": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+2", "condition": "Le forgesort inscrit des runes de protection sur l’ensemble de son équipement et parfois jusque sur sa peau. Il obtient un bonus de +2 en DEF. Ce bonus augmente de +1 au rang 3 puis au rang 5. S’il possède un golem, il peut inscrire les runes sur celui‐ci avec le même effet."}], "titre": "Runes de défense", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Rune de puissance", "actions": [{"dm": "", "sort": true, "type": "L", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le forgesort enchante une arme pour 24 h. Une fois par combat, celle‐ci peut d’infliger les DM maximaux sur une attaque au contact ou à distance. Les dés bonus ne sont pas maximisés (attaque sournoise ou puissante, rage, etc.). Le joueur doit annoncer l’utilisation de la rune avant de lancer les dés de DM.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Rune de protection", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le forgesort enchante une armure (ou des vêtements) pour 24 h. Une fois par jour, celle‐ci permet d’ignorer les dommages d’une attaque que le personnage subit (au contact, magique ou à distance). Si l’attaque est un critique, le personnage subit tout de même les DM normaux (non‐critique). Pour activer la rune, le personnage doit être conscient et ne pas être surpris (action gratuite). Le joueur doit activer la rune avant de connaître le montant des DM.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Rune d’énergie (A)*", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le forgesort enchante un bijou pour une durée de 24 h. Une fois par combat, celui‐ci permet d’obtenir un d20 bonus sur un test de son choix déterminé au moment où l’effet est utilisé : test d’attaque ou de caractéristique.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Rune de garde*", "actions": [{"dm": "", "sort": true, "type": "", "titre": "", "cout_mana": "5", "test_type": "", "description": "En réalisant un rituel de 10 min, le forgesort inscrit des runes invisibles au sol. Il protège une zone allant jusqu’à 10 m de diamètre pendant 12 h. À chaque fois qu’une créature (de taille au moins très petite) pénètre dans la zone protégée, le sort produit un effet choisi (voir ci‐après) au moment où le sort est lancé. Les créatures présentes dans la zone pendant le rituel ne déclenchent pas le sort. Ce sort peut aussi être utilisé sur une porte ou un coffre. Il est automatiquement lancé avec la règle de concentration et coûte seulement 3 PM pour être lancé.\n - Alarme : un puissant gong retentit et la cible est étourdie pendant 1 round à moins de réussir un test de CON difficulté 15.\n- Feu : [3d4°+INT] DM de feu (un autre élément peut être choisi parmi foudre, froid, acide).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('b6d2ee75-60c8-4f50-9677-d3fdb9d405b8', '2026-04-30 13:36:01.453765+00', 'Voie des élixirs', 'famille', NULL, 'baf24636-8c4a-4899-ba60-cc2c57280418', false, '{"rang1": {"bonus": null, "titre": "Fortifiant", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Un breuvage qui guérit immédiatement 1d4° PV et permet de gagner un dé bonus aux trois prochains tests effectués dans une période de 30 min. En plus de cette recette, grâce à ses études, le forgesort ajoute son rang + 2 aux tests d’alchimie et de chimie ou pour identifier une potion (test difficulté 10 + rang du sort).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Feu grégeois", "actions": [{"dm": "2D4°", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le forgesort lance la fiole à une distance maximale de 10 m (réussite automatique). Le contenu explose dans un rayon de 3 m en infligeant 2d4° DM. Un test d’AGI difficulté [10 + INT du forgesort] réussi permet aux victimes de diviser les DM par deux. Les DM passent à 3d4° au rang 4 et 4d4° au rang 5.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Élixir de guérison", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le forgesort peut préparer un élixir qui soigne [2d4°+INT] PV au bout d’une minute ou guérit un empoisonnement de manière instantanée.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Élixirs mineurs", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le forgesort apprend à préparer des élixirs parmi Forme gazeuse, Maîtrise des éléments, Chute ralentie (voies de magicien) et Masque mortuaire (voie de sorcier). Il choisit un nombre d’élixirs égal à sa valeur d’INT (pour un maximum de 4).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Élixirs majeurs", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le forgesort apprend à préparer des élixirs parmi Invisibilité, Vol, Accélération (voies de magicien) et Masque du prédateur (voie de druide). Il choisit un nombre d’élixirs égal à sa valeur d’INT (pour un maximum de 4). Ces préparations comptent pour deux élixirs. ", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('e980fcd2-1f45-41e4-b901-ca825362e477', '2026-04-30 12:50:50.932285+00', 'Voie du combat', 'famille', NULL, '01976a10-7e38-4233-b4d0-4b867f557327', false, '{"rang1": {"bonus": [{"type": "Initiative", "titre": "", "valeur": "+3", "condition": ""}, {"type": "Tests AGI ou FOR", "titre": "", "valeur": "+3", "condition": "Le guerrier gagne +3 aux tests d’AGI ou de FOR pour éviter d’être immobilisé ou renversé"}], "titre": "Vivacité", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Une fois par combat, il obtient une action de mouvement supplémentaire à son tour."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Manœuvre", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le guerrier obtient un dé bonus lorsqu’il exécute une manœuvre en combat."}], "familiers": null}, "rang3": {"bonus": null, "titre": "Attaque puissante", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le guerrier peut choisir de s’imposer un dé malus sur une attaque au contact et il ajoute +2d4° aux DM. Cette capacité peut être utilisée avec Double attaque, Attaque circulaire ou Attaque parfaite (voir exemple). Transformez cette capacité en action limitée (L) pour obtenir +3d4° aux DM au lieu de +2d4°."}], "familiers": null}, "rang4": {"bonus": null, "titre": "Double attaque ", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le guerrier fait deux attaques au contact durant son tour avec un malus de ‐2.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Attaque circulaire", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le guerrier peut faire une attaque au contact avec un malus de ‐2 contre chaque adversaire engagé au contact avec lui (il fait un test d’attaque pour chaque adversaire).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('bb807fb1-b04f-47a4-9740-7ea82307b5fd', '2026-04-30 13:57:30.00386+00', 'Voie de la magie destructrice', 'famille', NULL, 'd9b341c4-cb8a-4ec0-ac65-f8b08a87f414', false, '{"rang1": {"bonus": null, "titre": "Arc de feu", "actions": [{"dm": "1D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "1", "test_type": "", "description": "Des flammes jaillissent des doigts tendus du magicien. Jusqu’à 3 cibles au contact subissent [1d4°+INT] DM, les cibles peuvent faire un test d’AGI difficulté [10 + INT] pour ne subir que la moitié des DM. Les DM passent à 2d4° au rang 4.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Saper les forces", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le magicien choisit une cible vivante située à une distance maximum de 10 m. S’il réussit un test opposé d’attaque magique, la cible subit un malus de ‐2 à ses tests de FOR, d’attaque au contact et aux DM, jusqu’à la fin du combat. Le sort n’est pas cumulable plusieurs fois sur la même cible.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Flèche de feu", "actions": [{"dm": "3D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Le magicien choisit une cible située à moins de 30 m. Si son attaque magique réussit (contre DEF), la cible subit [3d4°+INT] DM. Chaque round de combat suivant, le feu inflige 1d6 DM supplémentaires. Sur un résultat de 1 ou 2, le sort prend fin. Les DM sur la durée ne sont pas cumulables si le sort est lancé plusieurs fois.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Explosion de feu", "actions": [{"dm": "4D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "AGI", "description": "Le magicien choisit un point situé à moins de 30 m. Toutes les créatures (y compris le magicien et ses compagnons) se trouvant dans un rayon de 5 m autour de ce point subissent [4d4°+INT] DM et peuvent effectuer un test d’AGI difficulté [10 + INT] pour ne subir que la moitié des DM.", "test_oppose": true, "resultat_si_reussi": "DM/2"}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Appel de la foudre", "actions": [{"dm": "2D4°+INT", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Le magicien projette des traits de foudre sur toutes les cibles de son choix dans un rayon de 10 m autour de lui. Il fait un seul test d’attaque magique et toutes les créatures ciblées dont il atteint la DEF subissent [2d4°+INT] DM d’électricité.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('4224a637-33dc-49ab-bcdf-ea3ed2ad5315', '2026-04-30 13:57:30.200902+00', 'Voie de la magie protectrice', 'famille', NULL, 'd9b341c4-cb8a-4ec0-ac65-f8b08a87f414', false, '{"rang1": {"bonus": null, "titre": "Armure de mana", "actions": [{"dm": "", "sort": true, "type": "M", "titre": "", "cout_mana": "1", "test_type": "", "description": "Le magicien fait apparaître une protection magique chatoyante qui recouvre son corps et produit des étincelles à chaque fois qu’il encaisse un coup. Pendant INT minutes, la DEF du magicien augmente de +3. Cette valeur passe à +4 lorsque le personnage atteint le rang 3 dans la voie et augmente de +1 supplémentaire chaque fois que le personnage atteint le rang 5 dans une voie de magicien (ou dans la voie du mage). Ce sort ne se cumule jamais à une armure (il est considéré comme une armure).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang2": {"bonus": null, "titre": "Chute ralentie", "actions": [{"dm": "", "sort": true, "type": "G", "titre": "", "cout_mana": "2", "test_type": "", "description": "Le magicien peut désigner un nombre de cibles maximal (dont lui‐même) égal à son INT à une portée de 10 m, même en dehors de son tour. Les cibles peuvent chuter de n’importe quelle hauteur sans subir de dommages. En cas de chute inattendue, le magicien doit faire un test d’INT difficulté 15 pour chacun de ses compagnons afin d’avoir le temps de lancer le sort (réussite automatique sur lui‐même).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Déphasage", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "3", "test_type": "", "description": "Pendant [1d4°+INT] rounds, le corps du magicien se désincarne par intermittence, son image se brouille et tous les DM des attaques de contact ou à distance qu’il subit et qu’il inflige sont divisés par 2. Les DM des sorts ne sont pas réduits. Un personnage sous l’effet d’un sort d’armure de pierre ne peut se déphaser.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Cercle de protection", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "4", "test_type": "", "description": "Le magicien peut tracer un cercle sur le sol (environ 2 m de diamètre) afin de se protéger et d’inclure à sa protection un nombre de personnes égal à son INT. Une fois par round, lorsqu’un sort prend pour cible un personnage protégé, le magicien fait un test d’attaque magique opposé avec l’auteur du sort. Si le test est réussi, le sort adverse est annulé et n’a aucun effet. De plus, toutes les créatures invoquées (élémentaires, démons) et les morts‐vivants qui veulent attaquer une créature dans le cercle subissent un dé malus en attaque. Si le magicien sort du cercle, le sort est dissipé.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Interruption du temps", "actions": [{"dm": "", "sort": true, "type": "A", "titre": "", "cout_mana": "5", "test_type": "", "description": "Après avoir lancé ce sort, le personnage bénéficie d’INT rounds complets hors du temps durant lesquels il peut utiliser des sorts ou des objets (potions) sur lui‐même. Il ne peut interagir avec son environnement, ni se déplacer, seulement utiliser son propre équipement ou ses capacités sur lui‐même.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('888fccef-130f-4f53-947d-ab2f292d5168', '2026-04-02 09:22:11.092695+00', 'Voie du compagnon animal', 'famille', NULL, '69a984cb-e7d2-4f98-b109-69536f32a6b4', false, '{"rang1": {"bonus": null, "titre": "Compagnon animal", "actions": null, "legacies": null, "capacites": null, "familiers": [{"titre": "Le Loup", "description": "Le rôdeur obtient un loup pour compagnon animal. En combat, le loup attaque en même temps que le rôdeur. Le loup comprend des ordres simples comme : garde, reste, apporte, attaque, etc.\nAGI+1 | CON+1* | FOR+2 | PER+2* | CHA-2 | INT-3 | VOL+2\nDEF 12+rang dans la voie | PV niv rodeur x 4 | INIT du rodeur\n[Attaque au contact : attaque magique du rodeur  - DM 1D4+2]"}]}, "rang2": {"bonus": [{"type": "Attaque et Tests vigilance", "titre": "", "valeur": "+dé bonus", "condition": "Lorsque le loup et le rôdeur sont au contact, le loup obtient un dé bonus en attaque et le rôdeur obtient un dé bonus aux tests effectués pour pister ou pour éviter d’être surpris (Vigilance)."}], "titre": "Travail d’équipe", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang3": {"bonus": null, "titre": "Lien empathique (L) :", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Le rôdeur peut communiquer avec son loup par télépathie et le guérir à distance en dépensant ses propres PV (1 PV du rôdeur pour 1 PV octroyé au loup, sans limitation de quantité) au prix d’une action limitée.au loup, sans limitation de quantité) au prix d’une action limitée.", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}, "rang4": {"bonus": null, "titre": "Loup alpha", "actions": null, "legacies": null, "capacites": null, "familiers": [{"titre": "", "description": "Le loup du rôdeur devient un spécimen particulièrement puissant.\nMÂLE ALPHA | CON +3* | FOR +5 | DEF 18 | PV [Niveau × 5] | DM 1d4°+5"}]}, "rang5": {"bonus": [{"type": "DM", "titre": "", "valeur": "+1D4°", "condition": "Lorsque le loup attaque la même cible que le rôdeur, il obtient un bonus de 1d4° aux DM. "}, {"type": "PV", "titre": "", "valeur": "+2", "condition": "Chaque fois que le rôdeur dépense 1 PV pour soigner son loup, le loup récupère 2 PV. "}, {"type": "DEF", "titre": "", "valeur": "+1", "condition": "Le rôdeur et son loup augmentent leur DEF de +1 chaque fois que le personnage atteint le rang 5 dans une voie de rôdeur (celle‐ci incluse)."}], "titre": "Tactiques de meute", "actions": null, "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('4512e09c-57a2-4e14-a530-ecd84f9c39b5', '2026-04-02 09:51:26.325734+00', 'Voie de la méditation', 'famille', NULL, '366b95b3-7789-4c78-8353-7b098c2b1c5f', false, '{"rang1": {"bonus": [{"type": "Tests empathie", "titre": "", "valeur": "Rang+2", "condition": " De plus, il obtient un bonus égal à son rang + 2 à tous les tests d’empathie (pour analyser l’état émotionnel d’un interlocuteur) ou à ceux effectués pour apaiser un auditoire ou le convaincre de ne pas avoir recours à la violence."}], "titre": "Pacifisme", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Tant que le moine n’a réalisé aucune action offensive dans un combat, il bénéficie d’un bonus de +5 en DEF et divise par deux tous les DM subis par des attaques."}], "familiers": null}, "rang2": {"bonus": null, "titre": "Transe de guérison", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le moine peut méditer pendant 10 min et récupérer ainsi [1d4°+VOL] PV. Les soins augmentent de +1d4° chaque fois que le personnage atteint le rang 4 dans une voie de moine. Il doit terminer une récupération rapide avant de pouvoir à nouveau utiliser cette capacité et il ne peut pas l’utiliser plus de trois fois par jour."}], "familiers": null}, "rang3": {"bonus": [{"type": "DEF", "titre": "", "valeur": "+2", "condition": "Le moine  gagne +2 en DEF (ce bonus passe à +3 au rang 5)."}], "titre": "Maîtrise du ki", "actions": null, "legacies": null, "capacites": [{"titre": "", "description": "Le moine utilise sa force mentale pour augmenter son efficacité en combat. Il ajoute sa VOL à son Initiative et à ses PV. "}], "familiers": null}, "rang4": {"bonus": [{"type": "VOL", "titre": "", "valeur": "+1", "condition": ""}, {"type": "Tests VOL", "titre": "", "valeur": "+dé bonus", "condition": ""}], "titre": "Volonté héroïque", "actions": null, "legacies": null, "capacites": null, "familiers": null}, "rang5": {"bonus": null, "titre": "Projection mentale (L)", "actions": [{"dm": "", "sort": false, "type": "L", "titre": "", "cout_mana": "", "test_type": "", "description": "Une fois par jour, le moine entre en méditation et projette son esprit hors de son corps pendant [1d4°+VOL] minutes. Il ressemble à un ectoplasme de couleur blanche qui se déplace en volant à la vitesse de 10 m par round. Il peut passer au travers des murs, mais pas des êtres vivants ou des barrières magiques. Le moine ne perçoit le monde que par sa projection mentale, mais ressent les DM qui sont infligés à son corps. Il peut utiliser cette capacité une fois de plus chaque jour par rang 5 atteint dans une autre voie de moine. De plus le moine augmente définitivement de +1 la valeur de sa plus faible caractéristique (choisir en cas d’égalité).", "test_oppose": false, "resultat_si_reussi": ""}], "legacies": null, "capacites": null, "familiers": null}}', NULL, NULL, NULL),
	('0fa87223-11e4-4ef8-b85c-7e7c230060a3', '2026-05-12 12:17:08.699793+00', 'Voie de l''expert', 'prestige', NULL, NULL, true, '{"rang1": {"nom": "Capacité de néophyte", "type": "Autre", "description": "Choisissez une capacité de rang 1 de n''importe quelle voie issue d''un profil de votre famille"}, "rang2": {"nom": "Capacité d''initié", "type": "Autre", "description": "Choisissez une capacité de rang 2 de n''importe quelle voie issue d''un profil de votre famille"}, "rang3": {"nom": "Capacité de professionnel", "type": "Autre", "description": "Choisissez une capacité de rang 3 de n''importe quelle voie issue d''un profil de votre famille"}, "rang4": {"nom": "Capacité d''expert", "type": "Autre", "description": "Choisissez une capacité de rang 4 de n''importe quelle voie issue d''un profil de votre famille"}, "rang5": {"nom": "Capacité de maître", "type": "Autre", "description": "Choisissez une capacité de rang 5 de n''importe quelle voie issue d''un profil de votre famille"}}', '4afd8b4f-06c2-4432-823e-743464d27432', NULL, 'Cette voie n''est pas accessible aux profils hybrides qui ont choisi des voies issues d''une autre famille de profils que celle du profil principal. La voie de l''expert permet d''élargir les capacités du personnage à l''ensemble des profils de sa famille.
INSERT INTO "public"."wiki_pages" ("id", "title", "content", "category_id", "created_at", "campaign_id", "position_index", "subcategory_id", "is_public") VALUES
	('98a0779c-d6e8-4e1b-9d0f-016b396d1972', '2. Le Combat (Déroulement & Attaques)', '<table style="min-width: 251px;"><colgroup><col style="width: 201px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="201"><p>Règle</p></th><th colspan="1" rowspan="1"><p>Déclencheur</p></th><th colspan="1" rowspan="1"><p>Effets</p></th></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>L''initiative</strong></p></td><td colspan="1" rowspan="1"><p>10 + PER + mod</p></td><td colspan="1" rowspan="1"><p>Détermine l''ordre d''action (du plus grand au plus petit). En cas d''égalité, le plus haut niveau agit en premier. À niveau égal, les PJ agissent avant les PNJ. +3 si PER est une caractéristique supérieure.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>La surprise</strong></p></td><td colspan="1" rowspan="1"><p>test de PER contre 10 + AGI des assaillants</p></td><td colspan="1" rowspan="1"><p><br>Les cibles qui ratent le test n''ont aucune action et subissent -5 DEF au 1er round</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>Le round et les actions</strong></p></td><td colspan="1" rowspan="1"><p>1 rount = 6sec</p></td><td colspan="1" rowspan="1"><p>À son tour, un personnage choisit entre :<br>• <strong>1 Action Limitée (L)</strong><br>• <em>OU</em> <strong>1 Mouvement (M) + 1 Attaque (A)</strong><br>• <em>OU</em> <strong>2 Mouvements (M)</strong><br><br>(Il peut ajouter des Actions Gratuites (G) comme parler ou lâcher une arme )</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>Attaque au contact</strong></p></td><td colspan="1" rowspan="1"><p>1d20 + niveau +FOR</p></td><td colspan="1" rowspan="1"><p>Le résultat doit être ≥ à la DEF de la cible. Les Dommages (DM) sont : <code>Dé de l''arme + FOR</code>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>Attaque à distance</strong></p></td><td colspan="1" rowspan="1"><p>1d20 + niveau + AGI</p></td><td colspan="1" rowspan="1"><p>Le résultat doit être ≥ à la DEF de la cible. Les Dommages (DM) sont : <code>Dé de l''arme</code> (sans bonus de caractéristique sauf capacité spéciale)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>Attaque magique</strong></p></td><td colspan="1" rowspan="1"><p>1d20 + Niveau + VOL</p></td><td colspan="1" rowspan="1"><p>Le résultat doit être ≥ à la DEF de la cible. Les Dommages (DM) dépendent du sort lancé.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>Réussite Critique (Attaque)</strong></p></td><td colspan="1" rowspan="1"><p>Résultat de <strong>20</strong> naturel</p></td><td colspan="1" rowspan="1"><p>L''attaque réussit automatiquement. Les DM de l''arme sont <strong>doublés</strong> (bonus inclus, mais pas les dés supplémentaires). Les sorts magiques ne doublent pas mais gagnent <strong>+1d4 DM</strong></p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>Points de Vigueur (PV) à 0</strong></p></td><td colspan="1" rowspan="1"><p>Les PV tombent à 0</p></td><td colspan="1" rowspan="1"><p>Le personnage est inconscient et perd 1 Dé de Récupération (DR). S''il n''est pas soigné dans l''heure, il meurt. (Note : Toute attaque réussie inflige toujours au moins 1 DM ).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="201"><p><strong>Premiers Soins</strong></p></td><td colspan="1" rowspan="1"><p>Test d''INT (Médecine) DD10</p></td><td colspan="1" rowspan="1"><p>Sur un personnage à 0 PV. Si réussi, le PJ reprend connaissance en 1 minute et récupère 1d4 PV. En cas d''échec, il lui faut 30 minutes pour récupérer 1 PV.</p></td></tr></tbody></table><p></p>', '07ff50e2-df8a-43a0-8d62-9dd749e1dd94', '2026-06-23 16:50:46.243058+00', NULL, 3, NULL, true),
	('b987855c-bd09-457d-94d4-ce769aabae18', '1. Les Règles de Base', '<p>Dans Chroniques Oubliées Fantasy, vos actions sont libres, mais lorsqu''une situation est risquée ou que son issue est incertaine, le Meneur de Jeu (MJ) fait appel à un <strong>test</strong> .</p><h2>1. La Mécanique de Base : Le Test</h2><p>Il existe deux types de tests : les <strong>tests de caractéristique</strong> (pour accomplir une action) et les <strong>tests d''attaque</strong> (pour porter un coup en combat).</p><p>La formule est simple :</p><table style="min-width: 25px;"><colgroup><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p><strong>[Résultat du d20] + [Caractéristique] + [Modificateurs/Bonus de Compétence]</strong></p></th></tr></tbody></table><p><strong>Réussite :</strong> Le total doit être supérieur ou égal à la <strong>difficulté</strong> fixée par le MJ.</p><table style="min-width: 50px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><td colspan="1" rowspan="1"><p><strong>Qualificatif de l''action</strong></p></td><td colspan="1" rowspan="1"><p><strong>Difficulté</strong></p></td></tr><tr><td colspan="1" rowspan="1"><p>Facile</p></td><td colspan="1" rowspan="1"><p>5</p></td></tr><tr><td colspan="1" rowspan="1"><p>Moyenne</p></td><td colspan="1" rowspan="1"><p>10</p></td></tr><tr><td colspan="1" rowspan="1"><p>Difficile</p></td><td colspan="1" rowspan="1"><p>15</p></td></tr><tr><td colspan="1" rowspan="1"><p>Très difficile</p></td><td colspan="1" rowspan="1"><p>20</p></td></tr><tr><td colspan="1" rowspan="1"><p>Extrême</p></td><td colspan="1" rowspan="1"><p>25</p></td></tr><tr><td colspan="1" rowspan="1"><p>Abominable</p></td><td colspan="1" rowspan="1"><p>30</p></td></tr></tbody></table><h2>2. Dés Bonus et Dés Malus</h2><ul><li><p><strong>Dé Bonus :</strong> Lancez deux d20 et <strong>gardez le meilleur résultat</strong>.</p></li><li><p><strong>Dé Malus :</strong> Lancez deux d20 et <strong>gardez le pire résultat</strong>.</p></li></ul><p><em>Règles de cumul :</em> Plusieurs dés bonus (ou malus) ne se cumulent pas entre eux. Si vous avez à la fois un dé bonus et un dé malus, ils s''annulent mutuellement .</p><h2>3. Les Cas Extrêmes : 20 et 1</h2><ul><li><p><strong>Réussite Critique (20 "naturel") :</strong> L''action est une réussite automatique ! En dehors du combat, vous pouvez même suggérer au MJ un effet positif supplémentaire. En combat, une réussite critique double les dommages .</p></li><li><p><strong>Échec Critique (1 "naturel") :</strong> L''action échoue automatiquement, quels que soient vos bonus. Le MJ peut imposer une conséquence désagréable ou une complication .</p></li></ul><h2>4. Tests Opposés</h2><p>Lorsque deux personnages (ou créatures) s''affrontent directement (ex: bras de fer, intimidation, se cacher), ils font un <strong>test opposé</strong>.</p><ul><li><p>Chacun lance son d20 et ajoute ses modificateurs.</p></li><li><p>Celui qui obtient le <strong>plus haut résultat l''emporte</strong>.</p></li><li><p>En cas d''égalité, c''est un statu quo (ou on relance) .</p></li></ul><h2>5. Les Compétences (Pour les Tests de Caractéristiques)</h2><p>Une compétence est un savoir-faire (ex: Escalade, Érudition, Séduction).</p><p>Si vous possédez une capacité vous octroyant un bonus dans une compétence, vous ajoutez ce bonus à votre test de caractéristique .&nbsp;<em>Attention :</em> Un bonus de compétence ne s''applique <strong>jamais</strong> à un test d''attaque.</p><p>Le bonus maximum cumulé pour un test de caractéristique est plafonné à +15 (règle optionnelle / simplifiée).</p><h2>6. Gérer le Temps</h2><p><strong>Tests en Coopération :</strong> Un personnage peut vous aider. S''il réussit un test de difficulté 10, il vous donne un bonus de +2 à votre test (+4 sur un critique, parfois +5 pour la force brute) .</p><p><strong>Prendre son Temps :</strong> Pour une action sans stress, vous pouvez prendre 5 fois plus de temps. Vous ne lancez pas de d20, mais obtenez automatiquement un résultat de 10 sur le dé .</p><h2>7. Les Points de Chance (PC)</h2><p>Les PC sont une ressource précieuse pour forcer le destin. Dépenser 1 PC est une action gratuite qui peut se faire à tout moment.</p><ul><li><p><strong>Le Coup de Pouce :</strong> Après un jet de dé, dépensez 1 PC pour ajouter <strong>+10</strong> au résultat final de votre test .</p></li><li><p><strong>Sauver sa Peau :</strong> Si vous obtenez un échec critique (un 1 au d20), vous pouvez dépenser 1 PC. Si le nouveau total (1 + modificateurs + 10) égale ou dépasse la difficulté, l''échec devient un succès partiel (un "Oui, mais...") avec une complication choisie par le MJ .</p></li></ul><p><em>Règles et Limites :</em> 1 seul PC dépensable par test. Ils sont récupérés entièrement lors d''un passage de niveau, ou exceptionnellement accordés par le MJ pour une très bonne interprétation (Roleplay) .</p><p><em>Test de Chance :</em> Le MJ peut demander de lancer 1d6 (avec relance sur les 6) + vos PC pour déterminer au hasard qui est affecté par un événement .</p><p></p><p></p>', '07ff50e2-df8a-43a0-8d62-9dd749e1dd94', '2026-04-22 12:22:46.834119+00', NULL, 2, NULL, true),
	('05466fcb-5b2b-49a6-9720-af4176288fcc', '4. Magie, Sorts & Récupération', '<table style="min-width: 266px;"><colgroup><col style="width: 216px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="216"><p><strong>Règles</strong></p></th><th colspan="1" rowspan="1"><p><strong>Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Lancer un sort</strong></p></td><td colspan="1" rowspan="1"><p><em>Action variable</em></p></td><td colspan="1" rowspan="1"><p>Un lanceur de sort doit pouvoir parler et faire des gestes. Il est possible de lancer plusieurs sorts par round si le type d''action le permet (ex : un sort M et un sort A)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Contraintes d''équipement</strong></p></td><td colspan="1" rowspan="1"><p><em>Selon le type de magie</em></p></td><td colspan="1" rowspan="1"><p><strong>Magie profane :</strong> Nécessite au moins une main libre pour l''incantation gestuelle. Impossible avec arme + bouclier ou deux armes .<br><br><strong>Magie divine :</strong> Le prêtre/druide doit utiliser les armes autorisées par son culte, sinon la prière échoue.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Coût en Mana (PM)</strong></p></td><td colspan="1" rowspan="1"><p><em>Dépense de PM</em></p></td><td colspan="1" rowspan="1"><p>Lancer un sort coûte un nombre de PM égal à son Rang.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Concentration accrue</strong></p></td><td colspan="1" rowspan="1"><p><em>Pour les sorts de type (A)</em></p></td><td colspan="1" rowspan="1"><p>Le lanceur passe l''action du sort de (A) à (L) pour se concentrer. Cela réduit le coût du sort de <strong>2 PM</strong>. Ne s''applique pas aux sorts (L), (M) ou (G).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Brûlure de Mana</strong></p></td><td colspan="1" rowspan="1"><p><em>À 0 PM (Sacrifice de PV)</em></p></td><td colspan="1" rowspan="1"><p>Le lanceur sacrifie ses propres Points de Vigueur (PV) pour lancer un sort. Il perd un lancer de son <strong>Dé de Récupération (DR) par PM manquant</strong>. Ex: Un mage (DR d6) voulant lancer un sort de Rang 2 sacrifie 2d6 PV . Impossible pour les sorts de soins.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Sorts de Zone (en mêlée)</strong></p></td><td colspan="1" rowspan="1"><p><em>Sort de zone sur une cible au contact d''un allié</em></p></td><td colspan="1" rowspan="1"><p><strong>Cible privilégiée :</strong> La cible subit tous les DM. L''allié a +5 au test d''AGI pour diviser les DM par 2 .<br><br><strong>Allié privilégié :</strong> L''allié ne subit aucun DM. La cible divise les DM par 2 (si échec AGI) ou 0 DM (si réussite AGI).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Rendement Décroissant</strong></p></td><td colspan="1" rowspan="1"><p><em>Sorts répétés sur la même cible</em></p></td><td colspan="1" rowspan="1"><p>Les sorts nécessitant un test opposé ou infligeant un état (ex: contrôle mental) perdent en efficacité. La cible gagne un <strong>bonus cumulatif de +5</strong> à son test de résistance à chaque nouvelle tentative.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Fin d''un sort</strong></p></td><td colspan="1" rowspan="1"><p><em>Action Gratuite (G) ou Inconscience</em></p></td><td colspan="1" rowspan="1"><p>Le lanceur peut mettre fin à son sort en une action gratuite. S''il tombe inconscient, tous ses sorts actifs (non permanents) s''annulent immédiatement.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Récupération des PM</strong></p></td><td colspan="1" rowspan="1"><p><em>Récupération complète (8h)</em></p></td><td colspan="1" rowspan="1"><p>Le personnage regagne tous ses PM après une nuit de repos de 8h. Il doit passer 30 minutes à réviser, méditer ou prier.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="216"><p><strong>Perte du Grimoire</strong></p></td><td colspan="1" rowspan="1"><p><em>Pour les magiciens</em></p></td><td colspan="1" rowspan="1"><p>Sans son grimoire, le coût en PM des sorts du magicien est <strong>doublé</strong>. (Le réécrire coûte 1 jour de travail et 10 pièces d''argent par rang) .</p></td></tr></tbody></table><p></p>', '07ff50e2-df8a-43a0-8d62-9dd749e1dd94', '2026-06-24 14:57:06.401559+00', NULL, 5, NULL, true),
	('755ecd2e-81f5-481b-9c83-cfb87097c074', '3. Options Tactiques,  Manoeuvres & Etats', '<p>(A) = action d''&nbsp;<strong>Attaque</strong>&nbsp;(permet d''effectuer une attaque de son choix avec une arme, ou de faire une action comme ramasser une arme tombée au sol ou se relever.)<br>(M) = action de&nbsp;<strong>Mouvement</strong>&nbsp;(permet de se déplacer de 10 mètres, de dégainer/rengainer une arme, ou d''ouvrir une porte.)<br>(L) = action&nbsp;<strong>Limitée</strong>&nbsp;(sert à utiliser des capacités spéciales puissantes, à prendre et boire une potion, ou à s''équiper d''un bouclier)<br>(G) = action&nbsp;<strong>Gratuite</strong></p><table style="min-width: 482px;"><colgroup><col style="width: 185px;"><col style="width: 272px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="185"><p><strong>Règles</strong></p></th><th colspan="1" rowspan="1" colwidth="272"><p><strong>Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Attaque Assurée (A)</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Remplacer une attaque normale</p></td><td colspan="1" rowspan="1"><p>+5 au test d''attaque (contact ou distance), mais les DM sont divisés par 2</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Attaque Violente (A)</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Remplacer une attaque normale</p></td><td colspan="1" rowspan="1"><p><strong>-3</strong> au test d''attaque, mais <strong>+1d4 DM</strong> (ou -7 en attaque pour +2d4 DM).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Défense Partielle (A)</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Action d''attaque sacrifiée</p></td><td colspan="1" rowspan="1"><p><strong>+3 en DEF</strong> et aux tests opposés pour résister (pendant 1 round).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Défense Totale (L)</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Action limitée sacrifiée</p></td><td colspan="1" rowspan="1"><p><strong>+5 en DEF</strong> et aux tests opposés pour résister (pendant 1 round).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Soutenir (L)</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Être au contact de la cible</p></td><td colspan="1" rowspan="1"><p>Sacrifier toutes ses actions pour donner <strong>+5 en attaque au contact à un allié</strong> contre cette cible (valable 1 round).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Manoeuvres</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Action Limitée (L)</p></td><td colspan="1" rowspan="1"><p>Test opposé d''attaque au contact. N''inflige <strong>aucun DM</strong>, mais applique un effet tactique.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Distraire</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Manœuvre (L)</p></td><td colspan="1" rowspan="1"><p>La cible subit <strong>-10 aux tests de PER</strong> et <strong>-5 en DEF</strong> (1 round) et est vulnérable aux attaques sournoises.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Repousser*</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Manœuvre (L)</p></td><td colspan="1" rowspan="1"><p>Fait reculer la cible de <strong>[FOR attaquant + 3] mètres</strong>. Si elle est acculée, elle perd autant en DEF pour 1 round.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Bloquer*</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Manœuvre (L)</p></td><td colspan="1" rowspan="1"><p>La cible est <strong>immobilisée</strong> (1 round).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Désarmer*</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Manœuvre (L)</p></td><td colspan="1" rowspan="1"><p>La cible <strong>laisse tomber son arme</strong>. La ramasser lui coûtera son prochain tour.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Renverser*</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Manœuvre (L)</p></td><td colspan="1" rowspan="1"><p>La cible est <strong>renversée</strong> (le malus passe à -10 contre un quadrupède).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Aveuglé</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Altération d''état</p></td><td colspan="1" rowspan="1"><p><strong>-5</strong> en Init., attaque (contact) et DEF. <strong>-10</strong> en attaque à distance. Magie ciblée impossible.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Étourdi</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Altération d''état</p></td><td colspan="1" rowspan="1"><p><strong>Aucune action possible</strong> et <strong>-5 en DEF</strong>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Immobilisé</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Altération d''état</p></td><td colspan="1" rowspan="1"><p>Pas de déplacement possible et <strong>dé malus</strong> aux tests d''attaque.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Paralysé</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Altération d''état</p></td><td colspan="1" rowspan="1"><p>Aucune action possible. La cible est <strong>touchée automatiquement et subit un coup critique</strong>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Ralenti</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Altération d''état</p></td><td colspan="1" rowspan="1"><p><strong>Une seule action</strong> autorisée par round (une attaque M ou une action A).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="185"><p><strong>Renversé</strong></p></td><td colspan="1" rowspan="1" colwidth="272"><p>Altération d''état</p></td><td colspan="1" rowspan="1"><p><strong>-5 en attaque et en DEF</strong>. Nécessite d''utiliser une action d''attaque (A) pour se relever.</p></td></tr></tbody></table><p>*: Le test subit un malus de -5 par catégorie de taille de moins que la cible, et un bonus de +5 par catégorie de taille en plus.</p><p></p>', '07ff50e2-df8a-43a0-8d62-9dd749e1dd94', '2026-06-24 14:55:47.285745+00', NULL, 4, NULL, true),
	('adfc4272-d3db-4c0a-841e-1b62157037fa', '1. Création de Personnage', '<h2>1. Rôle et Concept</h2><p>Avant de regarder les règles, imaginez l''image mentale de votre alter ego. Quel rôle souhaitez-vous tenir au sein du groupe ? Êtes-vous une guerrière robuste, un lanceur de sorts, un mystique ou un filou discret ? Pensez à la complémentarité de votre groupe.</p><h2>2. Le Profil Principal</h2><p>Choisissez votre profil principal qui représente votre occupation d''origine. Il est classé parmi quatre grandes familles qui déterminent vos <strong>Points de Vigueur (PV)</strong> de base et votre équipement:</p><ul><li><p><strong>Aventuriers :</strong> Ce sont des débrouillards polyvalents. Ils possèdent <em>4 PV de base</em> et gagnent <em>1 Point de Chance supplémentaire.</em> Ils portent des armures légères et ont l''<em>Agilité</em> en caractéristique commune. Profils : Arquebusier, Barde, Rôdeur, Voleur .</p></li><li><p><strong>Combattants :</strong> Des experts de la guerre et des armes. Ils possèdent <em>5 PV de base</em> et portent des armures lourdes. Leur caractéristique est la <em>Force</em>. Profils : Barbare, Chevalier, Guerrier .</p></li><li><p><strong>Mages :</strong> Spécialistes de la magie profane. Ils possèdent <em>3 PV de base</em>, ne portent pas d''armure (sauf le forgesort) et ont l''<em>Intelligence</em> (ou le <em>Charisme</em>) en caractéristique commune. Les mages débutent avec 1 capacité de rang 2 supplémentaire. Profils : Ensorceleur, Forgesort, Magicien, Sorcier .</p></li><li><p><strong>Mystiques :</strong> Personnages à la vie spirituelle intense. Ils possèdent 4 PV de base, bénéficient de capacités martiales intermédiaires, et gagnent 1 Dé de Récupération supplémentaire . Leur caractéristique est la Volonté. Profils : Druide, Moine, Prêtre .</p></li></ul><h2>3. Le Peuple</h2><p>Choisissez parmi les 8 peuples disponibles : Demi-elfe, Demi-orc, Elfe haut, Elfe sylvain, Gnome, Halfelin, Humain ou Nain . Ce choix a deux conséquences mécaniques :</p><ul><li><p>Il modifie deux valeurs de vos caractéristiques (ou une seule pour les humains).</p></li><li><p>Il vous donne accès à une "<strong><em>voie de peuple</em></strong>" spécifique.</p></li></ul><h2>4. Les Caractéristiques</h2><p>Le personnage est défini par 7 <strong><em>caractéristiques</em></strong> (Agilité, Constitution, Force, Perception, Charisme, Intelligence, Volonté) . Choisissez l''une des trois séries d''attributs de base, et répartissez ces valeurs selon vos préférences, en privilégiant les caractéristiques utiles à votre profil:</p><ul><li><p><strong>Polyvalent :</strong> +2, +2, +2, +1, +1, +0, -1.</p></li><li><p><strong>Expert :</strong> +3, +2, +1, +1, +0, +0, -1.</p></li><li><p><strong>Spécialiste :</strong> +4, +2, +1, +0, +0, -1, -1.</p></li></ul><p><em>Note importante :</em> Appliquez ensuite le modificateur lié à votre peuple. Si vous utilisez la magie, placez au moins +1 dans la caractéristique de magie de votre classe.</p><h3><strong>5. Voies et Capacités</strong></h3><p>À la création, vous obtenez automatiquement trois capacités de rang 1:</p><ul><li><p>Choisissez deux voies parmi les cinq proposées par votre profil.</p></li><li><p>La troisième est la voie associée à votre peuple.</p></li><li><p><em>Spécificité des Mages :</em> Les mages obtiennent une capacité supplémentaire de rang 2 dans l''une de leurs voies, ou peuvent choisir la "voie du mage" .</p></li></ul><h2>6.Calculs et valeurs dérivées&nbsp;</h2><h3></h3><table style="min-width: 75px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Valeur</p></th><td colspan="1" rowspan="1"><p><strong>Calcul</strong></p></td><td colspan="1" rowspan="1"><p><strong>Spécificités</strong></p></td></tr><tr><th colspan="1" rowspan="1"><p>Point de Vigueur (PV)</p></th><td colspan="1" rowspan="1"><p>(2 × PV de la famille) + CONSTITUTION</p></td><td colspan="1" rowspan="1"><p>Représente la santé. PV de famille : Combattant (5), Aventurier/Mystique (4), Mage (3) .</p></td></tr><tr><th colspan="1" rowspan="1"><p>Dé de Récupération (DR)</p></th><td colspan="1" rowspan="1"><p>2 + CONSTITUTION</p></td><td colspan="1" rowspan="1"><p>Sert à régénérer les PV. Les Mystiques en ont <code>3 + CON</code> . Type de dé : Mage (d6), Aventurier/Mystique (d8), Combattant (d10) .</p></td></tr><tr><th colspan="1" rowspan="1"><p>Points de Chance (PC)</p></th><td colspan="1" rowspan="1"><p>2 + CHARISME</p></td><td colspan="1" rowspan="1"><p>Les Aventuriers reçoivent 1PC supplémentaire.</p></td></tr><tr><th colspan="1" rowspan="1"><p>Points de Mana (PM)</p></th><td colspan="1" rowspan="1"><p>VOLONTE + nombre de sorts appris</p></td><td colspan="1" rowspan="1"><p>Réservé aux personnages possédant au moins une capacité de sort (signalé par un *).</p></td></tr><tr><th colspan="1" rowspan="1"><p>Initiative (INIT)</p></th><td colspan="1" rowspan="1"><p>10 + PERCEPTION</p></td><td colspan="1" rowspan="1"><p>Détermine l''ordre d''action lors d''un combat.</p></td></tr><tr><th colspan="1" rowspan="1"><p>Défense (DEF)</p></th><td colspan="1" rowspan="1"><p>10 + AGILITE + armure/bouclier</p></td><td colspan="1" rowspan="1"><p>Permet d''esquiver ou d''encaisser les attaques.</p></td></tr><tr><th colspan="1" rowspan="1"><p>Attaque au contact</p></th><td colspan="1" rowspan="1"><p>1 + FORCE</p></td><td colspan="1" rowspan="1"><p>Pour attaquer avec une arme de mêlée. La Force s''ajoute aussi aux dommages infligés.</p></td></tr><tr><th colspan="1" rowspan="1"><p>Attaque à distance</p></th><td colspan="1" rowspan="1"><p>1 + AGILITE</p></td><td colspan="1" rowspan="1"><p>Pour attaquer avec une arme de tir ou de jet. L''Agilité ne s''ajoute pas aux dommages.</p></td></tr><tr><th colspan="1" rowspan="1"><p>Attaque Magique</p></th><td colspan="1" rowspan="1"><p>1 + VOLONTE</p></td><td colspan="1" rowspan="1"><p>Pour lancer des sorts offensifs.</p></td></tr></tbody></table><h2>7. Équipement &amp; Dommages</h2><ul><li><p><strong>Inventaire de base :</strong> Vous recevez l''équipement de votre profil et un sac d''aventurier (couverture, torche, briquet à silex, outre, gamelle, bourse de 2d6 pièces d''argent) .</p></li><li><p><strong>Dommages (DM) :</strong> Dépendent de l''arme (voir le chapitre Équipement) ou du sort utilisé. Ajoutez votre Force aux dommages de mêlée, mais n''ajoutez rien aux dommages à distance (sauf règle spécifique)t .</p></li></ul><h2>8. Touche Finale</h2><p>Donnez vie et épaisseur à votre personnage :</p><ul><li><p><strong>Apparence et Histoire :</strong> Déterminez ses caractéristiques physiques (âge, taille, poids) et son passé .</p></li><li><p><strong>Idéal et Travers :</strong> Choisissez ou tirez au sort un idéal héroïque et un travers pour guider l''interprétation de votre personnage en jeu .</p></li><li><p><strong>Langues :</strong> Vous parlez le Commun et la langue de votre peuple. Si votre Intelligence est positive (+1, +2...), vous maîtrisez une langue supplémentaire par point d''Intelligence . Un score négatif signifie que le personnage est analphabète.</p></li></ul><p></p>', 'fb748a9f-0d31-4ab3-9a1c-1fbdb69ab150', '2026-04-22 11:28:30.42286+00', NULL, 0, NULL, true),
	('d15a2a7c-b85a-4cce-b810-9c4d481ffba1', '2. Progression & Niveaux', '<p>Un personnage gagne généralement un niveau lorsqu''il a terminé une aventure ou franchi une étape importante dans une campagne .</p><h2>1. Les Bénéfices du Passage de Niveau</h2><p>À chaque passage de niveau, le personnage obtient automatiquement plusieurs avantages :</p><ul><li><p><strong>Points de Vigueur (PV) :</strong> Son maximum de PV augmente.</p></li><li><p><strong>Valeurs d''Attaque :</strong> Toutes ses valeurs d''attaque (contact, distance, magie) augmentent de +1, et ce jusqu''au niveau 10, qui représente le palier maximal de compétence de base .</p></li><li><p><strong>Capacités :</strong> Il gagne 2 points de capacité qu''il doit dépenser immédiatement .</p></li><li><p><strong>Points de Mana (PM) :</strong> Ses PM augmentent s''il apprend de nouveaux sorts.</p></li></ul><h2>2. Points de Vigueur (PV) et Constitution</h2><p>Le gain de PV à chaque niveau dépend de la famille de profils et de la valeur de Constitution (CON) du personnage :</p><table style="min-width: 75px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Combattants</p></th><th colspan="1" rowspan="1"><p>Aventuriers et Mystiques</p></th><th colspan="1" rowspan="1"><p>Mages</p></th></tr><tr><td colspan="1" rowspan="1"><ul><li><p>5 + CON</p></li></ul></td><td colspan="1" rowspan="1"><ul><li><p>4 + CON</p></li></ul></td><td colspan="1" rowspan="1"><ul><li><p>3 + CON</p></li></ul></td></tr></tbody></table><p><strong>Règle de Rétroactivité :</strong> Si la valeur de Constitution d''un personnage change en cours de jeu (grâce à une capacité par exemple), ses PV sont recalculés rétroactivement pour tous les niveaux déjà acquis .</p><h2>3. L''Acquisition des Capacités</h2><p>Les 2 points de capacité gagnés permettent d''améliorer son personnage, selon les règles suivantes :</p><p><strong>Coûts :</strong> Les rangs 1 et 2 d''une voie coûtent 1 point de capacité chacun. Les rangs 3 et supérieurs coûtent 2 points de capacité chacun.</p><p><strong>Prérequis :</strong> Pour acheter un rang supérieur dans une voie, il faut obligatoirement posséder tous les rangs inférieurs de cette même voie.</p><p><strong>Niveaux minimums requis :</strong>&nbsp;</p><table style="min-width: 200px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Rang 1</p></th><th colspan="1" rowspan="1"><p>Rang 2</p></th><th colspan="1" rowspan="1"><p>Rang 3</p></th><th colspan="1" rowspan="1"><p>&nbsp;Rang 4</p></th><th colspan="1" rowspan="1"><p>&nbsp;Rang 5</p></th><th colspan="1" rowspan="1"><p>Rang 6</p></th><th colspan="1" rowspan="1"><p>Rang 7</p></th><th colspan="1" rowspan="1"><p>Rang 8</p></th></tr><tr><td colspan="1" rowspan="1"><p>Niveau 1</p></td><td colspan="1" rowspan="1"><p>Niveau 2*</p></td><td colspan="1" rowspan="1"><p>Niveau 3</p></td><td colspan="1" rowspan="1"><p>Niveau 5</p></td><td colspan="1" rowspan="1"><p>Niveau 7</p></td><td colspan="1" rowspan="1"><p>Niveau 9</p></td><td colspan="1" rowspan="1"><p>Niveau 11</p></td><td colspan="1" rowspan="1"><p>Niveau 13</p></td></tr></tbody></table><p>*<strong><em>Capacité supplémentaire de mage</em></strong><em> : la capacité supplémentaire reçue par les mages au niveau 1 est une exception au niveau requis pour obtenir une capacité de rang 2. Toutefois, cette exception ne se prolonge pas au-delà du niveau 2 : les mages n''ont pas accès à une capacité de rang 3 avant les autres personnages.</em></p><p><strong>Nouvelles Voies :</strong> Il est possible d''ouvrir de nouvelles voies issues de son profil, mais un personnage ne peut jamais cumuler plus de six voies au total (en plus de sa voie de peuple).</p><p><strong>Point Orphelin :</strong> S''il ne reste qu''un seul point de capacité à dépenser et que seules des capacités coûtant 2 points sont disponibles, le joueur peut échanger ce point "orphelin" contre : 1 Point de Chance, ou 1 Dé de Récupération, ou 2 PV, ou 2 PM supplémentaires .</p><h2>4. Points de Mana (PM)</h2><p>Les PM n''augmentent pas automatiquement avec le niveau. Cependant, chaque nouveau sort appris lors du passage de niveau octroie 1 PM supplémentaire .</p><p><strong>Total des PM = nombre de capacités de sorts + VOL.</strong></p><h2>5. Les Dés Évolutifs (d4°)</h2><p>Certaines capacités mentionnent un dé avec le symbole ° (par exemple : d4°). Cela signifie que les dégâts ou l''efficacité de la capacité augmentent naturellement avec le niveau du personnage :</p><table style="min-width: 125px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Niveaux 1 à 5</p></th><th colspan="1" rowspan="1"><p>Niveaux 6 à 8</p></th><th colspan="1" rowspan="1"><p>Niveaux 9 à 11</p></th><th colspan="1" rowspan="1"><p>Niveaux 12 à 14</p></th><th colspan="1" rowspan="1"><p>Niveaux 15 et +</p></th></tr><tr><td colspan="1" rowspan="1"><p>D4</p></td><td colspan="1" rowspan="1"><p>D6</p></td><td colspan="1" rowspan="1"><p>D8</p></td><td colspan="1" rowspan="1"><p>D10</p></td><td colspan="1" rowspan="1"><p>D12</p></td></tr></tbody></table><h2>6. Voies de Prestige</h2><p>A partir de niveau 5 un personnage peut choisir une Voie de Prestige. Les Voies de Prestige sont des voies puissantes qui permettent à un personnage de se spécialiser dans un aspect particulier. Un PJ ne peut donc prendre qu''une seule Voie de Prestige dans toute sa carrière.</p><p>Il existe des Voies de Prestige spécifiques à chaque famille de profil ainsi que des Voies de Prestige génériques. Un personnage peut choisir sa Voie de Prestige soit dans la liste de la famille qui correspond à son profil principal, soit dans les Voies de Prestige Génériques. </p><p>Chaque voie de prestige : </p><ul><li><p>Est constituée de 5 rangs échelonnés du rang 4 au rang 8; </p></li><li><p>Octroie son propre bonus de vigueur, qui est utilisé lorsqu''un personnage choisit une capacité de cette voie lors d''un changement de niveau; </p></li><li><p>Impose les mêmes limitations d''armure que le profil principal du personnage, sauf si on est spécifié autrement. </p></li></ul><table style="min-width: 125px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Rang 4</p></th><th colspan="1" rowspan="1"><p>Rang 5</p></th><th colspan="1" rowspan="1"><p>Rang 6</p></th><th colspan="1" rowspan="1"><p>Rang 7</p></th><th colspan="1" rowspan="1"><p>Rang 8</p></th></tr><tr><td colspan="1" rowspan="1"><p>Niveau 5</p></td><td colspan="1" rowspan="1"><p>Niveau 7</p></td><td colspan="1" rowspan="1"><p>Niveau 9</p></td><td colspan="1" rowspan="1"><p>Niveau 11</p></td><td colspan="1" rowspan="1"><p>Niveau 13</p></td></tr></tbody></table><p><u>Prérequis </u>: Certaines voies de prestige peuvent nécessiter la prestation au préalable d''une capacité particulière. En général la seule condition d''accès est un prérequis d''interprétation. Il correspond à une action que le personnage doit effectuer ou à un événement qu''il a vécu, parfois de façon répétée. Dans ce cas le MJ a le dernier mot pour décider si les actions du PJ sont suffisantes pour ouvrir l''accès à la voie de prestige. </p><h2>7. Droit à l''Erreur : Changement d''Orientation</h2><p>Si un joueur regrette l''orientation de son personnage, il a le droit de se raviser. Lors d''un passage de niveau, il peut "oublier" une capacité pour la remplacer par une autre:</p><p><strong>Limite :</strong> 1 capacité oubliée par niveau (jusqu''à 2 capacités par niveau si le personnage a une Intelligence de +2 ou plus) .</p><p><strong>Cohérence :</strong> Il est interdit de créer des "trous" dans une voie. Il faut d''abord oublier le rang le plus élevé d''une voie avant d''oublier le rang précédent .</p><p><strong>Exceptions :</strong> Il est impossible d''oublier une capacité acquise gratuitement (comme la voie de peuple) ou d''oublier les deux premières capacités de rang 1 acquises à la création du personnage .</p><p></p><p></p>', 'fb748a9f-0d31-4ab3-9a1c-1fbdb69ab150', '2026-04-22 11:41:42.21171+00', NULL, 1, NULL, true),
	('5bb54bc3-adcb-4e84-8cbc-ce064699515f', '5. Règles de l''aventure & dangers', '<h1><strong>1. Voyage &amp; Déplacement</strong></h1><table style="min-width: 436px;"><colgroup><col style="width: 187px;"><col style="width: 224px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="187"><p><strong>Règle</strong></p></th><th colspan="1" rowspan="1" colwidth="224"><p><strong>Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="187"><p><strong>Vitesse de base</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>1 période de marche = 4h</p></td><td colspan="1" rowspan="1"><p>Un PJ parcourt <code>12 + CON - pénalité d''armure</code> km par période. L''armure portée dans le sac divise sa pénalité par 2.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="187"><p><strong>Terrains Difficiles</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>Hors-piste ou Forêt/Marais</p></td><td colspan="1" rowspan="1"><p>Hors piste : Vitesse <strong>/2</strong>. Terrain difficile : Vitesse <strong>/2</strong>. Si les deux s''appliquent : Vitesse <strong>/4</strong> .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="187"><p><strong>Montures &amp; Bêtes</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>Cheval / Mule</p></td><td colspan="1" rowspan="1"><p><strong>Cheval :</strong> 18 km/période. <strong>Mule de bât :</strong> +2 km et annule la pénalité d''armure.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="187"><p><strong>Marche Forcée</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>&gt; 2 périodes par jour</p></td><td colspan="1" rowspan="1"><p>Le PJ perd <strong>1 Dé de Récupération (DR)</strong> par période supplémentaire à pied . S''il n''a plus de DR, il est <em>Affaibli</em>. À cheval : Test de CON et CHA diff. 10 (+10 par période extra).</p></td></tr></tbody></table><h1><strong>2. Survie Quotidienne &amp; Bivouac</strong></h1><table style="min-width: 483px;"><colgroup><col style="width: 205px;"><col style="width: 253px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="205"><p><strong>Règle / Mécanique</strong></p></th><th colspan="1" rowspan="1" colwidth="253"><p><strong>Formule ou Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets &amp; Précisions</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="205"><p><strong>Dangerosité</strong></p></td><td colspan="1" rowspan="1" colwidth="253"><p>Définie par le MJ</p></td><td colspan="1" rowspan="1"><p>Fixe la Difficulté (Diff) et les Dommages (DM). Ex: Civilisée (Diff 10 / 1 DM), Naturelle (Diff 10 / 1d4° DM), Sauvage (Diff 15 / 2d4° DM), Mortelle (Diff 25 / 4d4° DM). Hiver : +5 Diff et +1d4° DM.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="205"><p><strong>Test de Progression</strong></p></td><td colspan="1" rowspan="1" colwidth="253"><p>1 Test de PER (Survie) / PJ</p></td><td colspan="1" rowspan="1"><p>Faire la somme des Succès et des Échecs du groupe. (1 Échec Critique ou marge de 10 = 2 échecs) .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="205"><p><strong>Résultat du Voyage</strong></p></td><td colspan="1" rowspan="1" colwidth="253"><p>Bilan des succès/échecs</p></td><td colspan="1" rowspan="1"><p><strong>3 échecs :</strong> Stoppé + Incident majeur. <strong>2 échecs :</strong> Ralenti + Incident majeur. <strong>-1 à +1 :</strong> Progression ordinaire + Incident mineur. <strong>2 succès :</strong> Bon bivouac. <strong>3 succès :</strong> Rapide + Bon bivouac .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="205"><p><strong>Test de Récupération</strong></p></td><td colspan="1" rowspan="1" colwidth="253"><p>Si le bivouac est inconfortable</p></td><td colspan="1" rowspan="1"><p>Test de CON contre la difficulté de la zone. Échec de 10+ ou critique : Le PJ perd 1 DR (ou <em>Affaibli</em> le lendemain s''il est à 0 DR).</p></td></tr></tbody></table><h1><strong>3. Obstacles &amp; Dangers Environnementaux</strong></h1><table style="min-width: 451px;"><colgroup><col style="width: 202px;"><col style="width: 224px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="202"><p><strong>Règle / Mécanique</strong></p></th><th colspan="1" rowspan="1" colwidth="224"><p><strong>Formule ou Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets &amp; Précisions</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="202"><p><strong>Saut en longueur</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>Test d''AGI</p></td><td colspan="1" rowspan="1"><p><strong>Avec élan :</strong> Difficulté = 3 x Distance en mètres. <strong>Sans élan :</strong> Difficulté = 6 x Distance en mètres.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="202"><p><strong>Chute</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>Jet de dégâts</p></td><td colspan="1" rowspan="1"><p><strong>1d4° DM par tranche de 3 mètres</strong> (max 10d4°). Test d''AGI Diff. 10 pour ignorer les 3 premiers mètres.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="202"><p><strong>Feu &amp; Incendie</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>Jet de dégâts + Test</p></td><td colspan="1" rowspan="1"><p>Le feu inflige <strong>1d6 DM par round</strong>. Incendie : Test de CON Diff. 5 (+2 par round suivant) ou suffocation (inconscience).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="202"><p><strong>Climat Extrême</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>Test de CON toutes les 6h</p></td><td colspan="1" rowspan="1"><p><strong>Chaleur (&gt;40°C) :</strong> Diff. 10 (+1 par degré au-dessus) ou 1d4° DM . <strong>Froid (&lt;0°C) :</strong> Diff. égale à la temp. négative ou 1d4° DM. (Vêtements chauds : +5 à +10 au test) .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="202"><p><strong>Forcer un Obstacle</strong></p></td><td colspan="1" rowspan="1" colwidth="224"><p>Porte / Barreaux / Mur</p></td><td colspan="1" rowspan="1"><p><strong>Forcer :</strong> Test de FOR contre la <em>Solidité</em> (Ex: Porte simple = 15, Barreaux = 20). <strong>Briser :</strong> PV de l''objet = Solidité, avec une Réduction de Dommages (RD).</p></td></tr></tbody></table><h1><strong>4. Pièges, Poisons &amp; Enquêtes</strong></h1><table style="min-width: 412px;"><colgroup><col style="width: 161px;"><col style="width: 226px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="161"><p><strong>Règle / Mécanique</strong></p></th><th colspan="1" rowspan="1" colwidth="226"><p><strong>Formule ou Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets &amp; Précisions</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="161"><p><strong>Les Pièges</strong></p></td><td colspan="1" rowspan="1" colwidth="226"><p>Action des joueurs</p></td><td colspan="1" rowspan="1"><p><strong>Détecter :</strong> Test de PER (+5 si recherche active, mais vitesse divisée par 2). <strong>Désamorcer :</strong> Test d''INT. En cas d''échec, le piège se déclenche.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="161"><p><strong>Les Poisons</strong></p></td><td colspan="1" rowspan="1" colwidth="226"><p>Contact / Ingestion / Blessure</p></td><td colspan="1" rowspan="1"><p>La victime fait un Test de CON (souvent Diff 10). Enduire une arme de poison nécessite un test d''INT Diff 10 (seule la première attaque réussie l''applique).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="161"><p><strong>L''Enquête</strong></p></td><td colspan="1" rowspan="1" colwidth="226"><p>Action de recherche (2d6 min)</p></td><td colspan="1" rowspan="1"><p><strong>Preuve matérielle :</strong> Test de PER .</p><p><strong>Déduction/Logique :</strong>&nbsp;Test d''INT .<br><strong>Obtenir un aveu/Baratiner :</strong>&nbsp;Test de CHA. </p></td></tr></tbody></table><p></p>', '07ff50e2-df8a-43a0-8d62-9dd749e1dd94', '2026-06-24 15:03:36.369955+00', NULL, 7, NULL, true),
	('508c76df-16be-42d5-b564-e8b7fdf8aca3', '6. Objets Magiques & Récompenses', '<h1><strong>1. Niveau de magie &amp; Valeur</strong></h1><table style="min-width: 475px;"><colgroup><col style="width: 210px;"><col style="width: 240px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="210"><p><strong>Règle</strong></p></th><th colspan="1" rowspan="1" colwidth="240"><p><strong>Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Armes &amp; Armures</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p><code>(Niveau x Niveau) x 200 po</code></p></td><td colspan="1" rowspan="1"><p>Le Niveau de Magie est égal au bonus (+1, +2...). Chaque propriété spéciale ajoute +1 ou +2 au niveau .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Parchemin / Potion</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p><code>(Rang x Rang) x 50 pa</code></p></td><td colspan="1" rowspan="1"><p>Consommable à usage unique. Niveau de magie = 0.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Baguette</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Valeur d''un parchemin x Charges</p></td><td colspan="1" rowspan="1"><p><code>Rang du sort</code> (si ≥ 30 charges) ou <code>Moitié du Rang</code> (si &lt; 30 charges).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Objet de pouvoir</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Pouvoir / Sort activable</p></td><td colspan="1" rowspan="1"><p>Niveau de magie = Rang du sort (ou des sorts) dupliqué.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Grimoire de pouvoir</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Action Limitée (L) et 1 PM</p></td><td colspan="1" rowspan="1"><p>Niveau de magie = <code>Somme des rangs des sorts inscrits / 3</code> (arrondi au plus proche).</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Objet de puissance</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Augmente une caractéristique</p></td><td colspan="1" rowspan="1"><p>Niveau de Magie = <code>Bonus accordé x 3</code>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Objet mineur</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Augmente PV, PC, DR ou PM</p></td><td colspan="1" rowspan="1"><p>Niveau = 1 par point de DR ou PC. 1 par tranche de 3 PM ou 5 PV.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="210"><p><strong>Objet de compétence</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Donne +5 sur un type de test</p></td><td colspan="1" rowspan="1"><p>Niveau de magie = 1.</p></td></tr></tbody></table><h1><strong>2. Limitation et Cumul des Bonus</strong></h1><table style="min-width: 471px;"><colgroup><col style="width: 206px;"><col style="width: 240px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="206"><p><strong>Règle</strong></p></th><th colspan="1" rowspan="1" colwidth="240"><p><strong>Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="206"><p><strong>Règle de Non-Cumul</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Multiples objets équipés</p></td><td colspan="1" rowspan="1"><p><strong>Impossible de cumuler</strong> plus d''un bonus d''objet magique sur un même jet ou une même valeur (ex: DEF). Seul le plus haut s''applique .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="206"><p><strong>Exceptions au Cumul</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Sorts et bonus indirects</p></td><td colspan="1" rowspan="1"><p>Le bonus d''un objet <strong>se cumule</strong> avec un sort (ex: Anneau + Armure de mage) ou un bonus indirect (ex: Ceinture de Force qui augmente la FOR + Épée magique) .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="206"><p><strong>Nombre d''objets (Classique)</strong></p></td><td colspan="1" rowspan="1" colwidth="240"><p>Recommandation pour le MJ</p></td><td colspan="1" rowspan="1"><p>À partir du niveau 3. Autour de <strong>2 objets majeurs</strong> et <strong>2 à 3 objets mineurs</strong> à haut niveau. <em>La somme totale des niveaux de magie ne devrait pas dépasser le niveau du PJ.</em></p></td></tr></tbody></table><h1><strong>3. Identifier un objet</strong></h1><table style="min-width: 493px;"><colgroup><col style="width: 220px;"><col style="width: 248px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="220"><p><strong>Règle</strong></p></th><th colspan="1" rowspan="1" colwidth="248"><p><strong>Déclencheur</strong></p></th><th colspan="1" rowspan="1"><p><strong>Effets</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="220"><p><strong>Lanceur de Sort</strong></p></td><td colspan="1" rowspan="1" colwidth="248"><p>Récupération rapide (30 min)</p></td><td colspan="1" rowspan="1"><p>Identifie un objet si son niveau de magie est ≤ au plus haut rang de sort maîtrisé par le PJ .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="220"><p><strong>Voie du Vagabond (Barde)</strong></p></td><td colspan="1" rowspan="1" colwidth="248"><p>Test d''INT (Rumeurs/Légendes)</p></td><td colspan="1" rowspan="1"><p>Difficulté = <code>25 - (2 x Niveau de Magie)</code>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="220"><p><strong>Voie du Maître d''Armes</strong></p></td><td colspan="1" rowspan="1" colwidth="248"><p>Manipulation (quelques rounds)</p></td><td colspan="1" rowspan="1"><p>Test d''INT difficulté <code>10 + (2 x Niveau de Magie)</code> .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="220"><p><strong>Voie des Élixirs (Forgesort)</strong></p></td><td colspan="1" rowspan="1" colwidth="248"><p>Manipulation (10 min)</p></td><td colspan="1" rowspan="1"><p>Identifier une potion : Test d''INT difficulté <code>5 + (5 x Rang du Sort)</code>.</p></td></tr></tbody></table><h1><strong>4. Propriétés Spéciales d''Armes</strong></h1><table style="min-width: 425px;"><colgroup><col style="width: 184px;"><col style="width: 216px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="184"><p><strong>Propriété</strong></p></th><th colspan="1" rowspan="1" colwidth="216"><p><strong>Effet</strong></p></th><th colspan="1" rowspan="1"><p><strong>Impact sur le Niveau de Magie</strong></p></th></tr><tr><td colspan="1" rowspan="1" colwidth="184"><p><strong>Projectiles magiques</strong></p></td><td colspan="1" rowspan="1" colwidth="216"><p>Tirés avec une arme magique</p></td><td colspan="1" rowspan="1"><p>Ne se cumulent pas (le plus haut bonus s''applique). En contrepartie, la portée augmente de <strong>+10m par point du bonus ignoré</strong> .</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="184"><p><strong>Affûtée</strong></p></td><td colspan="1" rowspan="1" colwidth="216"><p>Modification du critique</p></td><td colspan="1" rowspan="1"><p><strong>+1</strong> aux chances de critique ET <strong>+1d4° DM</strong> sur un critique. <em>(Ajoute +1 au Niveau de Magie)</em>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="184"><p><strong>Fléau des [X]</strong></p></td><td colspan="1" rowspan="1" colwidth="216"><p>Cible spécifique (Démons...)</p></td><td colspan="1" rowspan="1"><p>Inflige <strong>+1d4° DM</strong> contre cette catégorie. <em>(Ajoute +1 au Niveau de Magie)</em>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="184"><p><strong>Élémentaire</strong></p></td><td colspan="1" rowspan="1" colwidth="216"><p>Feu, Froid, Acide, etc.</p></td><td colspan="1" rowspan="1"><p>Inflige <strong>+1d4° DM</strong> de cet élément. <em>(Ajoute +2 au Niveau de Magie)</em>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="184"><p><strong>Parade</strong></p></td><td colspan="1" rowspan="1" colwidth="216"><p>Arme défensive</p></td><td colspan="1" rowspan="1"><p>Offre un bonus constant de Défense (DEF) équivalent. <em>(Ajoute le bonus de DEF au Niveau de Magie)</em>.</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="184"><p><strong>Doublement</strong></p></td><td colspan="1" rowspan="1" colwidth="216"><p>Propriété doublée</p></td><td colspan="1" rowspan="1"><p>On peut doubler une propriété (ex: Feu Intense = +2d4° DM). Le coût en Niveau de Magie est également doublé.</p></td></tr></tbody></table><p></p>', '07ff50e2-df8a-43a0-8d62-9dd749e1dd94', '2026-06-24 15:05:18.165076+00', NULL, 8, NULL, true),
	('66e0537f-1ea0-4238-b897-44f73ae81e8b', '3. Profils Hybrides', '<h1><strong>Qu''est-ce qu''un profil hybride ?</strong></h1><p><strong>Le profil adopté par le personnage de niveau 1 est appelé le</strong> <strong>profil principal</strong>. Il permet de déterminer le dé de récupération et certains avantages selon la famille de profils. Le profil principal représente la jeunesse et la formation initiale du personnage. Même si par la suite il change complètement d''orientation, il ne peut pas le renier.</p><p>Toutefois lorsque le personnage change de niveau, le joueur peut décider de choisir une nouvelle voie qui n''appartient pas à son profil principal. Il adopte alors un <strong>profil hybride</strong>. Tant qu''il reste au moins une voie sur les cinq de son profil dans laquelle le joueur n''a investi aucun point de capacité, le personnage peut avoir un profil hybride. En revanche sa personnage a acquis des capacités dont l''ensemble des cinq voies de son profil, il ne le peut plus.</p><p><strong>Le choix d''une voix en dehors du profil principal du personnage</strong> doit avoir une cohérence avec les événements vécus au cours du jeu. Le personnage devra au moins se donner les moyens de justifier l''acquisition de nouvelles capacités (ex : découvrir un antique grimoire de magie; dépenser de fonds personnels pour étudier; rencontrer un maître d''armes etc). Toutefois si la nouvelle voie appartient à la même famille de profils, l''évolution peut être suffisamment subtile pour ne pas nécessiter d''entraînement particulier (ex : un chevalier qui choisit la voie du combat). Inversement certains profils sont radicalement opposés, par exemple les primitifs barbares et les érudits magiciens. Il faudra de très bonnes raisons pour justifier leur assemblage. La liste exacte des combinaisons interdites est toutefois laissée à la discrétion de chaque MJ.</p><p><strong>Du point de vue des règles</strong>, obtenir une nouvelle capacité dans une voie en dehors du profil principal du personnage se passe de la façon habituelle --&gt; Les capacités coûtent 1 PC (rang 1-2), 2PC pour les rangs supérieurs.</p><h2><u>Points de vigueur</u></h2><p>Lorsque le personnage change de niveau, le nombre de points de vigueur qu''il obtient dépend du choix de ses capacités.</p><ul><li><p><strong>Si toutes les capacités proviennent de la même famille</strong> : Augmentez simplement vos points de vigueur en fonction de cette famille (Aventurier : 4 PV | Combattant : 5 PV | Mage : 3 PV | Mystique : 4 PV)</p></li><li><p><strong>Si toutes les capacités ne proviennent pas de la même famille</strong> : le nombre de PV obtenu à ce niveau est égal à <u>la moyenne des PV des deux familles concernées</u>. En cas de demi-PV arrondissez l''inférieur pour la première fois et notez-le sur votre fiche de personnage. Vous arrondirez au demi-PV supérieur la fois suivante et ainsi de suite une fois sur deux (ex : un personnage fait l''acquisition d''une capacité de combattant de rang 2 et d''une capacité de mage de rang 1. Il gagne donc : (5 + 3) / 2 = 4 PV). Alternativement le joueur peut choisir de dépenser un PC dans voie du peuple. Dans ce cas le nombre de PV pour cette capacité correspond à la famille de votre profil principal.</p></li></ul><h2><u>Armes &amp; Armures</u></h2><p>Le personnage apprend à utiliser les armes et armures d''un autre profil dès qu''il fait l’acquisition d''<strong>au moins deux rangs dans une voie de ce profil</strong>. On dit alors qu''il les maîtrise. Utiliser une arme sans la maîtrise impose un des malus en attaque.</p><p>Attention, chaque capacité impose toujours <strong>la restriction d''armure qui correspond au profil dont elle est issue</strong>. Par exemple, pas d''armure pour l''usage d''une capacité de moine, armure de cure maximum pour une capacité de voleur, etc.</p><p>Voici la <strong>liste des meilleures armures autorisées</strong> pour chaque voie :</p><table style="min-width: 100px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Aventuriers</p></th><th colspan="1" rowspan="1"><p>Combattants</p></th><th colspan="1" rowspan="1"><p>Mages</p></th><th colspan="1" rowspan="1"><p>Mystiques</p></th></tr><tr><td colspan="1" rowspan="1"><p>Voies d''arquebusier :<em> chemise de mailles</em></p></td><td colspan="1" rowspan="1"><p>Voies de barbare : <em>cuir renforcé</em></p></td><td colspan="1" rowspan="1"><p>Voies d''ensorceleur : <em>aucune</em></p></td><td colspan="1" rowspan="1"><p>Voies de druide : cuir simple</p></td></tr><tr><td colspan="1" rowspan="1"><p>Voies de barde :<em> cuir renforcé</em></p></td><td colspan="1" rowspan="1"><p>Voies de chevalier : <em>armure de plaque</em></p></td><td colspan="1" rowspan="1"><p>Voies de forgesort : <em>cuir simple</em></p></td><td colspan="1" rowspan="1"><p>Voies de moine : aucune</p></td></tr><tr><td colspan="1" rowspan="1"><p>Voies du rôdeur : <em>cuir renforcé</em></p></td><td colspan="1" rowspan="1"><p>Voies de guerrier :<em> cotte de mailles</em></p></td><td colspan="1" rowspan="1"><p>Voies de magicien : <em>aucune</em></p></td><td colspan="1" rowspan="1"><p>Voies de prêtre : chemise de mailles</p></td></tr><tr><td colspan="1" rowspan="1"><p>Voies de voleur : <em>cuir simple</em></p></td><td colspan="1" rowspan="1"><p></p></td><td colspan="1" rowspan="1"><p>Voies de sorcier : <em>aucune</em></p></td><td colspan="1" rowspan="1"><p></p></td></tr></tbody></table><h2><u>Magie &amp; Sorts</u></h2><p>La caractéristique utilisée pour les sorts dépend <strong>du profil dont la capacité est issue</strong>. Exemple :<em> un profil magicien/prêtre utilise l''intelligence pour ses sorts de magicien et le charisme pour ses sorts de prêtre, mais toujours la volonté pour sa valeur d''attaque magique.</em></p><p>Les sorts issus des voies de prêtres peuvent être lancés en portant n''importe quelle armure mais pour tous les autres profils l''armure isole le lanceur de sort du monde et atténue sa connexion avec les flux de magie. Pour lancer un sort en portant une armure qui n''est pas autorisée au profil dont la capacité est issue, le personnage doit respecter deux règles :</p><ul><li><p><strong>Maîtriser l''armure concernée</strong></p></li><li><p><strong>Dépenser davantage de points de mana </strong>: le nombre de PM supplémentaires à dépenser pour lancer le sort est égal au bonus de DEF de l''armure portée (sans tenir compte d''un éventuel bonus magique de l''armure). Dans le cas d''un sort de forge-sort, de druide ou de barde, faites seulement la différence entre l''armure portée et l''armure maximum autorisée pour ce profil (ex : <em>Si un personnage veut lancer un sort de magicien de rang 3 (3 PM) en armure de cuir (DEF +2 ), ça lui en coûtera 5 PV. Si un personnage en cotte de maille (DEF +5 ) veut lancer un sort de forgesort (DEF max +2), il doit dépenser 3 PV supplémentaires)</em></p></li></ul><h2><u>Capacités en doublon</u></h2><p> A force de se spécialiser, un profil hybride court le risque d''obtenir <strong>deux capacités quasi identiques</strong>. Dans ce cas si le MJ l''autorise, le joueur peut cocher cette capacité gratuitement et ainsi accéder aux capacités suivantes. Le MJ ne devra autoriser cette exception que si les deux capacités accordent le même avantage. Tout se passe comme si le personnage avait effectivement acquis la capacité. </p><h2><u>Cumul des caractéristiques </u></h2><p>Aucun test, aucune valeur (DEF) ni aucun jet de dé (DM) ne peut bénéficier plusieurs fois de l''ajout de la même caractéristique. Exemple. <em>Si un personnage utilise sa valeur d''AGI pour attaquer au contact avec précision du barde par exemple et d''attaque de éclairs du rôdeur, il n''ajoute pas une seconde fois son AGI en attaque mais il peut l''ajouter normalement au DM.</em></p><p></p><h1><strong>Créer un profil hybride au niveau 1 </strong></h1><p>Cette option devrait être réservée aux joueurs expérimentés qui ont une idée précise de ce qu''ils souhaitent obtenir et connaissent suffisamment les différents profils et voies pour l''obtenir.</p><p>Lorsque le profil hybride est construit à la création du personnage, avant toute chose, le joueur devra<strong> consulter son MJ </strong>pour discuter du concept qu''il veut développer. Seul le MJ est capable d''estimer si le concept colle à son cadre du jeu. Il devra aussi veiller à ce que le but du profil hybride ne soient pas seulement de produire une combinaison de capacités surpuissantes individuellement ou par leur synergie, <strong>sans aucune considération de cohérence narrative</strong>. </p><table style="min-width: 100px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Voies et capacités</p></th><th colspan="1" rowspan="1"><p>Points de vigueur</p></th><th colspan="1" rowspan="1"><p>Dé de récupération</p></th><th colspan="1" rowspan="1"><p>Armes &amp; Armures</p></th></tr><tr><td colspan="1" rowspan="1"><p>Le joueur choisit <strong>2 voies de son choix</strong>, issues de n''importe quel profil, et il obtient la capacité de rang 1 de chacune d''elles. Il doit alors<strong> choisir son profil principal parmi les 2 profils</strong> dont sont issus les voies qu''il a choisies. </p></td><td colspan="1" rowspan="1"><p>Au lieu de doubler les PV de sa famille de profils, le personnage<strong> ajoute les PV de chacun des deux profils </strong>dont sont issus ses capacités</p></td><td colspan="1" rowspan="1"><p> Le personnage obtient le dé de récupération et les avantages qui correspondent à la famille <strong>de son profil principal. </strong></p></td><td colspan="1" rowspan="1"><p>Le personnages maîtrisent<strong> toutes les armes et armures des 2 profils dont sont issus ces voies </strong>mais attention, l''utilisation d''une capacité est toujours <strong>limitée par l''armure autorisée du profil</strong> dont elle est issue. </p></td></tr></tbody></table><h2>Par défaut le personnage obtient l''équipement de son profil principal mais le MJ pourrait lui permettre d''en échanger une partie avec l''équipement de son autre profil. </h2><p></p>', 'fb748a9f-0d31-4ab3-9a1c-1fbdb69ab150', '2026-06-24 15:00:31.412071+00', NULL, 2, NULL, true),
	('c7723390-d1af-4912-b364-ce0eda41e085', 'L''intrigue', '<p><strong>Lysandre, reine et dirigeante de la Principauté d''Arly,</strong> était passionément amoureuse de son époux, <strong>le prince semi-elfde Laurelith</strong>, natif de la forêt de Bois-Dormant. Elle lui donna d''abord un fils, <strong>le prince Thomar</strong> puis, 5 années plus tard, une adorable petite fille prénommée <strong>Luthielle</strong>.</p><p>Il y a 12 ans, <strong>Roncecroc, un puissant dragon vert</strong>, commença à semer la terreur dans la forêt de Bois-Dormant. La reine ne prit pas immédiatement la mesure du problème, occupée par la négociation d''un important traité commercial avec <strong><em>le Ponant</em></strong>. Son époux était inquiet pour sa famille. Il prit l''intiative de se présenter à la renconter du grand ver, accompagné d''une escorte de puissants chevaliers. Laurelith ne dit pas la vérité à sa Reine sur le motif de son escapade. Il prétexta un voyage diplomatique et pour donner du poids à son mensonge, il emmena leur fille avec lui, se jurant de la laisser loin de la confrontation avec le dragon, et sous bonne garde. Le jeune prince Thomar, âgé de 8 ans à cette époque, était alors au service d''un noble chevalier en tant que page et il resta à la capitale. Hélas, le dragon n''avait que faire d''une rencontre diplomatique. Une nuit, il vola à la rencontre du prince et de sa suite. Lors d''une attaque éclair à la faveur des ténèbres, il massacra Laurelith, Luthielle et toute leur escrote dans leur sommeil.</p><p>La reine consumée par une terrible rage et une immense culpabilité. Elle prit la tête de la longue traque qui permit d''abattre le dragon et décapita le grand ver de sa propre main dans la forêt d''Astréis. Le crâne du monstre orne désormais la salle du trône et, à compter de ce jour, Lysandre le contemple chaque matin en se reprochant de n''avoir pas su protéger les siens...</p><p>Mais un dragon est un être primordial dont la puissance et le mal plongent leurs racine dans les origines de la magie. Même mort, ses os conservent un pouvoir. Jour après jour, le désespoir de la reine nourrit le crâne jusqu''à faire de la relique le réceptacle d''une magie puissante et incidieuse...</p><p></p><p>Sans que personne ne comprenne pourquoi, la reine commença à se porter de plus en plus mal, et la principauté aussi. Elle se détacha de son fils et des affaires du royaume et restait de plus en plus souvent seule dans la salle du trône, en contemplation du crâne. Un an après la mort du dragon, des démons à têtes de reptile émergèrent de l''ancien antre du ver. Les soldats envoyés pour combattre les créatures contractèrent <strong><em>une étrange maladie, une sorte de lèpre reptilienne</em></strong>. Il fallut les isoler afin de ne pas répandre la corruption. La reine fit alors construire la cité de <strong><em>Rampart</em></strong> autour de la faille maléfique afin d''y stationner les soldats lépreux et de protéger la principauté de la corruption.</p><p>Aujourd''hui,<strong><em> le comté de Ponant</em></strong>, avec lequel la reine a cessé tout échange commercial, a décidé de profiter de la faiblesse du pays et de sa dirigeante pour prendre le pouvoir. "<em>Dans l''intérêt du royaume</em>", ils ont réussi à corrompre un des guérisseurs de la reine et l''ont convaincu de lui administrer un faux remède qui la tue à petit feu. Elle est déjà très affaiblie et sa mort doit paraître la plus naturelle possible. En effet <strong>le comte Nosra du Ponant </strong>ne veut pas d''un vulgaire assassinat qui pourrait se retourner contre lui en mobilisant la population. Il souhaite donner l''illusion que la reine est morte de sa mystérieuse maladie. Il ne veut pas d''une guerre longue et coûteuse, il entend annexer un pays en état de marche, pas une nation rebelle. Et pour cela, il compte sur un plan machiavélique qui implique l''aide involontaire du prince héritier, Thomar d''Arly, pour lequel il a en tête un traitement spécial....</p><p></p><p><img src="https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/wiki-images/grimoire/a7a53ac4-89df-4fb1-99c9-cbb1e150f66c.png" style="max-width: 80%; float: left; margin: 0.25rem 1.5rem 0.75rem 0px;"></p>', '6e497cdc-5d8e-4434-821a-963d25c603a0', '2026-06-26 12:48:06.124822+00', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 11, NULL, false),
	('983aaa2e-147c-4df2-b6fc-6d76d7094d88', 'Les religions d''Osgild', '<h2>LA GENÈSE D’OSGILD VUE PAR LES HUMAINS</h2><p>Au commencement, <strong>Ada</strong>, la première femme et <strong>Ivu</strong>, le premier homme, furent créés par les dieux et autorisés à vivre parmi eux, dans un monde parfait. Ils peuplèrent le Paradis de leurs enfants et ils se multiplièrent, donnant naissance à de nombreux peuples.</p><p>Les <strong>Élus</strong> régnaient sur les animaux et toutes les autres créatures, mais, aveuglés par l’ambition de ressembler à leurs créateurs, ils essayèrent de s’emparer de l’immortalité. Hélas, dans leur arrogance, ils ne virent que trop tard où les menaient leurs expériences : le néant. Leur échec se solda par une catastrophe cosmique, le Paradis fut anéanti et la vie passa tout près de l’extinction. Les Élus furent expulsés sur <strong>le Mitan</strong> avec des fragments de néant,<strong> Kaer Ouros, les Pierres du Ciel</strong>.</p><p>Les survivants durent apprendre à prier, car ils avaient brisé le lien privilégié avec leurs créateurs. Pire, ils avaient ouvert la porte à la corruption du néant et, désormais, certains dieux n’étaient plus l’incarnation de la bienveillance, mais la personnification des valeurs destructrices engendrées par le néant.</p><p>Certains dieux portent parfois des noms différents chez les peuples non humains, par exemple Arshran est appelé Thürdim chez les nains.</p><p></p><h2>Principales religions d’Osgild</h2><table style="min-width: 584px;"><colgroup><col style="width: 304px;"><col style="width: 133px;"><col style="width: 122px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1" colwidth="304"><p>Divinité et domaine</p></th><th colspan="1" rowspan="1" colwidth="133"><p>Symbole</p></th><th colspan="1" rowspan="1" colwidth="122"><p>Arme sacrée</p></th><th colspan="1" rowspan="1"><p>Capacité divine</p></th></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Arcanna, déesse de la magie blanche</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une étoile</p></td><td colspan="1" rowspan="1" colwidth="122"><p>bâton</p></td><td colspan="1" rowspan="1"><p>maîtrise de la magie (voie du mage)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Arshran, dieu du feu et des forgerons</p><p></p></td><td colspan="1" rowspan="1" colwidth="133"><p>une enclume</p></td><td colspan="1" rowspan="1" colwidth="122"><p>marteau</p></td><td colspan="1" rowspan="1"><p>morsure de la forge (voie du métal – forgesort)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Arwendée, déesse de la chasse et des archers</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une flèche</p></td><td colspan="1" rowspan="1" colwidth="122"><p>arc</p></td><td colspan="1" rowspan="1"><p>archer émérite (voie de l’archer – rôdeur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Aurilla, déesse de la chance et des aventuriers</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un dé</p></td><td colspan="1" rowspan="1" colwidth="122"><p>épée courte</p></td><td colspan="1" rowspan="1"><p>charmant (voie de la séduction – barde)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Axënder, dieu du devoir et de l’honneur</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un heaume</p></td><td colspan="1" rowspan="1" colwidth="122"><p>épée longue</p></td><td colspan="1" rowspan="1"><p>sans peur (voie du meneur d’hommes – chevalier)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Basile, dieu de la gourmandise et de la nourriture</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un chou</p></td><td colspan="1" rowspan="1" colwidth="122"><p>gourdin</p></td><td colspan="1" rowspan="1"><p>nature nourricière (voie de la survie – rôdeur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Céres, dieu de l’agriculture et du travail</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un épi de blé</p></td><td colspan="1" rowspan="1" colwidth="122"><p>faux</p><p></p></td><td colspan="1" rowspan="1"><p>robustesse (voie de la résistance – guerrier)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Dénora, déesse de la compassion et de la guérison</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une main</p></td><td colspan="1" rowspan="1" colwidth="122"><p>bâton</p></td><td colspan="1" rowspan="1"><p>baies magiques (voie du protecteur – druide)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Ellona, déesse de la perception et de la vérité</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un oeil</p></td><td colspan="1" rowspan="1" colwidth="122"><p>arc court</p></td><td colspan="1" rowspan="1"><p>détection de l’invisible (voie de la divination – ensorceleur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Forthur, dieu du courage et des exploits</p><p></p></td><td colspan="1" rowspan="1" colwidth="133"><p>un poing</p></td><td colspan="1" rowspan="1" colwidth="122"><p>épée à 2 mains</p></td><td colspan="1" rowspan="1"><p>tour de force (voie de la brute – barbare)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Gaëlm, dieu des arts et des artistes</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une lyre</p></td><td colspan="1" rowspan="1" colwidth="122"><p>rapière</p></td><td colspan="1" rowspan="1"><p>chant de réconfort (voie du musicien – barde)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Gorom, dieu de la pierre et des architectes</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un marteau</p></td><td colspan="1" rowspan="1" colwidth="122"><p>marteau</p><p></p></td><td colspan="1" rowspan="1"><p>peau de pierre (voie du pagne – barbare)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Guardal, dieu de la loyauté et des gardiens</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un bouclier</p></td><td colspan="1" rowspan="1" colwidth="122"><p>masse</p></td><td colspan="1" rowspan="1"><p>protéger un allié (voie du bouclier – guerrier)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Hellion, dieu des voleurs et du pillage</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une cape</p></td><td colspan="1" rowspan="1" colwidth="122"><p>épée courte</p></td><td colspan="1" rowspan="1"><p>doigts agiles (voie du roublard – voleur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Irrion, dieu de l’ordre et de la noblesse</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une épée</p></td><td colspan="1" rowspan="1" colwidth="122"><p>épée longue</p></td><td colspan="1" rowspan="1"><p>autorité naturelle (voie de la noblesse – chevalier)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Jeweln, dieu des souterrains et des mineurs</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une pioche</p></td><td colspan="1" rowspan="1" colwidth="122"><p>pioche</p></td><td colspan="1" rowspan="1"><p>démolition (voie des explosifs – arquebusier)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Linnarré, déesse de la mer et des marins</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un coquillage</p></td><td colspan="1" rowspan="1" colwidth="122"><p>trident</p></td><td colspan="1" rowspan="1"><p>respiration aquatique (voie de la magie élémentaire – magicien)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Mélenna, déesse des forêts et des animaux</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un arbre</p></td><td colspan="1" rowspan="1" colwidth="122"><p>arc</p></td><td colspan="1" rowspan="1"><p>nature nourricière (voie de la survie – rôdeur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Méphistère, dieu de l’ombre et des secrets</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un masque</p></td><td colspan="1" rowspan="1" colwidth="122"><p>dague</p></td><td colspan="1" rowspan="1"><p>discrétion (voie de l’assassin – voleur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Mirandia, déesse du sommeil et des rêves</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une demi‑lune</p></td><td colspan="1" rowspan="1" colwidth="122"><p>bâton</p></td><td colspan="1" rowspan="1"><p>sommeil (voie de l’envoûteur – ensorceleur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Möndovaël, dieu des nomades et du voyage</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une botte</p></td><td colspan="1" rowspan="1" colwidth="122"><p>bâton</p></td><td colspan="1" rowspan="1"><p>survie (voie de la survie – rôdeur)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Morn, dieu de la mort et du passage dans l’au‑delà</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une faux</p></td><td colspan="1" rowspan="1" colwidth="122"><p>faux</p></td><td colspan="1" rowspan="1"><p>masque mortuaire (voie de la mort – sorcier)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Orbis, dieu du commerce et des marchands</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une pièce d’or</p></td><td colspan="1" rowspan="1" colwidth="122"><p>arbalète légère</p></td><td colspan="1" rowspan="1"><p>sac sans fond (voie des artefacts – forgesort)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Oumaros, dieu de l’air et des cieux</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un nuage</p></td><td colspan="1" rowspan="1" colwidth="122"><p>arc</p></td><td colspan="1" rowspan="1"><p>lévitation (voie des arcanes – magicien)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Perinde, déesse de la fertilité et des mères</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une femme enceinte</p></td><td colspan="1" rowspan="1" colwidth="122"><p>bâton</p></td><td colspan="1" rowspan="1"><p>prison végétale (voie des végétaux – druide)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Sélenne, déesse de la paix et de la liberté</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un oiseau blanc</p></td><td colspan="1" rowspan="1" colwidth="122"><p>mains nues</p></td><td colspan="1" rowspan="1"><p>poings de fer (voie du poing – moine)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Solar, dieu de la lumière et du savoir</p></td><td colspan="1" rowspan="1" colwidth="133"><p>le soleil</p></td><td colspan="1" rowspan="1" colwidth="122"><p>masse</p></td><td colspan="1" rowspan="1"><p>lumière (voie de la magie universelle – magicien)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Suëlle, déesse de la beauté et de l’amour</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un coeur</p></td><td colspan="1" rowspan="1" colwidth="122"><p>bâton</p></td><td colspan="1" rowspan="1"><p>beauté de la succube (voie du démon – sorcier)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Trenner, dieu du temps et des ancêtres</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un sablier</p></td><td colspan="1" rowspan="1" colwidth="122"><p>bâton</p></td><td colspan="1" rowspan="1"><p>rumeurs et légendes (voie du vagabond – barde)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Tulsadüm, dieu de la jungle et des reptiles</p></td><td colspan="1" rowspan="1" colwidth="133"><p>un serpent qui se mord la queue</p></td><td colspan="1" rowspan="1" colwidth="122"><p>arc court</p></td><td colspan="1" rowspan="1"><p>terrains difficiles (voie de la nature – druide)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Tyriolith, dieu du combat contre le chaos et du feu purificateur</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une flamme</p></td><td colspan="1" rowspan="1" colwidth="122"><p>masse</p></td><td colspan="1" rowspan="1"><p>feu grégeois 3/jours (voie des élixirs – forgesort)</p></td></tr><tr><td colspan="1" rowspan="1" colwidth="304"><p>Vorona, déesse de la justice et de la loi</p></td><td colspan="1" rowspan="1" colwidth="133"><p>une balance</p></td><td colspan="1" rowspan="1" colwidth="122"><p>épée longue</p></td><td colspan="1" rowspan="1"><p>sans peur (voie du meneur d’hommes – chevalier)</p></td></tr></tbody></table><p></p><p></p><p></p><p></p><p></p><p></p>', 'b4f1d496-9120-4edf-9df9-62e6bd48297a', '2026-06-26 17:20:49.345455+00', NULL, 10, NULL, true),
	('3716462d-6570-4930-8668-34abac0eb560', 'Les terres d''Osgild', '<p>Les Terres d’Osgild ne sont qu’une petite portion d’un continent plus vaste. Cette région mesure environ 1 500 km d’est en ouest pour 1 000 km du nord au sud, et elle est encadrée par deux étendues maritimes : la mer Mauve à l’est et l’océan Pélurique à l’ouest. </p><p>Les nains et les elfes nomment cette zone géographique le Mitan. Osgild est en effet le nom d’un ancien empire, fondé il y a environ 2 500 ans par les humains aux dépens des peuples anciens. L’empire termina son expansion, il y a environ 1 500 ans et s’effondra cinq siècles plus tard. Six siècles de chaos et de fluctuations suivirent durant une période connue sous le nom des âges sombres qui vit nains et elfes se réapproprier une partie du territoire perdu. </p><p>La région a obtenu ses frontières et sa structure géopolitique actuelle il y a un peu plus de trois siècles, lors du traité de paix de Monastir. Il fut signé entre les deux plus grandes nations des Terres d’Osgild, la principauté d’Arly et les marches du Piémont, et marque l’an 1 de la datation  officielle des nations humaines. La route qui relie Ferrance (capitale de la principauté d’Arly) à Port‑Libre (une cité franche des marches du Piémont) est le chemin connu le plus court d’un bord à l’autre du continent. Cela en fait un axe commercial d’exception où transitent des marchandises exotiques et des voyageurs de pays lointains, voire d’autres continents.</p><p><img src="https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/wiki-images/grimoire/47d20405-18de-4732-9ae7-7b9faea6b42b.png" style="max-width: 80%; float: left; margin: 0.25rem 1.5rem 0.75rem 0px;"></p>', 'b4f1d496-9120-4edf-9df9-62e6bd48297a', '2026-06-26 17:32:02.927718+00', NULL, 11, NULL, true),
	('dc40e2e1-0c1d-4be1-b4f4-04678523863b', 'Un peu de contexte', '<p>La campagne débute à proximité de<strong> Clairva</strong>l. Le village se situe dans la <strong>forêt de Myvriel,</strong> une région peu peuplée à la frontière nord d''une nation nommée <strong>Principauté d''Arly</strong>, dont le dirigeant est <strong>la reine Lysandre</strong>.</p><p>La principauté fait partie d''une région plus vaste appelée <strong>les Terres d''Osgild,</strong> du nom d''un ancien empire qui s''effondra il y a un millénaire. La région a obtenu ses frontières et sa structure géopolitique actuelles il y a un peu moins de 300ans, lors du <em>traité de Monastir</em> qui marque l''an 0 de la datation officielle des nations humaines. Nous sommes actuellement en l''an 285 PM (post-Monastir).</p><p>La principauté est une nation vaste et riche. Sa capitale est <strong>Ferrance</strong>, un important port commercial qui reçoit les navires en provenance de l''océan Pélurique. Elle est la porte d''entrée vers toutes les terres d''Osgild. Les nations voisines de la Principauté sont<strong> le comté de Ponant</strong>, au nord-Ouest, et <strong>les Marches du Piémont</strong> à l''est. Deux anciennes régions de l''empire d''Osgild ayant signé le traité de Monastir. Il faut ajouter à cela <strong>les nains des monts argentés</strong> au sud, <strong>les elfes de la forêt de Hautesylve</strong> à l''est de Clairval, et enfin <strong>les orques du désert des Morteroches</strong>, juste au-dessus.</p><p></p><p><img src="https://njizvgfmyltubqlmkrde.supabase.co/storage/v1/object/public/wiki-images/grimoire/de181828-53a8-4a90-91bf-5a7fcb8d941d.jpg" style="max-width: 45%; float: left; margin: 0.25rem 1.5rem 0.75rem 0px;"></p>', '6e497cdc-5d8e-4434-821a-963d25c603a0', '2026-06-26 12:22:26.299026+00', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 10, NULL, false),
	('f390867c-bf7c-4ad1-a549-2f515bbaf90e', '4. Equipement', '<h1><strong>Matériel d''aventurier</strong></h1><h2><u>Système monétaire</u></h2><p>Tous les prix sont exprimés en pièces d''argent et pièces de cuivre. Les pièces d''or sont rares et précieuses et la plupart des paysans ne les utilisent rarement. Seuls les princes, les rois et les aventuriers ont vu un jour une pièce de platine.</p><p>1 PO = 10 PA = 100 PC</p><p>1 PP = 10 PO</p><h2><u>Acheter de l''équipement</u></h2><p>La liste des équipements qui est issue n''est pas exhaustive et le MJ décide ce qui est localement disponible, ce qui ne l''est pas, ainsi que les tarifs appliqués.</p><p></p><h1><strong>Armes</strong></h1><p>Un personnage peut utiliser soit :</p><ul><li><p>une arme à une main et un bouclier,</p></li><li><p>une arme à deux mains,</p></li><li><p>deux armes à une main,</p></li><li><p>une seule arme à une main (laisse une main libre pour tenir un autre objet)</p></li></ul><p>Dégainer ou rengainer une arme est <strong>une action de mouvement </strong>qui peut être accompagnée d''un déplacement de 10 mètres. La jeter au sol est une<strong> action gratuite</strong> mais la ramasser au sol est une <strong>action d''attaque</strong>. Pour les armes de lancers, se saisir de l''arme est inclus dans l<strong>''action d''attaque</strong>, pour peu que la main utilisée soit libre.</p><p>Chaque profil détermine la maîtrise de l''arme du personnage. Si le personnage utilise une arme qu''il ne maîtrise pas, il subit un Dé malus au test de l''attaque.</p><h2><u>Armes d''attaque au contact</u></h2><p><strong>DM</strong> : Sauf exception les DM des armes de contact sont composés d''un type de dé auquel on ajoute la FOR. Certaines armes disposent de deux valeurs, la première correspondant à l''utilisation avec une main et la seconde avec deux mains. Dans le cas du combat à main nue les DM sont généralement temporaires. Certaines armes peuvent également infliger des dégâts temporaires. C''est alors indiquer dans la colonne notes complémentaires.</p><p><strong>Types de DM</strong> : les armes peuvent provoquer trois types de DM</p><table style="min-width: 75px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Contondant</p></th><th colspan="1" rowspan="1"><p>Perforant</p></th><th colspan="1" rowspan="1"><p>Tranchant</p></th></tr><tr><td colspan="1" rowspan="1"><p>l''impact provoque des contusions et brise les os.</p></td><td colspan="1" rowspan="1"><p>la pointe perce la chair et s''enfonce profondément dans le corps.</p></td><td colspan="1" rowspan="1"><p>la lame découpe les chairs, formant de longues entailles.</p></td></tr></tbody></table><p>Le type de DM n''a une importance que lorsque les personnages affrontent certaines créatures particulières. P<em>ar exemple les squelettes sont résistants aux DM tranchants et perforants, tandis qu''ils subissent des DM ordinaires des armes contondantes.</em></p><p><strong>Catégorie d''armes : </strong>on distingue plusieurs catégories d''armes :</p><table style="min-width: 75px;"><colgroup><col style="min-width: 25px;"><col style="min-width: 25px;"><col style="min-width: 25px;"></colgroup><tbody><tr><th colspan="1" rowspan="1"><p>Arme légère</p></th><th colspan="1" rowspan="1"><p>Armes à une ou deux mains</p></th><th colspan="1" rowspan="1"><p>Armes à deux mains</p></th></tr><tr><td colspan="1" rowspan="1"><p>Ce sont des armes de duel souvent utilisées par les combattants légers. Elles permettent<strong> l''utilisation de certaines capacités</strong> de barde ou de voleur (comme l''attaque sournoise). Si le personnage manie un bouclier, l''arme n''est plus considérée comme légère. La vivelame est un cas à part, elle est considérée comme une arme légère, la plupart du temps, mais pas pour les attaques sournoises.</p></td><td colspan="1" rowspan="1"><p>Comme leur nom l''indique, ces armes peuvent être utilisées avec une ou deux mains au choix du combattant. <strong>Les DM sont alors plus ou moins importants.</strong> L''avantage de ces armes est l<strong>''adaptabilité </strong>selon la situation.</p></td><td colspan="1" rowspan="1"><p>Comme indiqué en introduction, ces armes qui <strong>infligent des DM plus importants</strong> ne peuvent être utilisées en même temps qu''un bouclier ou une torche.</p></td></tr></tbody></table><h2><u>Arme d''attaque à distance</u></h2><p><strong>Portée </strong>: La portée indique à quelle distance l''arme est efficace. Au-delà, le tireur subit un dé malus sur son test d''attaque à distance. La portée maximale à laquelle l''arme peut être utilisée est égale au double de la distance indiquée.</p><p><strong>DM </strong>: Les DM des armes d''attaque à distance ne reçoivent pas de bonus de caractéristiques du personnage qu''ils utilise.</p><p><strong>Types de DM</strong> : Les armes d''attaque à distance ne provoquent que de DM perforant.</p><p><strong>Recharger </strong>: Il n''est pas possible de recharger une arbalète ou une arme à poudre si vous avez un adversaire actif (par opposition à "incapable d''agir) à votre contact</p><p></p><h1><strong>Armure</strong></h1><p><strong>Armure maîtrisée :</strong> il n''y a pas de maîtrise d''armure à proprement parler. Un personnage peut toujours enfiler une armure de plaque ou utiliser un bouclier profite sous bonus indifférents. Toutefois les voies de chaque profil sont associées à un type d''armure maximale. Si vous utilisez une armure trop lourde, toutes les capacités restantes à une armure plus légère vous seront interdites.</p><p><strong>AGI maximal </strong>: La valeur maximale d''AGI d''un personnage est déterminée par l''armure qu''il porte. Les personnages avec une haute valeur d''AGI n''ont donc aucun intérêt à porter une armure trop lourde. La règle est calibrée de façon qu''aucun personnage ne puisse dépasser un bonus de DEF de +8 en cumulant AGI + Armure.</p><p><strong>Malus d''armure</strong> : les armures infligent des malus d''encombrement aux tests d''AGI. Ajoutez la valeur de DEF de l''armure à la difficulté de tous les tests d''AGI effectués par le personnage. Pour certains tests de survie vous pouvez aussi imposer ce malus. Si vous avez une armure magique, non seulement le bonus de magie ne vous manque pas le bonus d''encombrement mais en plus il le réduit (min 0).</p><p></p>', 'fb748a9f-0d31-4ab3-9a1c-1fbdb69ab150', '2026-07-16 15:13:19.402951+00', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 14, NULL, false),
	('ce978972-4ed0-4fdb-9536-3aebaafd2d66', 'Scénario 1. La sorcière', '<p>Nos aventuriers sont détachés à la protection d''un chantier au Nord de Clairval, menacé par des incursions d''orques noirs. Alors qu''ils subissent une attaque particulièrement violente, les PJ sont secourus par une troupe de cavaliers menés par une femme chevalier en quête pour la Principauté d''Arly. Aylin doit s''aventurer dans le marais à la recherche d''un objet légendaire. Elle propose aux aventuriers, des compagnons de valeur, de l''accompagner dans son périple où de grands dangers l''attendent....</p>', '6e497cdc-5d8e-4434-821a-963d25c603a0', '2026-07-31 08:06:45.530693+00', 'c57e1f84-52a5-4f4b-945a-40c47977adae', 14, '0eb48584-ad9f-4691-ab0b-de4a6a6e21e2', false);
